insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (274, 27, 56, 69, 'سورة النمل ٥٦ – ٦٩', '«فما كان جواب قومه إلا أن قالوا أخرجوا آل لوط»، و«أمّن يجيب المضطر إذا دعاه»، و«قل لا يعلم من في السماوات والأرض الغيب إلا الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 274) = $j$[{"lbl": "الآيات ٥٦ – ٥٨", "q": "۞فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ لُوطٖ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ﴿٥٦﴾ فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَٰهَا مِنَ ٱلۡغَٰبِرِينَ ﴿٥٧﴾ وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ ﴿٥٨﴾", "w": [["فما كان جواب قومه", "لم يكن لهم جواب إلا قولهم: أخرجوا."], ["آل لوط", "لوط ﵇ وامرأته المؤمنة وابنتاه."], ["من قريتكم", "من مدينتكم سدوم."], ["يتطهّرون", "يتنزّهون عن الأقذار والأوساخ."], ["قدّرناها من الغابرين", "حكمنا عليها أن تكون من الهالكين."], ["فساء مطر المنذرين", "قبح مطر المنذَرين من أهل الجرائم، وهو حجارة من سجّيل."]], "m": "بعد أن أنكر لوط على قومه الفاحشة وقبّحها أجابوه مهدّدين بالطرد: أخرجوا آل لوط من قريتكم، إنهم أناس يتنزّهون عن الفواحش، قالوا ذلك تهكّماً لا إقراراً بأن الفاحشة قذر. ولما بلغ بهم الحد إلى تهديد نبي الله بالطرد والسخرية منه أهلكهم الله، وأنجى لوطاً وأهله إلا امرأته العجوز الكافرة، حكمنا ببقائها مع الكافرين لتهلك معهم. وأمطرنا عليهم حجارة من سجّيل، بعد أن جعل الله عالي بلادهم سافلها، لتصيب من كان بعيداً عن المدن، فقبح مطر المنذَرين الذين كذّبوا وأصرّوا على الكفر والمعاصي.", "h": ["بيان سنّة أن الظلمة إذا أعيتهم الحجج والبراهين يفزعون إلى القوة.", "بيان سنّة أن المرء إذا أدمن على قبح قول أو عمل يصبح غير قبيح عنده.", "سنّة إنجاء الله أولياءه وإهلاكه أعداءه بعد إصرار المنذَرين على الكفر والمعاصي."], "k": "«إنهم أناس يتطهّرون»… صار الطهر تهمة عند من أدمن القبح؛ فهل ألِفت قبحاً حتى لم أعد أراه؟"}, {"lbl": "الآيات ٥٩ – ٦٤", "q": "قُلِ ٱلۡحَمۡدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصۡطَفَىٰٓۗ ءَآللَّهُ خَيۡرٌ أَمَّا يُشۡرِكُونَ ﴿٥٩﴾ أَمَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءٗ فَأَنۢبَتۡنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهۡجَةٖ مَّا كَانَ لَكُمۡ أَن تُنۢبِتُواْ شَجَرَهَآۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ هُمۡ قَوۡمٞ يَعۡدِلُونَ ﴿٦٠﴾ أَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارٗا وَجَعَلَ خِلَٰلَهَآ أَنۡهَٰرٗا وَجَعَلَ لَهَا رَوَٰسِيَ وَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿٦١﴾ أَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قَلِيلٗا مَّا تَذَكَّرُونَ ﴿٦٢﴾ أَمَّن يَهۡدِيكُمۡ فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ وَمَن يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦٓۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ تَعَٰلَى ٱللَّهُ عَمَّا يُشۡرِكُونَ ﴿٦٣﴾ أَمَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ ﴿٦٤﴾", "w": [["اصطفى", "اختارهم لحمل رسالته وإبلاغ دعوته."], ["آلله خير", "لمن يعبده."], ["حدائق ذات بهجة", "بساتين ذات منظر حسن لخضرتها وأزهارها."], ["يعدلون", "يعدلون بربهم غيره من الأصنام والأوثان."], ["جعل الأرض قراراً", "قارّة ثابتة لا تضطرب بسكانها."], ["وجعل خلالها أنهاراً", "جعل الأنهار العذبة تتخلّلها للشرب والسقي."], ["وجعل لها رواسي", "جبالاً أرساها بها حتى لا تتحرك ولا تميل."], ["بين البحرين حاجزاً", "فاصلاً لا يختلط أحدهما بالآخر."], ["ويكشف السوء", "الضرّ من مرض وغيره."], ["قليلاً ما تذكّرون", "ما تتّعظون إلا قليلاً."], ["بشراً بين يدي رحمته", "مبشّرة بين يدي المطر."], ["هاتوا برهانكم", "حجتكم إن كنتم صادقين أن مع الله إلهاً آخر."]], "m": "لما أخبر الله بإهلاك المجرمين ونجاة المؤمنين أمر رسوله أن يحمده تعليماً له ولأمته أن يحمدوا الله إذا تجدّدت لهم نعمة: قل الحمد لله، وسلام على عباده الذين اصطفاهم لرسالته. آلله خير لمن يعبده أم ما يشركون؟ أمّن خلق السماوات والأرض، وأنزل لكم من السماء ماءً فأنبتنا به بساتين ذات حسن وجمال، ما كان في استطاعتكم أن تنبتوا شجرها؟ أإله مع الله؟ لا والله، بل هم قوم يسوّون به الأصنام. أمّن جعل الأرض ثابتة لا تضطرب بسكانها، وجعل خلالها أنهاراً، وجعل لها جبالاً تثبّتها، وجعل بين العذب والملح حاجزاً؟ بل أكثرهم لا يعلمون. أمّن يجيب المضطر إذا دعاه، ويكشف ما يسوء المرء من مرض وجوع وقحط، ويجعلكم خلفاء الأرض جيلاً بعد جيل؟ قليلاً ما تتّعظون. أمّن يهديكم في ظلمات البر والبحر بالنجوم والعلامات، ومن يرسل الرياح مبشّرة بالمطر؟ تعالى الله عما يشركون. أمّن يبدأ الخلق نطفاً في الأرحام ثم يعيده بعد موته، ومن يرزقكم من السماء بالمطر والأرض بالنبات؟ فإن قلتم إن مع الله آلهة فقل: هاتوا حجتكم إن كنتم صادقين.", "h": ["وجوب حمد الله وشكره عند تجدّد النعم، والحمد لله رأس الشكر.", "مشروعية السلام عند ذكر الأنبياء، فمن ذكر أحدهم قال: عليه السلام.", "التنديد بالشرك والمشركين.", "تقرير عقيدة البعث الآخر وإثباتها بالاستنباط من الأدلة المذكورة.", "لا تثبت الأحكام إلا بالأدلة النقلية والعقلية."], "k": "«أمّن يجيب المضطر إذا دعاه»… في ضيقي الأخير، لمن مددت يدي أولاً؟"}, {"lbl": "الآيات ٦٥ – ٦٩", "q": "قُل لَّا يَعۡلَمُ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلۡغَيۡبَ إِلَّا ٱللَّهُۚ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ ﴿٦٥﴾ بَلِ ٱدَّـٰرَكَ عِلۡمُهُمۡ فِي ٱلۡأٓخِرَةِۚ بَلۡ هُمۡ فِي شَكّٖ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ ﴿٦٦﴾ وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ أَءِذَا كُنَّا تُرَٰبٗا وَءَابَآؤُنَآ أَئِنَّا لَمُخۡرَجُونَ ﴿٦٧﴾ لَقَدۡ وُعِدۡنَا هَٰذَا نَحۡنُ وَءَابَآؤُنَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٦٨﴾ قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ ﴿٦٩﴾", "w": [["الغيب إلا الله", "ما غاب عنهم، ومن ذلك متى قيام الساعة، إلا الله فإنه يعلمه."], ["أيّان يبعثون", "متى يُبعثون."], ["بل ادّارك علمهم في الآخرة", "تلاحق، فما منهم أحد إلا يظن فقط، فلا علم لهم بالآخرة بالمرة."], ["بل هم منها عمون", "في عمى كامل لا يبصرون شيئاً من حقائقها."], ["أئنا لمخرجون", "أحياءً من قبورنا."], ["لقد وُعدنا هذا", "البعث أحياءً من القبور."], ["أساطير الأولين", "أكاذيبهم التي سطّروها في كتبهم."], ["كيف كان عاقبة المجرمين", "المكذّبين بالبعث، كانت دماراً وهلاكاً، وديارهم الخاوية شاهدة."]], "m": "لما سأل المشركون النبي ﷺ عن الساعة أمره الله أن يجيبهم: لا يعلم من في السماوات من الملائكة ومن في الأرض من الناس الغيب إلا الله، والساعة أعظم الغيب، وما يشعرون متى يُبعثون. بل تلاحق علمهم في الآخرة فلا علم لهم بها بالمرة، بل هم في شك منها، بل هم منها في عمى كامل. وقال الذين كفروا منكرين أشد الإنكار: أئذا كنا تراباً وآباؤنا أئنا لمخرجون أحياءً من قبورنا؟ لقد وُعدنا هذا نحن وآباؤنا من قبل، ما هذا إلا أكاذيب الأولين وحكاياتهم. قل لهم يا رسولنا: سيروا في الأرض فانظروا كيف كان عاقبة المجرمين، أهلكناهم لما كذّبوا بالبعث كما كذّبتم، فالقادر على خلقهم ثم إماتتهم قادر قطعاً على بعثهم.", "h": ["حصر علم الغيب في الرب تبارك وتعالى، فمن ادّعى أنه يعلم ما في غد فقد كذب.", "تساوي علم أهل السماء والأرض في الجهل بوقت قيام الساعة.", "المكذّبون بيوم القيامة سيوقنون به في الآخرة، ولكن لا ينفعهم ذلك.", "إهلاك الله الأمم المكذّبة بالبعث بعد خلقهم ورزقهم دليل على قدرته تعالى على بعثهم لحسابهم وجزائهم."], "k": "«وما يشعرون أيّان يُبعثون»… لا أعلم موعدي؛ فهل أعيش يومي كأنه قد يكون الأخير؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 274;
insert into public.tdb_cards(topic, i, body) select 274, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٦ – ٥٨", "q": "۞فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ لُوطٖ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ﴿٥٦﴾ فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَٰهَا مِنَ ٱلۡغَٰبِرِينَ ﴿٥٧﴾ وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ ﴿٥٨﴾", "w": [["فما كان جواب قومه", "لم يكن لهم جواب إلا قولهم: أخرجوا."], ["آل لوط", "لوط ﵇ وامرأته المؤمنة وابنتاه."], ["من قريتكم", "من مدينتكم سدوم."], ["يتطهّرون", "يتنزّهون عن الأقذار والأوساخ."], ["قدّرناها من الغابرين", "حكمنا عليها أن تكون من الهالكين."], ["فساء مطر المنذرين", "قبح مطر المنذَرين من أهل الجرائم، وهو حجارة من سجّيل."]], "m": "بعد أن أنكر لوط على قومه الفاحشة وقبّحها أجابوه مهدّدين بالطرد: أخرجوا آل لوط من قريتكم، إنهم أناس يتنزّهون عن الفواحش، قالوا ذلك تهكّماً لا إقراراً بأن الفاحشة قذر. ولما بلغ بهم الحد إلى تهديد نبي الله بالطرد والسخرية منه أهلكهم الله، وأنجى لوطاً وأهله إلا امرأته العجوز الكافرة، حكمنا ببقائها مع الكافرين لتهلك معهم. وأمطرنا عليهم حجارة من سجّيل، بعد أن جعل الله عالي بلادهم سافلها، لتصيب من كان بعيداً عن المدن، فقبح مطر المنذَرين الذين كذّبوا وأصرّوا على الكفر والمعاصي.", "h": ["بيان سنّة أن الظلمة إذا أعيتهم الحجج والبراهين يفزعون إلى القوة.", "بيان سنّة أن المرء إذا أدمن على قبح قول أو عمل يصبح غير قبيح عنده.", "سنّة إنجاء الله أولياءه وإهلاكه أعداءه بعد إصرار المنذَرين على الكفر والمعاصي."], "k": "«إنهم أناس يتطهّرون»… صار الطهر تهمة عند من أدمن القبح؛ فهل ألِفت قبحاً حتى لم أعد أراه؟"}, {"lbl": "الآيات ٥٩ – ٦٤", "q": "قُلِ ٱلۡحَمۡدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصۡطَفَىٰٓۗ ءَآللَّهُ خَيۡرٌ أَمَّا يُشۡرِكُونَ ﴿٥٩﴾ أَمَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءٗ فَأَنۢبَتۡنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهۡجَةٖ مَّا كَانَ لَكُمۡ أَن تُنۢبِتُواْ شَجَرَهَآۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ هُمۡ قَوۡمٞ يَعۡدِلُونَ ﴿٦٠﴾ أَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارٗا وَجَعَلَ خِلَٰلَهَآ أَنۡهَٰرٗا وَجَعَلَ لَهَا رَوَٰسِيَ وَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿٦١﴾ أَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قَلِيلٗا مَّا تَذَكَّرُونَ ﴿٦٢﴾ أَمَّن يَهۡدِيكُمۡ فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ وَمَن يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦٓۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ تَعَٰلَى ٱللَّهُ عَمَّا يُشۡرِكُونَ ﴿٦٣﴾ أَمَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ ﴿٦٤﴾", "w": [["اصطفى", "اختارهم لحمل رسالته وإبلاغ دعوته."], ["آلله خير", "لمن يعبده."], ["حدائق ذات بهجة", "بساتين ذات منظر حسن لخضرتها وأزهارها."], ["يعدلون", "يعدلون بربهم غيره من الأصنام والأوثان."], ["جعل الأرض قراراً", "قارّة ثابتة لا تضطرب بسكانها."], ["وجعل خلالها أنهاراً", "جعل الأنهار العذبة تتخلّلها للشرب والسقي."], ["وجعل لها رواسي", "جبالاً أرساها بها حتى لا تتحرك ولا تميل."], ["بين البحرين حاجزاً", "فاصلاً لا يختلط أحدهما بالآخر."], ["ويكشف السوء", "الضرّ من مرض وغيره."], ["قليلاً ما تذكّرون", "ما تتّعظون إلا قليلاً."], ["بشراً بين يدي رحمته", "مبشّرة بين يدي المطر."], ["هاتوا برهانكم", "حجتكم إن كنتم صادقين أن مع الله إلهاً آخر."]], "m": "لما أخبر الله بإهلاك المجرمين ونجاة المؤمنين أمر رسوله أن يحمده تعليماً له ولأمته أن يحمدوا الله إذا تجدّدت لهم نعمة: قل الحمد لله، وسلام على عباده الذين اصطفاهم لرسالته. آلله خير لمن يعبده أم ما يشركون؟ أمّن خلق السماوات والأرض، وأنزل لكم من السماء ماءً فأنبتنا به بساتين ذات حسن وجمال، ما كان في استطاعتكم أن تنبتوا شجرها؟ أإله مع الله؟ لا والله، بل هم قوم يسوّون به الأصنام. أمّن جعل الأرض ثابتة لا تضطرب بسكانها، وجعل خلالها أنهاراً، وجعل لها جبالاً تثبّتها، وجعل بين العذب والملح حاجزاً؟ بل أكثرهم لا يعلمون. أمّن يجيب المضطر إذا دعاه، ويكشف ما يسوء المرء من مرض وجوع وقحط، ويجعلكم خلفاء الأرض جيلاً بعد جيل؟ قليلاً ما تتّعظون. أمّن يهديكم في ظلمات البر والبحر بالنجوم والعلامات، ومن يرسل الرياح مبشّرة بالمطر؟ تعالى الله عما يشركون. أمّن يبدأ الخلق نطفاً في الأرحام ثم يعيده بعد موته، ومن يرزقكم من السماء بالمطر والأرض بالنبات؟ فإن قلتم إن مع الله آلهة فقل: هاتوا حجتكم إن كنتم صادقين.", "h": ["وجوب حمد الله وشكره عند تجدّد النعم، والحمد لله رأس الشكر.", "مشروعية السلام عند ذكر الأنبياء، فمن ذكر أحدهم قال: عليه السلام.", "التنديد بالشرك والمشركين.", "تقرير عقيدة البعث الآخر وإثباتها بالاستنباط من الأدلة المذكورة.", "لا تثبت الأحكام إلا بالأدلة النقلية والعقلية."], "k": "«أمّن يجيب المضطر إذا دعاه»… في ضيقي الأخير، لمن مددت يدي أولاً؟"}, {"lbl": "الآيات ٦٥ – ٦٩", "q": "قُل لَّا يَعۡلَمُ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلۡغَيۡبَ إِلَّا ٱللَّهُۚ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ ﴿٦٥﴾ بَلِ ٱدَّـٰرَكَ عِلۡمُهُمۡ فِي ٱلۡأٓخِرَةِۚ بَلۡ هُمۡ فِي شَكّٖ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ ﴿٦٦﴾ وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ أَءِذَا كُنَّا تُرَٰبٗا وَءَابَآؤُنَآ أَئِنَّا لَمُخۡرَجُونَ ﴿٦٧﴾ لَقَدۡ وُعِدۡنَا هَٰذَا نَحۡنُ وَءَابَآؤُنَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٦٨﴾ قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ ﴿٦٩﴾", "w": [["الغيب إلا الله", "ما غاب عنهم، ومن ذلك متى قيام الساعة، إلا الله فإنه يعلمه."], ["أيّان يبعثون", "متى يُبعثون."], ["بل ادّارك علمهم في الآخرة", "تلاحق، فما منهم أحد إلا يظن فقط، فلا علم لهم بالآخرة بالمرة."], ["بل هم منها عمون", "في عمى كامل لا يبصرون شيئاً من حقائقها."], ["أئنا لمخرجون", "أحياءً من قبورنا."], ["لقد وُعدنا هذا", "البعث أحياءً من القبور."], ["أساطير الأولين", "أكاذيبهم التي سطّروها في كتبهم."], ["كيف كان عاقبة المجرمين", "المكذّبين بالبعث، كانت دماراً وهلاكاً، وديارهم الخاوية شاهدة."]], "m": "لما سأل المشركون النبي ﷺ عن الساعة أمره الله أن يجيبهم: لا يعلم من في السماوات من الملائكة ومن في الأرض من الناس الغيب إلا الله، والساعة أعظم الغيب، وما يشعرون متى يُبعثون. بل تلاحق علمهم في الآخرة فلا علم لهم بها بالمرة، بل هم في شك منها، بل هم منها في عمى كامل. وقال الذين كفروا منكرين أشد الإنكار: أئذا كنا تراباً وآباؤنا أئنا لمخرجون أحياءً من قبورنا؟ لقد وُعدنا هذا نحن وآباؤنا من قبل، ما هذا إلا أكاذيب الأولين وحكاياتهم. قل لهم يا رسولنا: سيروا في الأرض فانظروا كيف كان عاقبة المجرمين، أهلكناهم لما كذّبوا بالبعث كما كذّبتم، فالقادر على خلقهم ثم إماتتهم قادر قطعاً على بعثهم.", "h": ["حصر علم الغيب في الرب تبارك وتعالى، فمن ادّعى أنه يعلم ما في غد فقد كذب.", "تساوي علم أهل السماء والأرض في الجهل بوقت قيام الساعة.", "المكذّبون بيوم القيامة سيوقنون به في الآخرة، ولكن لا ينفعهم ذلك.", "إهلاك الله الأمم المكذّبة بالبعث بعد خلقهم ورزقهم دليل على قدرته تعالى على بعثهم لحسابهم وجزائهم."], "k": "«وما يشعرون أيّان يُبعثون»… لا أعلم موعدي؛ فهل أعيش يومي كأنه قد يكون الأخير؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (275, 27, 70, 81, 'سورة النمل ٧٠ – ٨١', '«ولا تحزن عليهم ولا تكن في ضيق مما يمكرون»، و«إن هذا القرآن يقصّ على بني إسرائيل»، و«إنك لا تُسمع الموتى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 275) = $j$[{"lbl": "الآيات ٧٠ – ٧٥", "q": "وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُن فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ ﴿٧٠﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٧١﴾ قُلۡ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعۡضُ ٱلَّذِي تَسۡتَعۡجِلُونَ ﴿٧٢﴾ وَإِنَّ رَبَّكَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ ﴿٧٣﴾ وَإِنَّ رَبَّكَ لَيَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ ﴿٧٤﴾ وَمَا مِنۡ غَآئِبَةٖ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِلَّا فِي كِتَٰبٖ مُّبِينٍ ﴿٧٥﴾", "w": [["ولا تحزن عليهم", "المراد تسلية الرسول ﷺ."], ["مما يمكرون", "بك، إذ حاولوا قتلك ولم يفلحوا."], ["متى هذا الوعد", "بعذابنا."], ["ردف لكم بعض الذي تستعجلون", "اقترب منكم، وقد حصل لهم في بدر."], ["إن ربك لذو فضل على الناس", "في خلقهم ورزقهم وحفظهم وعدم إنزال العذاب بهم."], ["ما تكنّ صدورهم", "ما تخفيه وتستره صدورهم."], ["وما من غائبة", "ما من حادثة غائبة في السماء والأرض إلا وهي مكتوبة في اللوح المحفوظ."]], "m": "ما زال المشركون يعارضون بل ويمكرون، فنهى الله رسوله عن الحزن عليهم وعن ضيق صدره مما يمكرون ويكيدون له. ويقولون: متى هذا العذاب إن كنتم صادقين؟ قل: عسى أن يكون اقترب منكم بعض الذي تستعجلون، وهو ما حصل لهم في بدر من الأسر والقتل. وإن ربك لذو فضل على الناس مؤمنهم وكافرهم، خلقهم ورزقهم وعافاهم ولم يهلكهم بذنوبهم، ولكن أكثرهم لا يشكرون، فهم يستعجلون العذاب وهو يمهلهم لعلهم يتوبون، وهذا أعظم فضل. وإن ربك ليعلم ما تخفي صدورهم وما يعلنون، وسيحصي أعمالهم ويجزيهم بها، وما من غائبة في السماء والأرض إلا في كتاب مبين، هو اللوح المحفوظ، فعلمه أحاط بكل شيء، وهذا مستلزم للبعث والجزاء.", "h": ["تسلية الرسول ﷺ لأنه يعاني شدة من ظلم المشركين وإعراضهم.", "بيان تعنّت المشركين وعنادهم.", "تحقّق وعد الله للمشركين حيث نزل بهم بعض العذاب الذي يستعجلون.", "بيان فضل الله تعالى على الناس مع ترك أكثرهم لشكره سبحانه.", "بيان إحاطة علم الله بكل شيء.", "إثبات وتقرير كتاب المقادير، وهو اللوح المحفوظ."], "k": "«إن ربك لذو فضل على الناس ولكن أكثرهم لا يشكرون»… إمهاله لي فضل؛ فهل أستعمله في التوبة؟"}, {"lbl": "الآيات ٧٦ – ٨١", "q": "إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَقُصُّ عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَكۡثَرَ ٱلَّذِي هُمۡ فِيهِ يَخۡتَلِفُونَ ﴿٧٦﴾ وَإِنَّهُۥ لَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ﴿٧٧﴾ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُم بِحُكۡمِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡعَلِيمُ ﴿٧٨﴾ فَتَوَكَّلۡ عَلَى ٱللَّهِۖ إِنَّكَ عَلَى ٱلۡحَقِّ ٱلۡمُبِينِ ﴿٧٩﴾ إِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوۡاْ مُدۡبِرِينَ ﴿٨٠﴾ وَمَآ أَنتَ بِهَٰدِي ٱلۡعُمۡيِ عَن ضَلَٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن يُؤۡمِنُ بِـَٔايَٰتِنَا فَهُم مُّسۡلِمُونَ ﴿٨١﴾", "w": [["يقصّ على بني إسرائيل", "يذكر كثيراً مما اختلف فيه بنو إسرائيل."], ["هدى ورحمة للمؤمنين", "به تتم هداية المؤمنين ورحمتهم."], ["يقضي بينهم بحكمه", "يحكم بينهم بحكمه العادل."], ["وهو العزيز العليم", "الغالب على أمره، العليم بخلقه."], ["فتوكّل على الله", "ثق فيه وفوّض أمرك إليه."], ["إنك لا تُسمع الموتى", "لا تقدر على إسماعهم ولو أردت، لأنهم موتى."], ["ولا تُسمع الصمّ الدعاء", "ولا تقدر على إسماع الصمّ الذين فقدوا حاسة السمع."], ["إذا ولّوا مدبرين", "إذا رجعوا مدبرين عنك غير ملتفتين إليك."], ["إن تُسمع إلا من يؤمن بآياتنا", "ما تُسمع إلا من يؤمن بآيات الله."]], "m": "إن هذا القرآن يقصّ على بني إسرائيل المعاصرين لنزوله أكثر الذي هم فيه يختلفون، كاختلافهم في عيسى ﵇ وأمه إذ غلا فيهما بعضهم وفرّط آخرون فطعنوا فيهما، وكاختلافهم في صفات الله وحقيقة المعاد، وفي مسائل شرعية وتاريخية. وإنه لهدى ورحمة للمؤمنين العاملين بما فيه. إن ربك يقضي بين الناس يوم القيامة بحكمه العادل، وهو العزيز الذي ينفذ حكمه، العليم بالمحقّين من المبطلين، فتوكّل على الله وفوّض أمرك إليه، إنك على الحق المبين، فالعاقبة الحسنى لك. إنك لا تُسمع الموتى، والكفار موتى لخلوّ أجسامهم من روح الإيمان، ولا تُسمع الصمّ الدعاء إذا ولّوا مدبرين، وما أنت بهادي العمي عن ضلالتهم، فهوّن على نفسك، إن تُسمع سماع فهم وقبول إلا من يؤمن بآياتنا فهم منقادون لشرع الله.", "h": ["شرف القرآن وفضله.", "لن ينتهي خلاف اليهود والنصارى إلا بالإسلام، فإذا أسلموا اهتدوا للحق.", "كل خلاف بين الناس اليوم سيحكم الله تعالى بين أهله يوم القيامة بحكمه العادل، وهو العزيز العليم.", "الكفار أموات لخلوّ أبدانهم من روح الإيمان، فلذا هم لا يسمعون الهدى ولا يبصرون الآيات مهما كانت واضحات، فعلى داعيهم أن يعرف هذا فيهم ويصبر على دعوتهم."], "k": "«إن تُسمع إلا من يؤمن بآياتنا»… السماع الحق يحتاج قلباً حياً؛ فهل يسمع قلبي ما يُتلى عليّ؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 275;
