insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (276, 27, 82, 93, 'سورة النمل ٨٢ – ٩٣', '«وإذا وقع القول عليهم أخرجنا لهم دابة من الأرض»، و«ويوم يُنفخ في الصور»، و«من جاء بالحسنة فله خير منها»، و«إنما أُمرت أن أعبد رب هذه البلدة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 276) = $j$[{"lbl": "الآيات ٨٢ – ٨٦", "q": "۞وَإِذَا وَقَعَ ٱلۡقَوۡلُ عَلَيۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَآبَّةٗ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ ٱلنَّاسَ كَانُواْ بِـَٔايَٰتِنَا لَا يُوقِنُونَ ﴿٨٢﴾ وَيَوۡمَ نَحۡشُرُ مِن كُلِّ أُمَّةٖ فَوۡجٗا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمۡ يُوزَعُونَ ﴿٨٣﴾ حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبۡتُم بِـَٔايَٰتِي وَلَمۡ تُحِيطُواْ بِهَا عِلۡمًا أَمَّاذَا كُنتُمۡ تَعۡمَلُونَ ﴿٨٤﴾ وَوَقَعَ ٱلۡقَوۡلُ عَلَيۡهِم بِمَا ظَلَمُواْ فَهُمۡ لَا يَنطِقُونَ ﴿٨٥﴾ أَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا ٱلَّيۡلَ لِيَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٨٦﴾", "w": [["وقع القول عليهم", "حقّ عليهم العذاب."], ["دابة من الأرض", "حيوان يدبّ على الأرض، لم يرد وصفها في حديث صحيح يُعوّل عليه."], ["تكلّمهم", "بلسان يفهمونه لأنها آية من الآيات."], ["أن الناس كانوا بآياتنا لا يوقنون", "بسبب أن الناس أصبحوا لا يؤمنون بآيات الله وشرائعه."], ["ويوم نحشر", "اذكر يوم نجمع."], ["من كل أمة فوجاً", "طائفة، وهم الرؤساء المتبوعون في الدنيا."], ["فهم يوزعون", "يُجمعون برد أولهم على آخرهم."], ["بما ظلموا", "بسبب ظلمهم، وهو شركهم بالله."], ["فهم لا ينطقون", "لا حجة لهم."], ["والنهار مبصراً", "يُبصر فيه من أجل التصرّف في الأعمال."]], "m": "وإذا حقّ العذاب على الكافرين، حيث لم يبق في الأرض من يأمر بمعروف ولا من ينهى عن منكر، أخرجنا لهم دابة من الأرض تكلّمهم بلسان يفهمونه، بسبب أن الناس كفروا وما عادوا يوقنون بآيات الله، ومن حِكمها أن بها يتميّز المؤمن من الكافر. واذكر يوم نحشر من كل أمة جماعة ممن يكذّب بآياتنا، فهم يُساقون بانتظام، حتى إذا جاؤوا موضع الحساب قال الله لهم تقريعاً: أكذّبتم بآياتي ولم تحيطوا بها علماً؟ إذ لا يجوز للإنسان أن يكذّب بشيء لمجرد أنه لم يعرفه، أم ماذا كنتم تعملون؟ ووجب عليهم العذاب بسبب ظلمهم، فهم لا ينطقون بحجة. ألم يروا أنّا جعلنا الليل ليسكنوا فيه، وسكونهم بالنوم شبيه بالموت، والنهار مبصراً ينصرفون فيه للعمل، وانبعاثهم فيه شبيه بالحياة، فكيف ينكر العقلاء البعث وله صورة متكررة كل يوم؟ إن في ذلك لآيات لقوم يؤمنون، لأنهم أحياء يسمعون ويبصرون ويفكّرون.", "h": ["تأكيد آية الدابة، وذلك يوم لا يبقى من يأمر بالمعروف ولا من ينهى عن المنكر، فيحقّ العذاب على الكافرين.", "تقرير عقيدة البعث والجزاء بذكر وصف لها.", "ويل لرؤساء الضلالة والشر والشرك والباطل، إذ يُؤتى بهم ويُسألون.", "في آية الليل والنهار ما يدل بوضوح على عقيدة البعث الآخر والحساب والجزاء."], "k": "«أكذّبتم بآياتي ولم تحيطوا بها علماً»… كم مرة رددت شيئاً لمجرد أني لم أعرفه؟"}, {"lbl": "الآيات ٨٧ – ٩٠", "q": "وَيَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَفَزِعَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۚ وَكُلٌّ أَتَوۡهُ دَٰخِرِينَ ﴿٨٧﴾ وَتَرَى ٱلۡجِبَالَ تَحۡسَبُهَا جَامِدَةٗ وَهِيَ تَمُرُّ مَرَّ ٱلسَّحَابِۚ صُنۡعَ ٱللَّهِ ٱلَّذِيٓ أَتۡقَنَ كُلَّ شَيۡءٍۚ إِنَّهُۥ خَبِيرُۢ بِمَا تَفۡعَلُونَ ﴿٨٨﴾ مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَا وَهُم مِّن فَزَعٖ يَوۡمَئِذٍ ءَامِنُونَ ﴿٨٩﴾ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتۡ وُجُوهُهُمۡ فِي ٱلنَّارِ هَلۡ تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ﴿٩٠﴾", "w": [["ويوم يُنفخ في الصور", "ينفخ إسرافيل في البوق نفخة الفزع والفناء، ثم القيام من القبور."], ["وكلٌّ أتوه داخرين", "أتوا الله أذلاء صاغرين."], ["وترى الجبال تحسبها جامدة", "تظنها في نظر العين جامدة."], ["وهي تمرّ مرّ السحاب", "لسرعة تسييرها."], ["من جاء بالحسنة", "وهي الإيمان والتوحيد وسائر الصالحات."], ["فله خير منها", "الجنة."], ["وهم من فزع يومئذ آمنون", "أصحاب حسنات التوحيد والعمل الصالح آمنون من هول يوم القيامة."], ["ومن جاء بالسيئة", "كالشرك وأكل الربا وقتل النفس."], ["فكُبّت وجوههم في النار", "أُلقوا فيها على وجوههم، والعياذ بالله."], ["هل تُجزون إلا ما كنتم تعملون", "ما تُجزون إلا بعملكم، لا بعمل غيركم."]], "m": "ما زال السياق في أحداث القيامة تقريراً للبعث والجزاء الباعث على الاستقامة: ويوم ينفخ إسرافيل في الصور ففزع من في السماوات ومن في الأرض إلا من شاء الله، وهم الشهداء، وهي نفخة الفزع والفناء، وكلٌّ أتوا الله إلى المحشر أذلاء صاغرين. وترى الجبال تحسبها جامدة لا تتحرك وهي تمرّ مرّ السحاب لسرعة تسييرها، صنع الله الذي أتقن كل شيء وأحكمه، إنه خبير بما تفعلون وسيجزيكم بحسب علمه. من جاء بالإيمان والعمل الصالح فله خير منها، وهي الجنة، وهم من فزع ذلك اليوم آمنون، ومن جاء بالشرك والمعاصي فكُبّت وجوههم في النار: هل تُجزون إلا ما كنتم تعملون؟", "h": ["تقرير عقيدة البعث والجزاء بذكر أحداثها مفصّلة.", "بيان كيفية خراب العوالم وفناء الأكوان.", "فضل الشهداء، حيث لا يحزنهم الفزع الأكبر وهم آمنون.", "تقرير مبدأ الجزاء، وهو الحسنة والسيئة: حسنة التوحيد وسيئة الشرك."], "k": "«وهم من فزع يومئذ آمنون»… أمان ذلك اليوم يُشترى بحسنات اليوم؛ فما حسنتي الآن؟"}, {"lbl": "الآيات ٩١ – ٩٣", "q": "إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ رَبَّ هَٰذِهِ ٱلۡبَلۡدَةِ ٱلَّذِي حَرَّمَهَا وَلَهُۥ كُلُّ شَيۡءٖۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ ﴿٩١﴾ وَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَقُلۡ إِنَّمَآ أَنَا۠ مِنَ ٱلۡمُنذِرِينَ ﴿٩٢﴾ وَقُلِ ٱلۡحَمۡدُ لِلَّهِ سَيُرِيكُمۡ ءَايَٰتِهِۦ فَتَعۡرِفُونَهَاۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ﴿٩٣﴾", "w": [["هذه البلدة", "مكة المكرمة، والإضافة للتشريف."], ["الذي حرّمها", "الله الذي حرّم مكة، فلا يُختلى خلاها ولا يُنفّر صيدها ولا يُقاتل فيها."], ["من المسلمين", "المنقادين له ظاهراً وباطناً، وهم أشرف الخلق."], ["وأن أتلو القرآن", "أمرني أن أقرأ القرآن إنذاراً وتعليماً وتعبّداً."], ["سيريكم آياته", "مدلول آيات الوعيد، وقد أراهموه في بدر، وسيرونه عند الموت."], ["وما ربك بغافل عما تعملون", "وسيجزيهم بأعمالهم."]], "m": "بعد ذلك العرض الهائل لأحداث القيامة، ولم يؤمن أكثر القوم، ناسب بيان موقف الرسول ﷺ: إنما أُمرت أن أعبد رب هذه البلدة الذي حرّمها، فلا يُقاتل فيها ولا يُصاد صيدها ولا يُختلى خلاها ولا تُلتقط لقطتها إلا لمن يعرّفها، وله كل شيء خلقاً وملكاً وتصرفاً. وأُمرت أن أكون من المنقادين لله، وأن أتلو القرآن تلاوة إنذار وتعليم وتعبّد، فمن اهتدى فإنما يعود نفع هدايته عليه، ومن ضلّ فقل: إنما أنا من المنذرين، لا من واهبي الهداية. وقل الحمد لله على نعمه التي لا تُحصى، ومن أجلّها الرسالة، سيريكم آياته فتعرفونها، وقد أراهم أول آية في بدر، وثانيها في الفتح، وآخرها عند الموت يوم تضرب الملائكة وجوههم وأدبارهم. وما ربك بغافل عما تعملون، ففي الآية وعد ووعيد.", "h": ["بيان وظيفة الرسول ﷺ، وأنها عبادة الله والإسلام له، وتلاوة القرآن إنذاراً وتعليماً وتعبّداً.", "بيان وتقرير حرمة مكة المكرمة والحرم.", "الندب إلى حمد الله تعالى على نعمه الظاهرة والباطنة، ولا سيما عند تجدّد النعمة.", "بيان أن عوائد الكسب عائدة على الكاسب، خيراً كانت أو شراً.", "بيان معجزة القرآن، إذ ما أعلم به المشركين أنهم سيرونه قد رأوه فعلاً."], "k": "«وأن أتلو القرآن»… أُمر النبي ﷺ بالتلاوة كما أُمر بالعبادة؛ فهل تلاوتي عبادة أم عادة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 276;
insert into public.tdb_cards(topic, i, body) select 276, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٢ – ٨٦", "q": "۞وَإِذَا وَقَعَ ٱلۡقَوۡلُ عَلَيۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَآبَّةٗ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ ٱلنَّاسَ كَانُواْ بِـَٔايَٰتِنَا لَا يُوقِنُونَ ﴿٨٢﴾ وَيَوۡمَ نَحۡشُرُ مِن كُلِّ أُمَّةٖ فَوۡجٗا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمۡ يُوزَعُونَ ﴿٨٣﴾ حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبۡتُم بِـَٔايَٰتِي وَلَمۡ تُحِيطُواْ بِهَا عِلۡمًا أَمَّاذَا كُنتُمۡ تَعۡمَلُونَ ﴿٨٤﴾ وَوَقَعَ ٱلۡقَوۡلُ عَلَيۡهِم بِمَا ظَلَمُواْ فَهُمۡ لَا يَنطِقُونَ ﴿٨٥﴾ أَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا ٱلَّيۡلَ لِيَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٨٦﴾", "w": [["وقع القول عليهم", "حقّ عليهم العذاب."], ["دابة من الأرض", "حيوان يدبّ على الأرض، لم يرد وصفها في حديث صحيح يُعوّل عليه."], ["تكلّمهم", "بلسان يفهمونه لأنها آية من الآيات."], ["أن الناس كانوا بآياتنا لا يوقنون", "بسبب أن الناس أصبحوا لا يؤمنون بآيات الله وشرائعه."], ["ويوم نحشر", "اذكر يوم نجمع."], ["من كل أمة فوجاً", "طائفة، وهم الرؤساء المتبوعون في الدنيا."], ["فهم يوزعون", "يُجمعون برد أولهم على آخرهم."], ["بما ظلموا", "بسبب ظلمهم، وهو شركهم بالله."], ["فهم لا ينطقون", "لا حجة لهم."], ["والنهار مبصراً", "يُبصر فيه من أجل التصرّف في الأعمال."]], "m": "وإذا حقّ العذاب على الكافرين، حيث لم يبق في الأرض من يأمر بمعروف ولا من ينهى عن منكر، أخرجنا لهم دابة من الأرض تكلّمهم بلسان يفهمونه، بسبب أن الناس كفروا وما عادوا يوقنون بآيات الله، ومن حِكمها أن بها يتميّز المؤمن من الكافر. واذكر يوم نحشر من كل أمة جماعة ممن يكذّب بآياتنا، فهم يُساقون بانتظام، حتى إذا جاؤوا موضع الحساب قال الله لهم تقريعاً: أكذّبتم بآياتي ولم تحيطوا بها علماً؟ إذ لا يجوز للإنسان أن يكذّب بشيء لمجرد أنه لم يعرفه، أم ماذا كنتم تعملون؟ ووجب عليهم العذاب بسبب ظلمهم، فهم لا ينطقون بحجة. ألم يروا أنّا جعلنا الليل ليسكنوا فيه، وسكونهم بالنوم شبيه بالموت، والنهار مبصراً ينصرفون فيه للعمل، وانبعاثهم فيه شبيه بالحياة، فكيف ينكر العقلاء البعث وله صورة متكررة كل يوم؟ إن في ذلك لآيات لقوم يؤمنون، لأنهم أحياء يسمعون ويبصرون ويفكّرون.", "h": ["تأكيد آية الدابة، وذلك يوم لا يبقى من يأمر بالمعروف ولا من ينهى عن المنكر، فيحقّ العذاب على الكافرين.", "تقرير عقيدة البعث والجزاء بذكر وصف لها.", "ويل لرؤساء الضلالة والشر والشرك والباطل، إذ يُؤتى بهم ويُسألون.", "في آية الليل والنهار ما يدل بوضوح على عقيدة البعث الآخر والحساب والجزاء."], "k": "«أكذّبتم بآياتي ولم تحيطوا بها علماً»… كم مرة رددت شيئاً لمجرد أني لم أعرفه؟"}, {"lbl": "الآيات ٨٧ – ٩٠", "q": "وَيَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَفَزِعَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۚ وَكُلٌّ أَتَوۡهُ دَٰخِرِينَ ﴿٨٧﴾ وَتَرَى ٱلۡجِبَالَ تَحۡسَبُهَا جَامِدَةٗ وَهِيَ تَمُرُّ مَرَّ ٱلسَّحَابِۚ صُنۡعَ ٱللَّهِ ٱلَّذِيٓ أَتۡقَنَ كُلَّ شَيۡءٍۚ إِنَّهُۥ خَبِيرُۢ بِمَا تَفۡعَلُونَ ﴿٨٨﴾ مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَا وَهُم مِّن فَزَعٖ يَوۡمَئِذٍ ءَامِنُونَ ﴿٨٩﴾ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتۡ وُجُوهُهُمۡ فِي ٱلنَّارِ هَلۡ تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ﴿٩٠﴾", "w": [["ويوم يُنفخ في الصور", "ينفخ إسرافيل في البوق نفخة الفزع والفناء، ثم القيام من القبور."], ["وكلٌّ أتوه داخرين", "أتوا الله أذلاء صاغرين."], ["وترى الجبال تحسبها جامدة", "تظنها في نظر العين جامدة."], ["وهي تمرّ مرّ السحاب", "لسرعة تسييرها."], ["من جاء بالحسنة", "وهي الإيمان والتوحيد وسائر الصالحات."], ["فله خير منها", "الجنة."], ["وهم من فزع يومئذ آمنون", "أصحاب حسنات التوحيد والعمل الصالح آمنون من هول يوم القيامة."], ["ومن جاء بالسيئة", "كالشرك وأكل الربا وقتل النفس."], ["فكُبّت وجوههم في النار", "أُلقوا فيها على وجوههم، والعياذ بالله."], ["هل تُجزون إلا ما كنتم تعملون", "ما تُجزون إلا بعملكم، لا بعمل غيركم."]], "m": "ما زال السياق في أحداث القيامة تقريراً للبعث والجزاء الباعث على الاستقامة: ويوم ينفخ إسرافيل في الصور ففزع من في السماوات ومن في الأرض إلا من شاء الله، وهم الشهداء، وهي نفخة الفزع والفناء، وكلٌّ أتوا الله إلى المحشر أذلاء صاغرين. وترى الجبال تحسبها جامدة لا تتحرك وهي تمرّ مرّ السحاب لسرعة تسييرها، صنع الله الذي أتقن كل شيء وأحكمه، إنه خبير بما تفعلون وسيجزيكم بحسب علمه. من جاء بالإيمان والعمل الصالح فله خير منها، وهي الجنة، وهم من فزع ذلك اليوم آمنون، ومن جاء بالشرك والمعاصي فكُبّت وجوههم في النار: هل تُجزون إلا ما كنتم تعملون؟", "h": ["تقرير عقيدة البعث والجزاء بذكر أحداثها مفصّلة.", "بيان كيفية خراب العوالم وفناء الأكوان.", "فضل الشهداء، حيث لا يحزنهم الفزع الأكبر وهم آمنون.", "تقرير مبدأ الجزاء، وهو الحسنة والسيئة: حسنة التوحيد وسيئة الشرك."], "k": "«وهم من فزع يومئذ آمنون»… أمان ذلك اليوم يُشترى بحسنات اليوم؛ فما حسنتي الآن؟"}, {"lbl": "الآيات ٩١ – ٩٣", "q": "إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ رَبَّ هَٰذِهِ ٱلۡبَلۡدَةِ ٱلَّذِي حَرَّمَهَا وَلَهُۥ كُلُّ شَيۡءٖۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ ﴿٩١﴾ وَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَقُلۡ إِنَّمَآ أَنَا۠ مِنَ ٱلۡمُنذِرِينَ ﴿٩٢﴾ وَقُلِ ٱلۡحَمۡدُ لِلَّهِ سَيُرِيكُمۡ ءَايَٰتِهِۦ فَتَعۡرِفُونَهَاۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ﴿٩٣﴾", "w": [["هذه البلدة", "مكة المكرمة، والإضافة للتشريف."], ["الذي حرّمها", "الله الذي حرّم مكة، فلا يُختلى خلاها ولا يُنفّر صيدها ولا يُقاتل فيها."], ["من المسلمين", "المنقادين له ظاهراً وباطناً، وهم أشرف الخلق."], ["وأن أتلو القرآن", "أمرني أن أقرأ القرآن إنذاراً وتعليماً وتعبّداً."], ["سيريكم آياته", "مدلول آيات الوعيد، وقد أراهموه في بدر، وسيرونه عند الموت."], ["وما ربك بغافل عما تعملون", "وسيجزيهم بأعمالهم."]], "m": "بعد ذلك العرض الهائل لأحداث القيامة، ولم يؤمن أكثر القوم، ناسب بيان موقف الرسول ﷺ: إنما أُمرت أن أعبد رب هذه البلدة الذي حرّمها، فلا يُقاتل فيها ولا يُصاد صيدها ولا يُختلى خلاها ولا تُلتقط لقطتها إلا لمن يعرّفها، وله كل شيء خلقاً وملكاً وتصرفاً. وأُمرت أن أكون من المنقادين لله، وأن أتلو القرآن تلاوة إنذار وتعليم وتعبّد، فمن اهتدى فإنما يعود نفع هدايته عليه، ومن ضلّ فقل: إنما أنا من المنذرين، لا من واهبي الهداية. وقل الحمد لله على نعمه التي لا تُحصى، ومن أجلّها الرسالة، سيريكم آياته فتعرفونها، وقد أراهم أول آية في بدر، وثانيها في الفتح، وآخرها عند الموت يوم تضرب الملائكة وجوههم وأدبارهم. وما ربك بغافل عما تعملون، ففي الآية وعد ووعيد.", "h": ["بيان وظيفة الرسول ﷺ، وأنها عبادة الله والإسلام له، وتلاوة القرآن إنذاراً وتعليماً وتعبّداً.", "بيان وتقرير حرمة مكة المكرمة والحرم.", "الندب إلى حمد الله تعالى على نعمه الظاهرة والباطنة، ولا سيما عند تجدّد النعمة.", "بيان أن عوائد الكسب عائدة على الكاسب، خيراً كانت أو شراً.", "بيان معجزة القرآن، إذ ما أعلم به المشركين أنهم سيرونه قد رأوه فعلاً."], "k": "«وأن أتلو القرآن»… أُمر النبي ﷺ بالتلاوة كما أُمر بالعبادة؛ فهل تلاوتي عبادة أم عادة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (277, 28, 1, 11, 'سورة القصص ١ – ١١', '«إن فرعون علا في الأرض وجعل أهلها شيعاً»، و«ونريد أن نمنّ على الذين استضعفوا»، و«وأوحينا إلى أم موسى أن أرضعيه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 277) = $j$[{"lbl": "الآيات ١ – ٦", "q": "طسٓمٓ ﴿١﴾ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿٢﴾ نَتۡلُواْ عَلَيۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمٖ يُؤۡمِنُونَ ﴿٣﴾ إِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا يَسۡتَضۡعِفُ طَآئِفَةٗ مِّنۡهُمۡ يُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ ﴿٤﴾ وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسۡتُضۡعِفُواْ فِي ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَئِمَّةٗ وَنَجۡعَلَهُمُ ٱلۡوَٰرِثِينَ ﴿٥﴾ وَنُمَكِّنَ لَهُمۡ فِي ٱلۡأَرۡضِ وَنُرِيَ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُواْ يَحۡذَرُونَ ﴿٦﴾", "w": [["طسم", "تُكتب طسم وتُقرأ: طا سين ميم."], ["تلك", "الآيات المؤلّفة من مثل هذه الحروف هي آيات القرآن."], ["نتلو عليك", "نقرأ عليك قاصّين شيئاً من خبر موسى وفرعون."], ["لقوم يؤمنون", "لأجل المؤمنين، ليزدادوا إيماناً ويوقنوا بالنصر وحسن العاقبة."], ["علا في الأرض", "تكبّر وظلم، فادّعى الربوبية وظلم بني إسرائيل ظلماً فظيعاً."], ["شيعاً", "طوائف بعضهم عدو لبعض، من باب: فرّق تسُد."], ["ويستحيي نساءهم", "يُبقي البنات لأنه لا يخاف منهن، ويذبح الأولاد لخوفه على ملكه منهم."], ["ونريد أن نمنّ", "ننعم على الذين استضعفوا فنجعلهم أئمة ونجعلهم الوارثين."], ["ما كانوا يحذرون", "من المولود الذي يولد في بني إسرائيل فيذهب بملكهم."]], "m": "طسم، الله أعلم بمراده منه، وفيه فائدتان: إعجاز القرآن المؤلّف من مثل هذه الحروف، واضطرار المشركين إلى السماع لغرابتها عندهم، فإذا ألقى أحدهم سمعه نفذ القرآن إلى قلبه. تلك آيات القرآن المبين، نقرأ عليك من خبر موسى وفرعون بالحق لقوم يؤمنون، لأنهم المنتفعون به، وهم في ظرف صعب يحتاجون فيه إلى مثل هذا القصص ليثبتوا. إن فرعون طغى وتكبّر في أرض مصر، وجعل أهلها طوائف فرّق بينها إبقاءً على ملكه، يستضعف طائفة منهم، بني إسرائيل، يذبح أبناءهم ساعة ولادتهم ويستبقي بناتهم للخدمة، لأن كهّانه وسياسيّيه أعلموه أن ملكه مهدّد بهم، فاستعمل طريقة تقليلهم، وهي سياسة تشبه تحديد النسل الذي يستعمله بعض الحاكمين اليوم، إنه كان من المفسدين. ونريد أن ننعم على المستضعفين من بني إسرائيل بالإيمان وتخليصهم من حكم فرعون، ونجعلهم قادة في الخير، ونجعلهم الوارثين لحكم البلاد، ونمكّن لهم فيها، ونُري فرعون وهامان وجنودهما منهم ما كانوا يحذرون من مولود يذهب بملكهم.", "h": ["تقرير إعجاز القرآن الذي هو آية أنه كتاب الله حقاً.", "تقرير النبوة المحمدية بهذا الوحي الإلهي.", "التحذير من الظلم والاستطالة على الناس والفساد في الأرض.", "المؤمنون هم الذين ينتفعون بما يُتلى عليهم لحياة قلوبهم.", "تقرير قاعدة: لا حذر مع القدر.", "تحريم تحديد النسل بإلزام المواطن بألا يزيد على عدد معين من الأطفال."], "k": "«ونريد أن نمنّ على الذين استضعفوا»… حين أشعر بالضعف، هل أتذكّر أن إرادة الله فوق كل قوة؟"}, {"lbl": "الآيات ٧ – ١١", "q": "وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ ﴿٧﴾ فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ ﴿٨﴾ وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ ﴿٩﴾ وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿١٠﴾ وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبٖ وَهُمۡ لَا يَشۡعُرُونَ ﴿١١﴾", "w": [["وأوحينا إلى أم موسى", "أعلمناها أن ترضع ولدها، ثم تضعه في تابوت فتلقيه في اليم."], ["في اليم", "في البحر، وهو نهر النيل."], ["ولا تخافي ولا تحزني", "لا تخافي عليه الهلاك، ولا تحزني على فراقه."], ["فالتقطه آل فرعون", "أعوانه ورجاله."], ["ليكون لهم عدواً وحزناً", "في عاقبة الأمر، فاللام للعاقبة والصيرورة."], ["قرّة عين لي ولك", "تقرّ به عيني وعينك فنفرح به."], ["وأصبح فؤاد أم موسى فارغاً", "من كل شيء إلا منه."], ["إن كادت لتُبدي به", "قاربت أن تصرخ أنه ولدها."], ["وقالت لأخته قصّيه", "اتّبعي أثره حتى تعرفي أين هو."], ["فبصرت به عن جُنُب", "لاحظته وهي مختفية تتبعه من مكان بعيد."]], "m": "هذه بداية قصة موسى مع فرعون، من طفولته رضيعاً إلى هلاك فرعون: وأوحينا إلى أم موسى إلهاماً: أن أرضعيه، فإذا خفت عليه من آل فرعون الذين يقتلون مواليد بني إسرائيل الذكور فاجعليه في صندوق وألقيه في النيل، ولا تخافي عليه الهلاك ولا تحزني على فراقه، إنا رادّوه إليك وجاعلوه من المرسلين. ففعلت، فالتقطه آل فرعون وأعطوه لآسية امرأة فرعون، ليكون لهم في عاقبة الأمر عدواً وحزناً، إن فرعون وهامان وجنودهما كانوا آثمين. وقالت امرأة فرعون حين همّ بقتله: قرّة عين لي ولك، لا تقتلوه، عسى أن ينفعنا أو نتخذه ولداً، فكان موسى إلى الثلاثين من عمره يُعرف بابن فرعون، وهم لا يشعرون بأن هلاكهم سيكون على يده. وأصبح فؤاد أم موسى فارغاً إلا منه، إن كادت لتصرخ بأنه ولدها من شدة الحزن، لولا أن ربط الله على قلبها لتكون من المؤمنين بوعده. وقالت لأخته: تتبّعي أثره، فرأته من بُعد تمشي على شاطئ النهر حتى علمت أنه دخل القصر، وهم لا يشعرون أنها أخته.", "h": ["بيان تدبير الله تعالى لأوليائه وصالحي عباده، وتجلّى ذلك في الوحي إلى أم موسى وإلقائه في البحر والتقاط آل فرعون له ليتربّى في بيت الملك عزيزاً مكرماً.", "بيان سوء الخطيئة وآثارها السيئة وعواقبها المدمّرة، وتجلّى ذلك فيما حلّ بفرعون وهامان.", "فضيلة الرجاء، تجلّت في قول آسية: «قرّة عين لي ولك»، فكان موسى قرة عين لآسية ولم يكن لفرعون.", "بيان عاطفة الأمومة، حيث أصبح فؤاد أم موسى فارغاً إلا من موسى.", "بيان عناية الله بأوليائه، حيث ربط على قلب أم موسى فصبرت ولم تُبده لهم."], "k": "«لولا أن ربطنا على قلبها»… الصبر ليس من عندي بل رباط من الله؛ فهل أسأله أن يربط على قلبي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 277;
insert into public.tdb_cards(topic, i, body) select 277, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "طسٓمٓ ﴿١﴾ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿٢﴾ نَتۡلُواْ عَلَيۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمٖ يُؤۡمِنُونَ ﴿٣﴾ إِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا يَسۡتَضۡعِفُ طَآئِفَةٗ مِّنۡهُمۡ يُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ ﴿٤﴾ وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسۡتُضۡعِفُواْ فِي ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَئِمَّةٗ وَنَجۡعَلَهُمُ ٱلۡوَٰرِثِينَ ﴿٥﴾ وَنُمَكِّنَ لَهُمۡ فِي ٱلۡأَرۡضِ وَنُرِيَ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُواْ يَحۡذَرُونَ ﴿٦﴾", "w": [["طسم", "تُكتب طسم وتُقرأ: طا سين ميم."], ["تلك", "الآيات المؤلّفة من مثل هذه الحروف هي آيات القرآن."], ["نتلو عليك", "نقرأ عليك قاصّين شيئاً من خبر موسى وفرعون."], ["لقوم يؤمنون", "لأجل المؤمنين، ليزدادوا إيماناً ويوقنوا بالنصر وحسن العاقبة."], ["علا في الأرض", "تكبّر وظلم، فادّعى الربوبية وظلم بني إسرائيل ظلماً فظيعاً."], ["شيعاً", "طوائف بعضهم عدو لبعض، من باب: فرّق تسُد."], ["ويستحيي نساءهم", "يُبقي البنات لأنه لا يخاف منهن، ويذبح الأولاد لخوفه على ملكه منهم."], ["ونريد أن نمنّ", "ننعم على الذين استضعفوا فنجعلهم أئمة ونجعلهم الوارثين."], ["ما كانوا يحذرون", "من المولود الذي يولد في بني إسرائيل فيذهب بملكهم."]], "m": "طسم، الله أعلم بمراده منه، وفيه فائدتان: إعجاز القرآن المؤلّف من مثل هذه الحروف، واضطرار المشركين إلى السماع لغرابتها عندهم، فإذا ألقى أحدهم سمعه نفذ القرآن إلى قلبه. تلك آيات القرآن المبين، نقرأ عليك من خبر موسى وفرعون بالحق لقوم يؤمنون، لأنهم المنتفعون به، وهم في ظرف صعب يحتاجون فيه إلى مثل هذا القصص ليثبتوا. إن فرعون طغى وتكبّر في أرض مصر، وجعل أهلها طوائف فرّق بينها إبقاءً على ملكه، يستضعف طائفة منهم، بني إسرائيل، يذبح أبناءهم ساعة ولادتهم ويستبقي بناتهم للخدمة، لأن كهّانه وسياسيّيه أعلموه أن ملكه مهدّد بهم، فاستعمل طريقة تقليلهم، وهي سياسة تشبه تحديد النسل الذي يستعمله بعض الحاكمين اليوم، إنه كان من المفسدين. ونريد أن ننعم على المستضعفين من بني إسرائيل بالإيمان وتخليصهم من حكم فرعون، ونجعلهم قادة في الخير، ونجعلهم الوارثين لحكم البلاد، ونمكّن لهم فيها، ونُري فرعون وهامان وجنودهما منهم ما كانوا يحذرون من مولود يذهب بملكهم.", "h": ["تقرير إعجاز القرآن الذي هو آية أنه كتاب الله حقاً.", "تقرير النبوة المحمدية بهذا الوحي الإلهي.", "التحذير من الظلم والاستطالة على الناس والفساد في الأرض.", "المؤمنون هم الذين ينتفعون بما يُتلى عليهم لحياة قلوبهم.", "تقرير قاعدة: لا حذر مع القدر.", "تحريم تحديد النسل بإلزام المواطن بألا يزيد على عدد معين من الأطفال."], "k": "«ونريد أن نمنّ على الذين استضعفوا»… حين أشعر بالضعف، هل أتذكّر أن إرادة الله فوق كل قوة؟"}, {"lbl": "الآيات ٧ – ١١", "q": "وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ ﴿٧﴾ فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ ﴿٨﴾ وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ ﴿٩﴾ وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿١٠﴾ وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبٖ وَهُمۡ لَا يَشۡعُرُونَ ﴿١١﴾", "w": [["وأوحينا إلى أم موسى", "أعلمناها أن ترضع ولدها، ثم تضعه في تابوت فتلقيه في اليم."], ["في اليم", "في البحر، وهو نهر النيل."], ["ولا تخافي ولا تحزني", "لا تخافي عليه الهلاك، ولا تحزني على فراقه."], ["فالتقطه آل فرعون", "أعوانه ورجاله."], ["ليكون لهم عدواً وحزناً", "في عاقبة الأمر، فاللام للعاقبة والصيرورة."], ["قرّة عين لي ولك", "تقرّ به عيني وعينك فنفرح به."], ["وأصبح فؤاد أم موسى فارغاً", "من كل شيء إلا منه."], ["إن كادت لتُبدي به", "قاربت أن تصرخ أنه ولدها."], ["وقالت لأخته قصّيه", "اتّبعي أثره حتى تعرفي أين هو."], ["فبصرت به عن جُنُب", "لاحظته وهي مختفية تتبعه من مكان بعيد."]], "m": "هذه بداية قصة موسى مع فرعون، من طفولته رضيعاً إلى هلاك فرعون: وأوحينا إلى أم موسى إلهاماً: أن أرضعيه، فإذا خفت عليه من آل فرعون الذين يقتلون مواليد بني إسرائيل الذكور فاجعليه في صندوق وألقيه في النيل، ولا تخافي عليه الهلاك ولا تحزني على فراقه، إنا رادّوه إليك وجاعلوه من المرسلين. ففعلت، فالتقطه آل فرعون وأعطوه لآسية امرأة فرعون، ليكون لهم في عاقبة الأمر عدواً وحزناً، إن فرعون وهامان وجنودهما كانوا آثمين. وقالت امرأة فرعون حين همّ بقتله: قرّة عين لي ولك، لا تقتلوه، عسى أن ينفعنا أو نتخذه ولداً، فكان موسى إلى الثلاثين من عمره يُعرف بابن فرعون، وهم لا يشعرون بأن هلاكهم سيكون على يده. وأصبح فؤاد أم موسى فارغاً إلا منه، إن كادت لتصرخ بأنه ولدها من شدة الحزن، لولا أن ربط الله على قلبها لتكون من المؤمنين بوعده. وقالت لأخته: تتبّعي أثره، فرأته من بُعد تمشي على شاطئ النهر حتى علمت أنه دخل القصر، وهم لا يشعرون أنها أخته.", "h": ["بيان تدبير الله تعالى لأوليائه وصالحي عباده، وتجلّى ذلك في الوحي إلى أم موسى وإلقائه في البحر والتقاط آل فرعون له ليتربّى في بيت الملك عزيزاً مكرماً.", "بيان سوء الخطيئة وآثارها السيئة وعواقبها المدمّرة، وتجلّى ذلك فيما حلّ بفرعون وهامان.", "فضيلة الرجاء، تجلّت في قول آسية: «قرّة عين لي ولك»، فكان موسى قرة عين لآسية ولم يكن لفرعون.", "بيان عاطفة الأمومة، حيث أصبح فؤاد أم موسى فارغاً إلا من موسى.", "بيان عناية الله بأوليائه، حيث ربط على قلب أم موسى فصبرت ولم تُبده لهم."], "k": "«لولا أن ربطنا على قلبها»… الصبر ليس من عندي بل رباط من الله؛ فهل أسأله أن يربط على قلبي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (278, 28, 12, 25, 'سورة القصص ١٢ – ٢٥', '«فرددناه إلى أمه كي تقرّ عينها»، و«ربّ إني ظلمت نفسي فاغفر لي»، و«ربّ إني لما أنزلت إليّ من خير فقير»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 278) = $j$[{"lbl": "الآيات ١٢ – ١٦", "q": "۞وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰٓ أَهۡلِ بَيۡتٖ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ ﴿١٢﴾ فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿١٣﴾ وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١٤﴾ وَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ ﴿١٥﴾ قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿١٦﴾", "w": [["وحرّمنا عليه المراضع", "منعناه من قبول ثدي أي مرضعة."], ["فقالت هل أدلّكم", "قالت أخت موسى."], ["يكفلونه لكم", "يضمّونه إليهم، يرضعونه ويربّونه لكم."], ["وهم له ناصحون", "قالت لما اتّهموها: إنما أعني أنهم ناصحون للملك."], ["ولتعلم أن وعد الله حق", "إذ أوحى إليها أنه رادّه إليها."], ["ولما بلغ أشدّه واستوى", "ثلاثين سنة، فكمل شبابه وعقله."], ["آتيناه حكماً وعلماً", "الحكمة في القول والعمل، والعلم بالدين، قبل أن يُنبّأ."], ["على حين غفلة من أهلها", "وقت القيلولة."], ["هذا من شيعته", "على دينه."], ["فوكزه موسى فقضى عليه", "ضربه بجمع كفّه فقتله."], ["هذا من عمل الشيطان", "لأنه المهيّج لغضبي."]], "m": "لما التقط آل فرعون موسى قدّموا له المراضع فرفضهن واحدة بعد أخرى، وقد ألقى الله عليه محبة منه فما رآه أحد إلا أحبّه. فتقدّمت أخته وقالت: هل أدلّكم على أهل بيت يكفلونه لكم وهم له ناصحون؟ فارتابوا فيها، فقالت: إنما عنيت أنهم ناصحون للملك. فأتت به أمه، فما إن رآها حتى أخذ ثديها، فأذنوا لها في إرضاعه في بيتها، فرددناه إلى أمه كي تقرّ عينها ولا تحزن، ولتعلم أن وعد الله حق، ولكن أكثر الناس لا يعلمون. ولما بلغ ثلاثين سنة آتيناه حكمة وفقهاً في الدين، وكذلك نجزي المحسنين. ودخل مدينة فرعون وقت القيلولة، فوجد فيها رجلين يقتتلان: هذا من بني إسرائيل على دينه، وهذا قبطي من عدوه، فاستغاثه الإسرائيلي فضرب موسى القبطي بجمع كفّه فقتله، فقال: هذا من عمل الشيطان، هيّج غضبي، إنه عدو مضل مبين. ثم دعا ربه معترفاً: رب إني ظلمت نفسي بقتل القبطي فاغفر لي، فغفر له، إنه هو الغفور الرحيم.", "h": ["بيان حسن تدبير الله تعالى في منع موسى من سائر المرضعات حتى يردّه إلى أمه.", "بيان حسن ردّ الفتاة على التهمة التي وُجّهت إليها، وذلك من ولاية الله لها وتوفيقه.", "تقرير أن وعد الله حق، وأنه تعالى لا يخلف الوعد ولا الميعاد.", "بيان إنعام الله على موسى بالحكمة والعلم قبل النبوة والرسالة.", "مشروعية إغاثة الملهوف ونصرة المظلوم.", "وجوب التوبة بعد الوقوع في الزلل، وأول التوبة الاعتراف بالذنب."], "k": "«ربّ إني ظلمت نفسي فاغفر لي»… التوبة تبدأ بالاعتراف؛ فما الذنب الذي أحتاج أن أسمّيه أمام ربي؟"}, {"lbl": "الآيات ١٧ – ٢١", "q": "قَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ ظَهِيرٗا لِّلۡمُجۡرِمِينَ ﴿١٧﴾ فَأَصۡبَحَ فِي ٱلۡمَدِينَةِ خَآئِفٗا يَتَرَقَّبُ فَإِذَا ٱلَّذِي ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ يَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِيّٞ مُّبِينٞ ﴿١٨﴾ فَلَمَّآ أَنۡ أَرَادَ أَن يَبۡطِشَ بِٱلَّذِي هُوَ عَدُوّٞ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقۡتُلَنِي كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارٗا فِي ٱلۡأَرۡضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلۡمُصۡلِحِينَ ﴿١٩﴾ وَجَآءَ رَجُلٞ مِّنۡ أَقۡصَا ٱلۡمَدِينَةِ يَسۡعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلۡمَلَأَ يَأۡتَمِرُونَ بِكَ لِيَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّي لَكَ مِنَ ٱلنَّـٰصِحِينَ ﴿٢٠﴾ فَخَرَجَ مِنۡهَا خَآئِفٗا يَتَرَقَّبُۖ قَالَ رَبِّ نَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٢١﴾", "w": [["بما أنعمت عليّ", "بإنعامك عليّ بمغفرة ذنبي."], ["فلن أكون ظهيراً للمجرمين", "معيناً لأهل الإجرام."], ["خائفاً يترقّب", "ماذا يحدث بعد القتل."], ["يستصرخه", "يستغيث به على قبطي آخر."], ["إنك لغويّ مبين", "لذو غواية وضلال ظاهر."], ["أن يبطش بالذي هو عدوّ لهما", "أن يأخذ عدوّه وعدوّ الإسرائيلي."], ["من المصلحين", "الذين يصلحون بين الناس إذا تخاصموا."], ["وجاء رجل من أقصى المدينة", "مؤمن آل فرعون، أتى من أبعد نواحيها."], ["إن الملأ يأتمرون بك", "يتشاورون ليقتلوك."], ["فخرج منها خائفاً يترقّب", "خائفاً من القتل يترقّب ما يحدث له."]], "m": "لما علم موسى بمغفرة الله له عاهده قائلاً: رب بما أنعمت عليّ بالمغفرة فلن أكون معيناً للمجرمين، ومن ذلك أن يعتزل فرعون وملأه. فأصبح في المدينة خائفاً مما قد يترتّب على القتل، يترقّب الأحداث، فإذا الإسرائيلي الذي استنصره بالأمس يستغيث به بأعلى صوته، فقال له موسى: إنك لذو غواية بيّنة، قاتلت أمس وتقاتل اليوم. فلما أراد أن يبطش بالقبطي ظن الإسرائيلي أنه يريده هو، فقال: يا موسى أتريد أن تقتلني كما قتلت نفساً بالأمس؟ إن تريد إلا أن تكون جباراً في الأرض، وما تريد أن تكون من المصلحين. فنقلها القبطي إلى القصر، فاجتمع رجاله يتداولون القضية، وكان فيهم مؤمن آل فرعون يكتم إيمانه، فجاء من أقصى المدينة يسعى فقال: يا موسى إن الملأ يتشاورون ليقتلوك، فاخرج إني لك من الناصحين. فخرج منها خائفاً يترقّب، وقال: رب نجّني من القوم الظالمين.", "h": ["شكر النعم، فموسى لما غفر الله له شكره بأن تعهّد له ألا يقف إلى جنب مجرم.", "سوء صحبة الأحمق الغويّ، فإن الإسرائيلي لغوايته وحمقه هو الذي سبّب متاعب موسى.", "لزوم إبلاغ الدولة عن أهل الفساد والشر في البلاد لحمايتها.", "وجوب النصح وبذل النصيحة، فمؤمن آل فرعون علم سلامة موسى من الجريمة إذ كان ما حدث خطأً، فنصحه بمغادرة البلاد إنقاذاً له، وليس هذا من خيانة البلاد.", "الخوف الطبيعي لا يُلام عليه، فموسى ﵇ خاف خوفاً أدّى به إلى الالتجاء إلى ربه بالدعاء."], "k": "«فلن أكون ظهيراً للمجرمين»… شكر المغفرة عهد على الطريق؛ فما العهد الذي أقطعه على نفسي بعد توبتي؟"}, {"lbl": "الآيات ٢٢ – ٢٥", "q": "وَلَمَّا تَوَجَّهَ تِلۡقَآءَ مَدۡيَنَ قَالَ عَسَىٰ رَبِّيٓ أَن يَهۡدِيَنِي سَوَآءَ ٱلسَّبِيلِ ﴿٢٢﴾ وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ ﴿٢٣﴾ فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ ﴿٢٤﴾ فَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٢٥﴾", "w": [["ولما توجّه تلقاء مدين", "أقبل بوجهه جهة مدين، مدينة شعيب."], ["أن يهديني سواء السبيل", "أرجو ربي أن يدلّني وسط الطريق حتى لا أضل فأهلك."], ["ولما ورد ماء مدين", "انتهى إلى بئر يسقي منها أهل مدين."], ["يسقون", "مواشيهم."], ["تذودان", "تمنعان أغنامهما من الماء حتى تخلو الساحة، خوف الاختلاط بالرجال."], ["ما خطبكما", "ما شأنكما؟"], ["حتى يُصدر الرعاء", "لا نسقي حتى ينصرف الرعاة ويبقى لنا الماء."], ["ثم تولّى إلى الظل", "رجع إلى ظل الشجرة بعد أن سقى لهما."], ["لما أنزلت إليّ من خير فقير", "محتاج إلى طعام لشدة جوعه."], ["تمشي على استحياء", "واضعة كمّ درعها على وجهها حياءً منه."]], "m": "ولما توجّه موسى نحو مدين، عملاً بنصيحة مؤمن آل فرعون، ولا علم له بالطريق الصحراوي ومسافته ثمانية أيام، قال: عسى ربي أن يهديني الطريق السويّ، فاستجاب الله له. ولما ورد ماء مدين وجد عليه جماعة كثيرة يسقون مواشيهم، ووجد من دونهم امرأتين، بنتي شعيب ﵇، تمنعان ماشيتهما من الاختلاط، فسألهما: ما شأنكما؟ قالتا: لا نسقي حتى يُصدر الرعاء، لضعفنا وعدم رغبتنا في الاختلاط بالرجال، وأبونا شيخ كبير لا يقوى على السقي. فسقى لهما، ثم تولّى إلى ظل شجرة، وسأل ربه الطعام لشدة جوعه، إذ خرج من مصر بلا زاد ولا دليل، فقال: رب إني لما أنزلت إليّ من خير فقير. فلما عادت البنتان أخبرتا أباهما، فجاءته إحداهما تمشي على استحياء، واضعة كمّ درعها على وجهها، فقالت: إن أبي يدعوك ليجزيك أجر ما سقيت لنا.", "h": ["وجوب حسن الظن بالله تعالى، وقوة الرجاء فيه عز وجل، والتوكّل عليه.", "بيان فضل الحياء، وشرف المؤمنات اللائي يتعفّفن عن الاختلاط بالرجال.", "بيان مروءة موسى في سقيه للمرأتين.", "فضل الدعاء، وسؤال الله تعالى ما العبد في حاجة إليه.", "ستر الوجه عن الأجانب سنّة المؤمنات من عهد قديم، وليس كما يقول المبطلون عادة جاهلية، فبنتا شعيب نشأتا في دار النبوة وغطّت إحداهما وجهها عن موسى حياءً وتقوى."], "k": "«ربّ إني لما أنزلت إليّ من خير فقير»… جائع غريب يعرض فقره على ربه؛ فهل أعرض حاجتي عليه قبل الناس؟"}]$j$::jsonb then 0 else 1 end;
