insert into public.tdb_cards(topic, i, body) select 278, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢ – ١٦", "q": "۞وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰٓ أَهۡلِ بَيۡتٖ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ ﴿١٢﴾ فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿١٣﴾ وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿١٤﴾ وَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ ﴿١٥﴾ قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿١٦﴾", "w": [["وحرّمنا عليه المراضع", "منعناه من قبول ثدي أي مرضعة."], ["فقالت هل أدلّكم", "قالت أخت موسى."], ["يكفلونه لكم", "يضمّونه إليهم، يرضعونه ويربّونه لكم."], ["وهم له ناصحون", "قالت لما اتّهموها: إنما أعني أنهم ناصحون للملك."], ["ولتعلم أن وعد الله حق", "إذ أوحى إليها أنه رادّه إليها."], ["ولما بلغ أشدّه واستوى", "ثلاثين سنة، فكمل شبابه وعقله."], ["آتيناه حكماً وعلماً", "الحكمة في القول والعمل، والعلم بالدين، قبل أن يُنبّأ."], ["على حين غفلة من أهلها", "وقت القيلولة."], ["هذا من شيعته", "على دينه."], ["فوكزه موسى فقضى عليه", "ضربه بجمع كفّه فقتله."], ["هذا من عمل الشيطان", "لأنه المهيّج لغضبي."]], "m": "لما التقط آل فرعون موسى قدّموا له المراضع فرفضهن واحدة بعد أخرى، وقد ألقى الله عليه محبة منه فما رآه أحد إلا أحبّه. فتقدّمت أخته وقالت: هل أدلّكم على أهل بيت يكفلونه لكم وهم له ناصحون؟ فارتابوا فيها، فقالت: إنما عنيت أنهم ناصحون للملك. فأتت به أمه، فما إن رآها حتى أخذ ثديها، فأذنوا لها في إرضاعه في بيتها، فرددناه إلى أمه كي تقرّ عينها ولا تحزن، ولتعلم أن وعد الله حق، ولكن أكثر الناس لا يعلمون. ولما بلغ ثلاثين سنة آتيناه حكمة وفقهاً في الدين، وكذلك نجزي المحسنين. ودخل مدينة فرعون وقت القيلولة، فوجد فيها رجلين يقتتلان: هذا من بني إسرائيل على دينه، وهذا قبطي من عدوه، فاستغاثه الإسرائيلي فضرب موسى القبطي بجمع كفّه فقتله، فقال: هذا من عمل الشيطان، هيّج غضبي، إنه عدو مضل مبين. ثم دعا ربه معترفاً: رب إني ظلمت نفسي بقتل القبطي فاغفر لي، فغفر له، إنه هو الغفور الرحيم.", "h": ["بيان حسن تدبير الله تعالى في منع موسى من سائر المرضعات حتى يردّه إلى أمه.", "بيان حسن ردّ الفتاة على التهمة التي وُجّهت إليها، وذلك من ولاية الله لها وتوفيقه.", "تقرير أن وعد الله حق، وأنه تعالى لا يخلف الوعد ولا الميعاد.", "بيان إنعام الله على موسى بالحكمة والعلم قبل النبوة والرسالة.", "مشروعية إغاثة الملهوف ونصرة المظلوم.", "وجوب التوبة بعد الوقوع في الزلل، وأول التوبة الاعتراف بالذنب."], "k": "«ربّ إني ظلمت نفسي فاغفر لي»… التوبة تبدأ بالاعتراف؛ فما الذنب الذي أحتاج أن أسمّيه أمام ربي؟"}, {"lbl": "الآيات ١٧ – ٢١", "q": "قَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ ظَهِيرٗا لِّلۡمُجۡرِمِينَ ﴿١٧﴾ فَأَصۡبَحَ فِي ٱلۡمَدِينَةِ خَآئِفٗا يَتَرَقَّبُ فَإِذَا ٱلَّذِي ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ يَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِيّٞ مُّبِينٞ ﴿١٨﴾ فَلَمَّآ أَنۡ أَرَادَ أَن يَبۡطِشَ بِٱلَّذِي هُوَ عَدُوّٞ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقۡتُلَنِي كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارٗا فِي ٱلۡأَرۡضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلۡمُصۡلِحِينَ ﴿١٩﴾ وَجَآءَ رَجُلٞ مِّنۡ أَقۡصَا ٱلۡمَدِينَةِ يَسۡعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلۡمَلَأَ يَأۡتَمِرُونَ بِكَ لِيَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّي لَكَ مِنَ ٱلنَّـٰصِحِينَ ﴿٢٠﴾ فَخَرَجَ مِنۡهَا خَآئِفٗا يَتَرَقَّبُۖ قَالَ رَبِّ نَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٢١﴾", "w": [["بما أنعمت عليّ", "بإنعامك عليّ بمغفرة ذنبي."], ["فلن أكون ظهيراً للمجرمين", "معيناً لأهل الإجرام."], ["خائفاً يترقّب", "ماذا يحدث بعد القتل."], ["يستصرخه", "يستغيث به على قبطي آخر."], ["إنك لغويّ مبين", "لذو غواية وضلال ظاهر."], ["أن يبطش بالذي هو عدوّ لهما", "أن يأخذ عدوّه وعدوّ الإسرائيلي."], ["من المصلحين", "الذين يصلحون بين الناس إذا تخاصموا."], ["وجاء رجل من أقصى المدينة", "مؤمن آل فرعون، أتى من أبعد نواحيها."], ["إن الملأ يأتمرون بك", "يتشاورون ليقتلوك."], ["فخرج منها خائفاً يترقّب", "خائفاً من القتل يترقّب ما يحدث له."]], "m": "لما علم موسى بمغفرة الله له عاهده قائلاً: رب بما أنعمت عليّ بالمغفرة فلن أكون معيناً للمجرمين، ومن ذلك أن يعتزل فرعون وملأه. فأصبح في المدينة خائفاً مما قد يترتّب على القتل، يترقّب الأحداث، فإذا الإسرائيلي الذي استنصره بالأمس يستغيث به بأعلى صوته، فقال له موسى: إنك لذو غواية بيّنة، قاتلت أمس وتقاتل اليوم. فلما أراد أن يبطش بالقبطي ظن الإسرائيلي أنه يريده هو، فقال: يا موسى أتريد أن تقتلني كما قتلت نفساً بالأمس؟ إن تريد إلا أن تكون جباراً في الأرض، وما تريد أن تكون من المصلحين. فنقلها القبطي إلى القصر، فاجتمع رجاله يتداولون القضية، وكان فيهم مؤمن آل فرعون يكتم إيمانه، فجاء من أقصى المدينة يسعى فقال: يا موسى إن الملأ يتشاورون ليقتلوك، فاخرج إني لك من الناصحين. فخرج منها خائفاً يترقّب، وقال: رب نجّني من القوم الظالمين.", "h": ["شكر النعم، فموسى لما غفر الله له شكره بأن تعهّد له ألا يقف إلى جنب مجرم.", "سوء صحبة الأحمق الغويّ، فإن الإسرائيلي لغوايته وحمقه هو الذي سبّب متاعب موسى.", "لزوم إبلاغ الدولة عن أهل الفساد والشر في البلاد لحمايتها.", "وجوب النصح وبذل النصيحة، فمؤمن آل فرعون علم سلامة موسى من الجريمة إذ كان ما حدث خطأً، فنصحه بمغادرة البلاد إنقاذاً له، وليس هذا من خيانة البلاد.", "الخوف الطبيعي لا يُلام عليه، فموسى ﵇ خاف خوفاً أدّى به إلى الالتجاء إلى ربه بالدعاء."], "k": "«فلن أكون ظهيراً للمجرمين»… شكر المغفرة عهد على الطريق؛ فما العهد الذي أقطعه على نفسي بعد توبتي؟"}, {"lbl": "الآيات ٢٢ – ٢٥", "q": "وَلَمَّا تَوَجَّهَ تِلۡقَآءَ مَدۡيَنَ قَالَ عَسَىٰ رَبِّيٓ أَن يَهۡدِيَنِي سَوَآءَ ٱلسَّبِيلِ ﴿٢٢﴾ وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ ﴿٢٣﴾ فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ ﴿٢٤﴾ فَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٢٥﴾", "w": [["ولما توجّه تلقاء مدين", "أقبل بوجهه جهة مدين، مدينة شعيب."], ["أن يهديني سواء السبيل", "أرجو ربي أن يدلّني وسط الطريق حتى لا أضل فأهلك."], ["ولما ورد ماء مدين", "انتهى إلى بئر يسقي منها أهل مدين."], ["يسقون", "مواشيهم."], ["تذودان", "تمنعان أغنامهما من الماء حتى تخلو الساحة، خوف الاختلاط بالرجال."], ["ما خطبكما", "ما شأنكما؟"], ["حتى يُصدر الرعاء", "لا نسقي حتى ينصرف الرعاة ويبقى لنا الماء."], ["ثم تولّى إلى الظل", "رجع إلى ظل الشجرة بعد أن سقى لهما."], ["لما أنزلت إليّ من خير فقير", "محتاج إلى طعام لشدة جوعه."], ["تمشي على استحياء", "واضعة كمّ درعها على وجهها حياءً منه."]], "m": "ولما توجّه موسى نحو مدين، عملاً بنصيحة مؤمن آل فرعون، ولا علم له بالطريق الصحراوي ومسافته ثمانية أيام، قال: عسى ربي أن يهديني الطريق السويّ، فاستجاب الله له. ولما ورد ماء مدين وجد عليه جماعة كثيرة يسقون مواشيهم، ووجد من دونهم امرأتين، بنتي شعيب ﵇، تمنعان ماشيتهما من الاختلاط، فسألهما: ما شأنكما؟ قالتا: لا نسقي حتى يُصدر الرعاء، لضعفنا وعدم رغبتنا في الاختلاط بالرجال، وأبونا شيخ كبير لا يقوى على السقي. فسقى لهما، ثم تولّى إلى ظل شجرة، وسأل ربه الطعام لشدة جوعه، إذ خرج من مصر بلا زاد ولا دليل، فقال: رب إني لما أنزلت إليّ من خير فقير. فلما عادت البنتان أخبرتا أباهما، فجاءته إحداهما تمشي على استحياء، واضعة كمّ درعها على وجهها، فقالت: إن أبي يدعوك ليجزيك أجر ما سقيت لنا.", "h": ["وجوب حسن الظن بالله تعالى، وقوة الرجاء فيه عز وجل، والتوكّل عليه.", "بيان فضل الحياء، وشرف المؤمنات اللائي يتعفّفن عن الاختلاط بالرجال.", "بيان مروءة موسى في سقيه للمرأتين.", "فضل الدعاء، وسؤال الله تعالى ما العبد في حاجة إليه.", "ستر الوجه عن الأجانب سنّة المؤمنات من عهد قديم، وليس كما يقول المبطلون عادة جاهلية، فبنتا شعيب نشأتا في دار النبوة وغطّت إحداهما وجهها عن موسى حياءً وتقوى."], "k": "«ربّ إني لما أنزلت إليّ من خير فقير»… جائع غريب يعرض فقره على ربه؛ فهل أعرض حاجتي عليه قبل الناس؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (279, 28, 26, 43, 'سورة القصص ٢٦ – ٤٣', '«إن خير من استأجرت القوي الأمين»، و«إني أنا الله رب العالمين»، و«سنشدّ عضدك بأخيك»، و«ما علمت لكم من إله غيري»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 279) = $j$[{"lbl": "الآيات ٢٦ – ٢٨", "q": "قَالَتۡ إِحۡدَىٰهُمَا يَـٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ ﴿٢٦﴾ قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن تَأۡجُرَنِي ثَمَٰنِيَ حِجَجٖۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرٗا فَمِنۡ عِندِكَۖ وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّـٰلِحِينَ ﴿٢٧﴾ قَالَ ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ ﴿٢٨﴾", "w": [["وقصّ عليه القصص", "أخبره بشأنه كله من قتله القبطي وطلب السلطة له."], ["لا تخف نجوت من القوم الظالمين", "من فرعون وملئه، إذ لا سلطان لهم على هذه البلاد."], ["يا أبت استأجره", "اتخذه أجيراً يرعى لنا الغنم."], ["القوي الأمين", "ذكرت كفاءته: القوة البدنية والأمانة."], ["على أن تأجرني", "تكون أجيراً لي في رعي غنمي."], ["ثماني حجج", "ثماني سنوات، والحجة العام."], ["فإن أتممت عشراً فمن عندك", "تفضّلاً منك."], ["من الصالحين", "الذين يوفون ولا ينقضون ولا ينقصون."], ["أيّما الأجلين قضيت", "الثمانية أو العشرة."], ["والله على ما نقول وكيل", "شهيد وحفيظ على العقد بشطريه: النكاح ورعي الغنم."]], "m": "فلما جاء موسى شعيباً وأخبره بشأنه كله قال له: لا تخف، نجوت من القوم الظالمين، فلا سلطان لفرعون على هذه البلاد. ودعاه إلى الطعام، فقال موسى: أخاف أن يكون عوضاً عما سقيت، وإني من أهل بيت لا يطلبون على عمل الخير عوضاً، فقال شعيب: لا، إنما عادتنا أن نقري الضيف. وقالت إحداهما: يا أبت استأجره، إن خير من استأجرت القوي الأمين، فسألها: كيف علمت ذلك؟ فذكرت قوّته في السقي، وأمانته في غضّ بصره عنها. فقال شعيب: إني أريد أن أزوّجك إحدى ابنتيّ هاتين على أن تكون أجيراً لي ثماني سنين، فإن أتممت عشراً فمن عندك تفضّلاً، وما أريد أن أشق عليك، ستجدني إن شاء الله من الصالحين الذين يوفون. قال موسى: ذلك بيني وبينك، أيّما الأجلين قضيت فلا عدوان عليّ بطلب الزيادة، والله على ما نقول شهيد، فأصبح موسى زوجاً لابنة شعيب.", "h": ["تجلّي كرم شعيب ومروءته وشهامته في تطمين موسى وإكرامه وإيوائه.", "بيان أن الكفاءة شرط في العمل، ولا أفضل من القوة، وهي القدرة البدنية والعلمية، مع الأمانة.", "مشروعية عرض الرجل ابنته على من يرى صدقه وأمانته ليزوّجه بها.", "مشروعية إشهاد الله تعالى على العقود بمثل: «والله على ما نقول وكيل».", "فضيلة موسى ﵇ بإيجار نفسه على شبع بطنه وإحصان فرجه."], "k": "«إن خير من استأجرت القوي الأمين»… قوة بلا أمانة لا تكفي؛ فأيهما أحتاج أن أنمّيه في عملي؟"}, {"lbl": "الآيات ٢٩ – ٣٢", "q": "۞فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارٗاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةٖ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ ﴿٢٩﴾ فَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴿٣٠﴾ وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡأٓمِنِينَ ﴿٣١﴾ ٱسۡلُكۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖ وَٱضۡمُمۡ إِلَيۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَٰنِكَ بُرۡهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ﴿٣٢﴾", "w": [["قضى موسى الأجل", "أتمّ المدة المتّفق عليها."], ["أو جذوة من النار", "خشبة في رأسها نار مشتعلة."], ["لعلكم تصطلون", "تستدفئون."], ["نودي", "ناداه الله: يا موسى إني أنا الله رب العالمين."], ["في البقعة المباركة", "قطعة الأرض التي عليها الشجرة."], ["تهتزّ كأنها جانّ", "تضطرب وتتحرك بسرعة كأنها حية."], ["ولّى مدبراً ولم يعقّب", "رجع هارباً لخوفه وفزعه منها."], ["اسلك يدك في جيبك", "أدخلها في جيب قميصك."], ["من غير سوء", "من غير عيب كبرص ونحوه."], ["واضمم إليك جناحك من الرهب", "ضع يدك على صدرك ليذهب عنك الخوف."], ["فذانك برهانان", "آيتان من ربك على صدق رسالتك."]], "m": "لما قضى موسى أوفى الأجلين، العشر، قفل بأهله إلى مصر لزيارة والدته وإخوته، فضلّ الطريق ليلاً في شتاء شديد البرد، فأبصر من جانب جبل الطور ناراً، فقال لأهله: امكثوا إني أبصرت ناراً، لعلي آتيكم منها بخبر عن الطريق، أو بشعلة لعلكم تستدفئون. فلما أتاها نودي من شاطئ الوادي الأيمن في البقعة المباركة من الشجرة: يا موسى إني أنا الله رب العالمين، وأن ألق عصاك، فلما رآها تهتزّ كأنها حية ولّى مدبراً ولم يرجع، فقال له ربه: يا موسى أقبل ولا تخف، إنك من الآمنين. أدخل يدك في جيب قميصك تخرج بيضاء كالنور من غير برص، واضمم يدك إلى صدرك من الخوف يذهب عنك. فذانك، العصا واليد، آيتان من ربك على رسالتك إلى فرعون وملئه، إنهم كانوا قوماً خارجين عن طاعة الله.", "h": ["الأنبياء أوفياء، فموسى قضى أوفى الأجلين وأتمّهما وهو العشر.", "مشروعية السفر بالأهل، وقد يحصل للمرء أن يضلّ الطريق أو يحتاج إلى شيء.", "فضل تلك البقعة التي كلّم الله تعالى فيها موسى ﵇.", "مشروعية حمل العصا، لا سيما للمسافر وراعي الماشية.", "مشروعية التدريب على السلاح قبل استعماله.", "لا يُلام على الخوف الطبيعي.", "من خاف فوضع يده على صدره زال خوفه إن شاء الله تعالى."], "k": "«أقبل ولا تخف إنك من الآمنين»… الأمان في الإقبال على الله لا في الفرار؛ فإلى أين أفرّ حين أخاف؟"}, {"lbl": "الآيات ٣٣ – ٣٧", "q": "قَالَ رَبِّ إِنِّي قَتَلۡتُ مِنۡهُمۡ نَفۡسٗا فَأَخَافُ أَن يَقۡتُلُونِ ﴿٣٣﴾ وَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ﴿٣٤﴾ قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ ﴿٣٥﴾ فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا سِحۡرٞ مُّفۡتَرٗى وَمَا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ﴿٣٦﴾ وَقَالَ مُوسَىٰ رَبِّيٓ أَعۡلَمُ بِمَن جَآءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ ﴿٣٧﴾", "w": [["إني قتلت منهم نفساً", "نفس القبطي الذي قتله خطأ قبل هجرته من مصر."], ["أفصح مني لساناً", "أبين مني قولاً."], ["ردءاً", "معيناً لي."], ["سنشدّ عضدك بأخيك", "ندعمك ونقوّيك بأخيك هارون."], ["ونجعل لكما سلطاناً", "حجة قوية يكون لكما بها الغلب."], ["فلما جاءهم موسى بآياتنا", "العصا واليد وغيرهما من الآيات التسع."], ["سحر مفترى", "مختلق مكذوب."], ["عاقبة الدار", "العاقبة المحمودة في الدار الآخرة."], ["إنه لا يفلح الظالمون", "المشركون الكافرون."]], "m": "لما كلّف الله موسى بالذهاب إلى فرعون قال: رب إني قتلت منهم نفساً فأخاف أن يقتلوني به قبل أن أبيّن حجتي، وأخي هارون أفصح مني لساناً فأرسله معي معيناً يصدّقني ويلخّص قولي لهم، إني أخاف أن يكذّبون. قال: سنقوّيك بأخيك، ونجعل لكما حجة قوية يكون لكما بها الغلب، فلا يصلون إليكما بسوء، بآياتنا أنتما ومن اتّبعكما الغالبون. فلما جاءهم موسى بآياتنا واضحات قالوا: ما هذا إلا سحر مختلق، وما سمعنا بهذا في آبائنا الأولين. فردّ موسى بأحسن رد: ربي أعلم بمن جاء بالهدى من عنده ومن تكون له العاقبة المحمودة يوم القيامة، إنه لا يفلح الظالمون؛ لم يقل له: اسكت يا ضال، بل تلطّف معه غاية اللطف امتثالاً لأمر الله: «فقولا له قولاً ليّناً».", "h": ["بيان أن القصاص كان معروفاً معمولاً به عند أقدم الأمم.", "مشروعية طلب العون عند التكليف بما يشق ويصعب من المسؤولين المكلِّفين.", "مشروعية التلطّف في خطاب الجبابرة وإلانة القول لهم، بل هو مشروع مع كل من يُدعى إلى الحق، من أجل أن يتفهّم القول ولا يرده للإغلاظ له."], "k": "«ربي أعلم بمن جاء بالهدى من عنده»… ردّ هادئ أمام اتهام جارح؛ فكيف أردّ حين يُتّهم ما أحمله من حق؟"}, {"lbl": "الآيات ٣٨ – ٤٣", "q": "وَقَالَ فِرۡعَوۡنُ يَـٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ ﴿٣٨﴾ وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَظَنُّوٓاْ أَنَّهُمۡ إِلَيۡنَا لَا يُرۡجَعُونَ ﴿٣٩﴾ فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّـٰلِمِينَ ﴿٤٠﴾ وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ ﴿٤١﴾ وَأَتۡبَعۡنَٰهُمۡ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِينَ ﴿٤٢﴾ وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٤٣﴾", "w": [["ما علمت لكم من إله غيري", "ربّاً يُطاع ويُعظّم غيري."], ["يا هامان", "أحد وزراء فرعون."], ["فأوقد لي يا هامان على الطين", "اطبخ لي الآجُرّ، وهو اللبِن المشويّ."], ["فاجعل لي صرحاً", "بناءً عالياً."], ["لعلي أطّلع إلى إله موسى", "أقف عليه وأنظر إليه."], ["فنبذناهم في اليم", "طرحناهم في البحر غرقى."], ["وجعلناهم أئمة", "رؤساء يُقتدى بهم في الباطل."], ["يدعون إلى النار", "إلى الكفر والشرك والمعاصي الموجبة للنار."], ["في هذه الدنيا لعنة", "خزياً وبعداً عن الخير."], ["من المقبوحين", "المبعدين من كل خير."], ["القرون الأولى", "قوم نوح وهود وصالح وغيرهم."], ["بصائر للناس", "فيه من النور ما يهدي كما تهدي الأبصار."]], "m": "لما سمع فرعون كلام موسى المصدَّق بكلام هارون، وكان غاية في اللين مؤثراً، خاف الهزيمة فراوغ، وقال للحاضرين: ما علمت لكم من إله غيري، ولكن سأبحث، فأوقد لي يا هامان على الطين فاجعل لي صرحاً عالياً لعلي أطّلع إلى إله موسى، وإني لأظنه من الكاذبين. واستكبر هو وجنوده في أرض مصر بغير الحق، وظنوا أنهم إلينا لا يرجعون، فأخذناه وجنوده بسبب استكبارهم وكفرهم فطرحناهم في البحر، فانظر كيف كان عاقبة الظالمين. وجعلناهم أئمة في الكفر يقتدي بهم الطغاة في كل زمان، يدعون إلى موجبات النار، ويوم القيامة لا يُنصرون، بل يُضاعف لهم العذاب، لأن من دعا إلى سيئة كان عليه وزرها ووزر من عمل بها. وأتبعناهم في هذه الدنيا خزياً، ويوم القيامة هم من المبعدين من رحمة الله. ولقد آتينا موسى التوراة من بعد ما أهلكنا القرون الأولى، ضياءً لبني إسرائيل يبصرون به ما يحتاجون إليه في دينهم ودنياهم، وهدى ورحمة لعلهم يتذكّرون نعم الله فيشكرونه.", "h": ["بيان أن فرعون كان على علم بأنه عبد مربوب لله، وأن الله هو رب العالمين.", "تقرير صفة العلوّ والاستكبار لفرعون، وأنه كان من العالين.", "بيان كيف تكون عاقبة الظلمة دماراً وفساداً.", "دعاة الفجور والضلالة والشرك أئمة أهل النار يدعون إليها وهم لا يشعرون.", "بيان إفضال الله تعالى على بني إسرائيل بإنزال التوراة فيهم كتاباً كله بصائر وهدى ورحمة."], "k": "«وجعلناهم أئمة يدعون إلى النار»… كل من يقتدي بي يحمل أثري؛ فإلى أين يدعو أثري من خلفي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 279;
insert into public.tdb_cards(topic, i, body) select 279, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٦ – ٢٨", "q": "قَالَتۡ إِحۡدَىٰهُمَا يَـٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ ﴿٢٦﴾ قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن تَأۡجُرَنِي ثَمَٰنِيَ حِجَجٖۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرٗا فَمِنۡ عِندِكَۖ وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّـٰلِحِينَ ﴿٢٧﴾ قَالَ ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ ﴿٢٨﴾", "w": [["وقصّ عليه القصص", "أخبره بشأنه كله من قتله القبطي وطلب السلطة له."], ["لا تخف نجوت من القوم الظالمين", "من فرعون وملئه، إذ لا سلطان لهم على هذه البلاد."], ["يا أبت استأجره", "اتخذه أجيراً يرعى لنا الغنم."], ["القوي الأمين", "ذكرت كفاءته: القوة البدنية والأمانة."], ["على أن تأجرني", "تكون أجيراً لي في رعي غنمي."], ["ثماني حجج", "ثماني سنوات، والحجة العام."], ["فإن أتممت عشراً فمن عندك", "تفضّلاً منك."], ["من الصالحين", "الذين يوفون ولا ينقضون ولا ينقصون."], ["أيّما الأجلين قضيت", "الثمانية أو العشرة."], ["والله على ما نقول وكيل", "شهيد وحفيظ على العقد بشطريه: النكاح ورعي الغنم."]], "m": "فلما جاء موسى شعيباً وأخبره بشأنه كله قال له: لا تخف، نجوت من القوم الظالمين، فلا سلطان لفرعون على هذه البلاد. ودعاه إلى الطعام، فقال موسى: أخاف أن يكون عوضاً عما سقيت، وإني من أهل بيت لا يطلبون على عمل الخير عوضاً، فقال شعيب: لا، إنما عادتنا أن نقري الضيف. وقالت إحداهما: يا أبت استأجره، إن خير من استأجرت القوي الأمين، فسألها: كيف علمت ذلك؟ فذكرت قوّته في السقي، وأمانته في غضّ بصره عنها. فقال شعيب: إني أريد أن أزوّجك إحدى ابنتيّ هاتين على أن تكون أجيراً لي ثماني سنين، فإن أتممت عشراً فمن عندك تفضّلاً، وما أريد أن أشق عليك، ستجدني إن شاء الله من الصالحين الذين يوفون. قال موسى: ذلك بيني وبينك، أيّما الأجلين قضيت فلا عدوان عليّ بطلب الزيادة، والله على ما نقول شهيد، فأصبح موسى زوجاً لابنة شعيب.", "h": ["تجلّي كرم شعيب ومروءته وشهامته في تطمين موسى وإكرامه وإيوائه.", "بيان أن الكفاءة شرط في العمل، ولا أفضل من القوة، وهي القدرة البدنية والعلمية، مع الأمانة.", "مشروعية عرض الرجل ابنته على من يرى صدقه وأمانته ليزوّجه بها.", "مشروعية إشهاد الله تعالى على العقود بمثل: «والله على ما نقول وكيل».", "فضيلة موسى ﵇ بإيجار نفسه على شبع بطنه وإحصان فرجه."], "k": "«إن خير من استأجرت القوي الأمين»… قوة بلا أمانة لا تكفي؛ فأيهما أحتاج أن أنمّيه في عملي؟"}, {"lbl": "الآيات ٢٩ – ٣٢", "q": "۞فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارٗاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةٖ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ ﴿٢٩﴾ فَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴿٣٠﴾ وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡأٓمِنِينَ ﴿٣١﴾ ٱسۡلُكۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖ وَٱضۡمُمۡ إِلَيۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَٰنِكَ بُرۡهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ﴿٣٢﴾", "w": [["قضى موسى الأجل", "أتمّ المدة المتّفق عليها."], ["أو جذوة من النار", "خشبة في رأسها نار مشتعلة."], ["لعلكم تصطلون", "تستدفئون."], ["نودي", "ناداه الله: يا موسى إني أنا الله رب العالمين."], ["في البقعة المباركة", "قطعة الأرض التي عليها الشجرة."], ["تهتزّ كأنها جانّ", "تضطرب وتتحرك بسرعة كأنها حية."], ["ولّى مدبراً ولم يعقّب", "رجع هارباً لخوفه وفزعه منها."], ["اسلك يدك في جيبك", "أدخلها في جيب قميصك."], ["من غير سوء", "من غير عيب كبرص ونحوه."], ["واضمم إليك جناحك من الرهب", "ضع يدك على صدرك ليذهب عنك الخوف."], ["فذانك برهانان", "آيتان من ربك على صدق رسالتك."]], "m": "لما قضى موسى أوفى الأجلين، العشر، قفل بأهله إلى مصر لزيارة والدته وإخوته، فضلّ الطريق ليلاً في شتاء شديد البرد، فأبصر من جانب جبل الطور ناراً، فقال لأهله: امكثوا إني أبصرت ناراً، لعلي آتيكم منها بخبر عن الطريق، أو بشعلة لعلكم تستدفئون. فلما أتاها نودي من شاطئ الوادي الأيمن في البقعة المباركة من الشجرة: يا موسى إني أنا الله رب العالمين، وأن ألق عصاك، فلما رآها تهتزّ كأنها حية ولّى مدبراً ولم يرجع، فقال له ربه: يا موسى أقبل ولا تخف، إنك من الآمنين. أدخل يدك في جيب قميصك تخرج بيضاء كالنور من غير برص، واضمم يدك إلى صدرك من الخوف يذهب عنك. فذانك، العصا واليد، آيتان من ربك على رسالتك إلى فرعون وملئه، إنهم كانوا قوماً خارجين عن طاعة الله.", "h": ["الأنبياء أوفياء، فموسى قضى أوفى الأجلين وأتمّهما وهو العشر.", "مشروعية السفر بالأهل، وقد يحصل للمرء أن يضلّ الطريق أو يحتاج إلى شيء.", "فضل تلك البقعة التي كلّم الله تعالى فيها موسى ﵇.", "مشروعية حمل العصا، لا سيما للمسافر وراعي الماشية.", "مشروعية التدريب على السلاح قبل استعماله.", "لا يُلام على الخوف الطبيعي.", "من خاف فوضع يده على صدره زال خوفه إن شاء الله تعالى."], "k": "«أقبل ولا تخف إنك من الآمنين»… الأمان في الإقبال على الله لا في الفرار؛ فإلى أين أفرّ حين أخاف؟"}, {"lbl": "الآيات ٣٣ – ٣٧", "q": "قَالَ رَبِّ إِنِّي قَتَلۡتُ مِنۡهُمۡ نَفۡسٗا فَأَخَافُ أَن يَقۡتُلُونِ ﴿٣٣﴾ وَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ﴿٣٤﴾ قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ ﴿٣٥﴾ فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا سِحۡرٞ مُّفۡتَرٗى وَمَا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ﴿٣٦﴾ وَقَالَ مُوسَىٰ رَبِّيٓ أَعۡلَمُ بِمَن جَآءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ ﴿٣٧﴾", "w": [["إني قتلت منهم نفساً", "نفس القبطي الذي قتله خطأ قبل هجرته من مصر."], ["أفصح مني لساناً", "أبين مني قولاً."], ["ردءاً", "معيناً لي."], ["سنشدّ عضدك بأخيك", "ندعمك ونقوّيك بأخيك هارون."], ["ونجعل لكما سلطاناً", "حجة قوية يكون لكما بها الغلب."], ["فلما جاءهم موسى بآياتنا", "العصا واليد وغيرهما من الآيات التسع."], ["سحر مفترى", "مختلق مكذوب."], ["عاقبة الدار", "العاقبة المحمودة في الدار الآخرة."], ["إنه لا يفلح الظالمون", "المشركون الكافرون."]], "m": "لما كلّف الله موسى بالذهاب إلى فرعون قال: رب إني قتلت منهم نفساً فأخاف أن يقتلوني به قبل أن أبيّن حجتي، وأخي هارون أفصح مني لساناً فأرسله معي معيناً يصدّقني ويلخّص قولي لهم، إني أخاف أن يكذّبون. قال: سنقوّيك بأخيك، ونجعل لكما حجة قوية يكون لكما بها الغلب، فلا يصلون إليكما بسوء، بآياتنا أنتما ومن اتّبعكما الغالبون. فلما جاءهم موسى بآياتنا واضحات قالوا: ما هذا إلا سحر مختلق، وما سمعنا بهذا في آبائنا الأولين. فردّ موسى بأحسن رد: ربي أعلم بمن جاء بالهدى من عنده ومن تكون له العاقبة المحمودة يوم القيامة، إنه لا يفلح الظالمون؛ لم يقل له: اسكت يا ضال، بل تلطّف معه غاية اللطف امتثالاً لأمر الله: «فقولا له قولاً ليّناً».", "h": ["بيان أن القصاص كان معروفاً معمولاً به عند أقدم الأمم.", "مشروعية طلب العون عند التكليف بما يشق ويصعب من المسؤولين المكلِّفين.", "مشروعية التلطّف في خطاب الجبابرة وإلانة القول لهم، بل هو مشروع مع كل من يُدعى إلى الحق، من أجل أن يتفهّم القول ولا يرده للإغلاظ له."], "k": "«ربي أعلم بمن جاء بالهدى من عنده»… ردّ هادئ أمام اتهام جارح؛ فكيف أردّ حين يُتّهم ما أحمله من حق؟"}, {"lbl": "الآيات ٣٨ – ٤٣", "q": "وَقَالَ فِرۡعَوۡنُ يَـٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ ﴿٣٨﴾ وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَظَنُّوٓاْ أَنَّهُمۡ إِلَيۡنَا لَا يُرۡجَعُونَ ﴿٣٩﴾ فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّـٰلِمِينَ ﴿٤٠﴾ وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ ﴿٤١﴾ وَأَتۡبَعۡنَٰهُمۡ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِينَ ﴿٤٢﴾ وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٤٣﴾", "w": [["ما علمت لكم من إله غيري", "ربّاً يُطاع ويُعظّم غيري."], ["يا هامان", "أحد وزراء فرعون."], ["فأوقد لي يا هامان على الطين", "اطبخ لي الآجُرّ، وهو اللبِن المشويّ."], ["فاجعل لي صرحاً", "بناءً عالياً."], ["لعلي أطّلع إلى إله موسى", "أقف عليه وأنظر إليه."], ["فنبذناهم في اليم", "طرحناهم في البحر غرقى."], ["وجعلناهم أئمة", "رؤساء يُقتدى بهم في الباطل."], ["يدعون إلى النار", "إلى الكفر والشرك والمعاصي الموجبة للنار."], ["في هذه الدنيا لعنة", "خزياً وبعداً عن الخير."], ["من المقبوحين", "المبعدين من كل خير."], ["القرون الأولى", "قوم نوح وهود وصالح وغيرهم."], ["بصائر للناس", "فيه من النور ما يهدي كما تهدي الأبصار."]], "m": "لما سمع فرعون كلام موسى المصدَّق بكلام هارون، وكان غاية في اللين مؤثراً، خاف الهزيمة فراوغ، وقال للحاضرين: ما علمت لكم من إله غيري، ولكن سأبحث، فأوقد لي يا هامان على الطين فاجعل لي صرحاً عالياً لعلي أطّلع إلى إله موسى، وإني لأظنه من الكاذبين. واستكبر هو وجنوده في أرض مصر بغير الحق، وظنوا أنهم إلينا لا يرجعون، فأخذناه وجنوده بسبب استكبارهم وكفرهم فطرحناهم في البحر، فانظر كيف كان عاقبة الظالمين. وجعلناهم أئمة في الكفر يقتدي بهم الطغاة في كل زمان، يدعون إلى موجبات النار، ويوم القيامة لا يُنصرون، بل يُضاعف لهم العذاب، لأن من دعا إلى سيئة كان عليه وزرها ووزر من عمل بها. وأتبعناهم في هذه الدنيا خزياً، ويوم القيامة هم من المبعدين من رحمة الله. ولقد آتينا موسى التوراة من بعد ما أهلكنا القرون الأولى، ضياءً لبني إسرائيل يبصرون به ما يحتاجون إليه في دينهم ودنياهم، وهدى ورحمة لعلهم يتذكّرون نعم الله فيشكرونه.", "h": ["بيان أن فرعون كان على علم بأنه عبد مربوب لله، وأن الله هو رب العالمين.", "تقرير صفة العلوّ والاستكبار لفرعون، وأنه كان من العالين.", "بيان كيف تكون عاقبة الظلمة دماراً وفساداً.", "دعاة الفجور والضلالة والشرك أئمة أهل النار يدعون إليها وهم لا يشعرون.", "بيان إفضال الله تعالى على بني إسرائيل بإنزال التوراة فيهم كتاباً كله بصائر وهدى ورحمة."], "k": "«وجعلناهم أئمة يدعون إلى النار»… كل من يقتدي بي يحمل أثري؛ فإلى أين يدعو أثري من خلفي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (280, 28, 44, 55, 'سورة القصص ٤٤ – ٥٥', '«وما كنت بجانب الغربي»، و«ومن أضلّ ممن اتّبع هواه بغير هدى من الله»، و«أولئك يؤتون أجرهم مرتين بما صبروا»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 280) = $j$[{"lbl": "الآيات ٤٤ – ٤٧", "q": "وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِيِّ إِذۡ قَضَيۡنَآ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّـٰهِدِينَ ﴿٤٤﴾ وَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ ﴿٤٥﴾ وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذۡ نَادَيۡنَا وَلَٰكِن رَّحۡمَةٗ مِّن رَّبِّكَ لِتُنذِرَ قَوۡمٗا مَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٤٦﴾ وَلَوۡلَآ أَن تُصِيبَهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَيَقُولُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿٤٧﴾", "w": [["وما كنت بجانب الغربي", "لم تكن يا رسولنا حاضراً بالجانب الغربي من الطور."], ["إذ قضينا إلى موسى الأمر", "بالرسالة إلى فرعون وقومه."], ["فتطاول عليهم العمر", "أنشأنا بعد موسى أمماً طالت أعمارهم فنسوا العهود واندرست العلوم."], ["وما كنت ثاوياً في أهل مدين", "مقيماً فيهم فتعرف أخبارهم."], ["إذ نادينا", "موسى، وأوحينا إليه ما أوحينا."], ["ما أتاهم من نذير من قبلك", "أهل مكة والعرب كافة."], ["ولولا أن تصيبهم مصيبة", "فيقولوا: هلّا أرسلت إلينا رسولاً، لعاجلناهم بالعقوبة ولما أرسلناك إليهم."]], "m": "بعد انتهاء قصص موسى، وكان كله شاهداً على نبوة محمد ﷺ، قال تعالى: وما كنت حاضراً بالجانب الغربي إذ أرسلنا موسى إلى فرعون، فكيف علمت هذا لولا أنك رسول حق؟ ولكنا أنشأنا أمماً بعد موسى طالت أعمارهم فنسوا العهود واندرست العلوم وانقطع الوحي، فجئنا بك رسولاً وأوحينا إليك خبر موسى وغيره. وما كنت مقيماً في أهل مدين تتلو عليهم آياتنا، فكيف عرفت إقامة موسى بينهم عشر سنين، ولكنا كنا مرسلين. وما كنت بجانب الطور إذ نادينا موسى، ولكن أرسلناك رحمة من ربك لتنذر قوماً ما أتاهم من نذير من قبلك، أهل مكة والعرب، لعلهم يتّعظون. ولولا أن يقولوا إذا أصابتهم عقوبة بما قدّمت أيديهم من الشرك: ربنا هلّا أرسلت إلينا رسولاً فنتّبع آياتك، لعاجلناهم بالعذاب ولما أرسلناك إليهم.", "h": ["تقرير النبوة المحمدية بأقوى الأدلة العقلية.", "بعثة الرسول محمد ﷺ جاءت في أوانها واشتداد الحاجة إليها.", "البعثة المحمدية رحمة إلهية رحم الله بها العالمين."], "k": "«ولكن رحمة من ربك»… الرسالة التي بين يديّ رحمة جاءتني بلا طلب؛ فكيف أشكرها؟"}, {"lbl": "الآيات ٤٨ – ٥١", "q": "فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُواْ لَوۡلَآ أُوتِيَ مِثۡلَ مَآ أُوتِيَ مُوسَىٰٓۚ أَوَلَمۡ يَكۡفُرُواْ بِمَآ أُوتِيَ مُوسَىٰ مِن قَبۡلُۖ قَالُواْ سِحۡرَانِ تَظَٰهَرَا وَقَالُوٓاْ إِنَّا بِكُلّٖ كَٰفِرُونَ ﴿٤٨﴾ قُلۡ فَأۡتُواْ بِكِتَٰبٖ مِّنۡ عِندِ ٱللَّهِ هُوَ أَهۡدَىٰ مِنۡهُمَآ أَتَّبِعۡهُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤٩﴾ فَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٥٠﴾ ۞وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٥١﴾", "w": [["فلما جاءهم الحق من عندنا", "محمد ﷺ رسولاً مبيّناً."], ["لولا أوتي مثل ما أوتي موسى", "هلّا أُعطي مثل ما أُعطي موسى من الآيات كالعصا واليد."], ["أوَلم يكفروا بما أوتي موسى من قبل", "لما أخبرهم اليهود أنهم يجدون نعت محمد في التوراة كفروا بهذا الخبر."], ["سحران تظاهرا", "التوراة والقرآن سحران يعاون بعضهما بعضاً."], ["فإن لم يستجيبوا لك", "بالإتيان بكتاب أهدى منهما."], ["فاعلم أنما يتّبعون أهواءهم", "في كفرهم، فلا عقل ولا كتاب منير."], ["ومن أضلّ ممن اتّبع هواه", "لا أضلّ منه قط."], ["ولقد وصّلنا لهم القول", "بأخبار الأولين وما أحللنا بهم من نقمتنا لعلهم يتّعظون."]], "m": "لما جاءهم محمد ﷺ قالوا: هلّا أوتي مثل ما أوتي موسى من الآيات حتى نؤمن به؟ قال تعالى: أوَلم يكفروا بما أوتي موسى من قبل؟ وذلك أن قريشاً بعثت إلى يهود المدينة تسألهم عن صدق محمد، فأجابوهم بأنهم يجدون نعته في التوراة، فقالوا: التوراة والقرآن سحران تعاونا، وإنا بكلٍّ كافرون؛ فكيف يطالبون اليوم بمثل ما أوتي موسى؟ قل: فأتوا بكتاب من عند الله هو أهدى منهما أتّبعه إن كنتم صادقين. فإن لم يستجيبوا لك، ومن أين لهم ذلك، فاعلم أنما يتّبعون أهواءهم، فلا عقل ولا نقل عندهم، ومن أضلّ ممن اتّبع هواه بغير هدى من الله؟ إن الله لا يهدي القوم الظالمين الذين توغّلوا في الظلم شركاً ومعاصي. ولقد وصّلنا لهم القول بأخبار الماضين وما أحللنا بهم من نقمتنا، مبيّناً موصولاً أوله بآخره، لعلهم يتذكّرون فيؤمنوا.", "h": ["بيان تناقض المشركين، وكل من يتّبع الهوى ويترك الهدى الإلهي.", "بيان تحدّي المشركين بالإتيان بكتاب من عند الله وعجزهم عن ذلك، فبان بذلك أنهم يتّبعون أهواءهم.", "بيان سنّة الله في حرمان المتوغّلين في الظلم من الهداية الإلهية.", "بيان أن الله عز وجل وصّل القول لأهل مكة مفصّلاً مبيّناً لهدايتهم، فله الحمد وله المنة."], "k": "«ومن أضلّ ممن اتّبع هواه بغير هدى من الله»… في أي قرار أخير اتّبعت هواي وسمّيته رأياً؟"}, {"lbl": "الآيات ٥٢ – ٥٥", "q": "ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ مِن قَبۡلِهِۦ هُم بِهِۦ يُؤۡمِنُونَ ﴿٥٢﴾ وَإِذَا يُتۡلَىٰ عَلَيۡهِمۡ قَالُوٓاْ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبۡلِهِۦ مُسۡلِمِينَ ﴿٥٣﴾ أُوْلَـٰٓئِكَ يُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَيۡنِ بِمَا صَبَرُواْ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿٥٤﴾ وَإِذَا سَمِعُواْ ٱللَّغۡوَ أَعۡرَضُواْ عَنۡهُ وَقَالُواْ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ سَلَٰمٌ عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ ﴿٥٥﴾", "w": [["الذين آتيناهم الكتاب من قبله", "التوراة والإنجيل من قبل القرآن."], ["وإذا يُتلى عليهم", "القرآن."], ["إنا كنا من قبله مسلمين", "منقادين لله مطيعين لأمره."], ["أجرهم مرتين", "يُضاعف لهم الثواب، لأنهم آمنوا بنبيّهم وآمنوا بمحمد ﷺ."], ["ويدرؤون بالحسنة السيئة", "يدفعون بالحسنة من القول والفعل السيئة منهما."], ["وإذا سمعوا اللغو أعرضوا عنه", "الكلام اللاغي الذي لا يحقق درهماً للمعاش ولا حسنة للمعاد."], ["سلام عليكم", "سلام المتاركة، قالوا قولاً يسلمون به."], ["لا نبتغي الجاهلين", "لا نطلب صحبة أهل الجهل لما فيها من الأذى."]], "m": "وتوصيل القول يشمل أهل الكتاب أيضاً، فذكر تعالى أن فريقاً منهم يؤمنون بمحمد ﷺ لأنه الحق: الذين آتيناهم الكتاب من قبل القرآن هم به يؤمنون، وإذا يُتلى عليهم قالوا: آمنا به إنه الحق من ربنا، إنا كنا من قبله موحّدين منقادين نعبد الله بما شرع على لسان موسى وعيسى ﵉، منهم عبد الله بن سلام وسلمان الفارسي وغيرهما. أولئك يؤتون أجرهم مضاعفاً بما صبروا، لأنهم آمنوا برسولهم ثم آمنوا بمحمد ﷺ، ويدفعون بالصفح والعفو أذى السب والشتم، ومما رزقناهم يتصدّقون. وإذا سمعوا اللغو من سفهاء الناس أعرضوا عنه وقالوا: لنا أعمالنا ولكم أعمالكم، سلام عليكم، اتركونا، لا نبتغي صحبة الجاهلين لما فيها من الأذى.", "h": ["بيان فضل أهل الكتاب إذا آمنوا بالنبي الأمي وكتابه وأسلموا لله رب العالمين.", "فضيلة من يدرأ بالحسنة السيئة، وينفق مما رزقه الله.", "فضيلة من يُعرض عن اللغو وأهل الجهالات ويقول ما يسلم به من القول، وهذا السلام ليس سلام تحية وإنما هو سلام متاركة."], "k": "«وإذا سمعوا اللغو أعرضوا عنه»… كم من وقتي يذهب في لغو لا ينفع معاشاً ولا معاداً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 280;
insert into public.tdb_cards(topic, i, body) select 280, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٤ – ٤٧", "q": "وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِيِّ إِذۡ قَضَيۡنَآ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّـٰهِدِينَ ﴿٤٤﴾ وَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ ﴿٤٥﴾ وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذۡ نَادَيۡنَا وَلَٰكِن رَّحۡمَةٗ مِّن رَّبِّكَ لِتُنذِرَ قَوۡمٗا مَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٤٦﴾ وَلَوۡلَآ أَن تُصِيبَهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَيَقُولُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿٤٧﴾", "w": [["وما كنت بجانب الغربي", "لم تكن يا رسولنا حاضراً بالجانب الغربي من الطور."], ["إذ قضينا إلى موسى الأمر", "بالرسالة إلى فرعون وقومه."], ["فتطاول عليهم العمر", "أنشأنا بعد موسى أمماً طالت أعمارهم فنسوا العهود واندرست العلوم."], ["وما كنت ثاوياً في أهل مدين", "مقيماً فيهم فتعرف أخبارهم."], ["إذ نادينا", "موسى، وأوحينا إليه ما أوحينا."], ["ما أتاهم من نذير من قبلك", "أهل مكة والعرب كافة."], ["ولولا أن تصيبهم مصيبة", "فيقولوا: هلّا أرسلت إلينا رسولاً، لعاجلناهم بالعقوبة ولما أرسلناك إليهم."]], "m": "بعد انتهاء قصص موسى، وكان كله شاهداً على نبوة محمد ﷺ، قال تعالى: وما كنت حاضراً بالجانب الغربي إذ أرسلنا موسى إلى فرعون، فكيف علمت هذا لولا أنك رسول حق؟ ولكنا أنشأنا أمماً بعد موسى طالت أعمارهم فنسوا العهود واندرست العلوم وانقطع الوحي، فجئنا بك رسولاً وأوحينا إليك خبر موسى وغيره. وما كنت مقيماً في أهل مدين تتلو عليهم آياتنا، فكيف عرفت إقامة موسى بينهم عشر سنين، ولكنا كنا مرسلين. وما كنت بجانب الطور إذ نادينا موسى، ولكن أرسلناك رحمة من ربك لتنذر قوماً ما أتاهم من نذير من قبلك، أهل مكة والعرب، لعلهم يتّعظون. ولولا أن يقولوا إذا أصابتهم عقوبة بما قدّمت أيديهم من الشرك: ربنا هلّا أرسلت إلينا رسولاً فنتّبع آياتك، لعاجلناهم بالعذاب ولما أرسلناك إليهم.", "h": ["تقرير النبوة المحمدية بأقوى الأدلة العقلية.", "بعثة الرسول محمد ﷺ جاءت في أوانها واشتداد الحاجة إليها.", "البعثة المحمدية رحمة إلهية رحم الله بها العالمين."], "k": "«ولكن رحمة من ربك»… الرسالة التي بين يديّ رحمة جاءتني بلا طلب؛ فكيف أشكرها؟"}, {"lbl": "الآيات ٤٨ – ٥١", "q": "فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُواْ لَوۡلَآ أُوتِيَ مِثۡلَ مَآ أُوتِيَ مُوسَىٰٓۚ أَوَلَمۡ يَكۡفُرُواْ بِمَآ أُوتِيَ مُوسَىٰ مِن قَبۡلُۖ قَالُواْ سِحۡرَانِ تَظَٰهَرَا وَقَالُوٓاْ إِنَّا بِكُلّٖ كَٰفِرُونَ ﴿٤٨﴾ قُلۡ فَأۡتُواْ بِكِتَٰبٖ مِّنۡ عِندِ ٱللَّهِ هُوَ أَهۡدَىٰ مِنۡهُمَآ أَتَّبِعۡهُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤٩﴾ فَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٥٠﴾ ۞وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٥١﴾", "w": [["فلما جاءهم الحق من عندنا", "محمد ﷺ رسولاً مبيّناً."], ["لولا أوتي مثل ما أوتي موسى", "هلّا أُعطي مثل ما أُعطي موسى من الآيات كالعصا واليد."], ["أوَلم يكفروا بما أوتي موسى من قبل", "لما أخبرهم اليهود أنهم يجدون نعت محمد في التوراة كفروا بهذا الخبر."], ["سحران تظاهرا", "التوراة والقرآن سحران يعاون بعضهما بعضاً."], ["فإن لم يستجيبوا لك", "بالإتيان بكتاب أهدى منهما."], ["فاعلم أنما يتّبعون أهواءهم", "في كفرهم، فلا عقل ولا كتاب منير."], ["ومن أضلّ ممن اتّبع هواه", "لا أضلّ منه قط."], ["ولقد وصّلنا لهم القول", "بأخبار الأولين وما أحللنا بهم من نقمتنا لعلهم يتّعظون."]], "m": "لما جاءهم محمد ﷺ قالوا: هلّا أوتي مثل ما أوتي موسى من الآيات حتى نؤمن به؟ قال تعالى: أوَلم يكفروا بما أوتي موسى من قبل؟ وذلك أن قريشاً بعثت إلى يهود المدينة تسألهم عن صدق محمد، فأجابوهم بأنهم يجدون نعته في التوراة، فقالوا: التوراة والقرآن سحران تعاونا، وإنا بكلٍّ كافرون؛ فكيف يطالبون اليوم بمثل ما أوتي موسى؟ قل: فأتوا بكتاب من عند الله هو أهدى منهما أتّبعه إن كنتم صادقين. فإن لم يستجيبوا لك، ومن أين لهم ذلك، فاعلم أنما يتّبعون أهواءهم، فلا عقل ولا نقل عندهم، ومن أضلّ ممن اتّبع هواه بغير هدى من الله؟ إن الله لا يهدي القوم الظالمين الذين توغّلوا في الظلم شركاً ومعاصي. ولقد وصّلنا لهم القول بأخبار الماضين وما أحللنا بهم من نقمتنا، مبيّناً موصولاً أوله بآخره، لعلهم يتذكّرون فيؤمنوا.", "h": ["بيان تناقض المشركين، وكل من يتّبع الهوى ويترك الهدى الإلهي.", "بيان تحدّي المشركين بالإتيان بكتاب من عند الله وعجزهم عن ذلك، فبان بذلك أنهم يتّبعون أهواءهم.", "بيان سنّة الله في حرمان المتوغّلين في الظلم من الهداية الإلهية.", "بيان أن الله عز وجل وصّل القول لأهل مكة مفصّلاً مبيّناً لهدايتهم، فله الحمد وله المنة."], "k": "«ومن أضلّ ممن اتّبع هواه بغير هدى من الله»… في أي قرار أخير اتّبعت هواي وسمّيته رأياً؟"}, {"lbl": "الآيات ٥٢ – ٥٥", "q": "ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ مِن قَبۡلِهِۦ هُم بِهِۦ يُؤۡمِنُونَ ﴿٥٢﴾ وَإِذَا يُتۡلَىٰ عَلَيۡهِمۡ قَالُوٓاْ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبۡلِهِۦ مُسۡلِمِينَ ﴿٥٣﴾ أُوْلَـٰٓئِكَ يُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَيۡنِ بِمَا صَبَرُواْ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿٥٤﴾ وَإِذَا سَمِعُواْ ٱللَّغۡوَ أَعۡرَضُواْ عَنۡهُ وَقَالُواْ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ سَلَٰمٌ عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ ﴿٥٥﴾", "w": [["الذين آتيناهم الكتاب من قبله", "التوراة والإنجيل من قبل القرآن."], ["وإذا يُتلى عليهم", "القرآن."], ["إنا كنا من قبله مسلمين", "منقادين لله مطيعين لأمره."], ["أجرهم مرتين", "يُضاعف لهم الثواب، لأنهم آمنوا بنبيّهم وآمنوا بمحمد ﷺ."], ["ويدرؤون بالحسنة السيئة", "يدفعون بالحسنة من القول والفعل السيئة منهما."], ["وإذا سمعوا اللغو أعرضوا عنه", "الكلام اللاغي الذي لا يحقق درهماً للمعاش ولا حسنة للمعاد."], ["سلام عليكم", "سلام المتاركة، قالوا قولاً يسلمون به."], ["لا نبتغي الجاهلين", "لا نطلب صحبة أهل الجهل لما فيها من الأذى."]], "m": "وتوصيل القول يشمل أهل الكتاب أيضاً، فذكر تعالى أن فريقاً منهم يؤمنون بمحمد ﷺ لأنه الحق: الذين آتيناهم الكتاب من قبل القرآن هم به يؤمنون، وإذا يُتلى عليهم قالوا: آمنا به إنه الحق من ربنا، إنا كنا من قبله موحّدين منقادين نعبد الله بما شرع على لسان موسى وعيسى ﵉، منهم عبد الله بن سلام وسلمان الفارسي وغيرهما. أولئك يؤتون أجرهم مضاعفاً بما صبروا، لأنهم آمنوا برسولهم ثم آمنوا بمحمد ﷺ، ويدفعون بالصفح والعفو أذى السب والشتم، ومما رزقناهم يتصدّقون. وإذا سمعوا اللغو من سفهاء الناس أعرضوا عنه وقالوا: لنا أعمالنا ولكم أعمالكم، سلام عليكم، اتركونا، لا نبتغي صحبة الجاهلين لما فيها من الأذى.", "h": ["بيان فضل أهل الكتاب إذا آمنوا بالنبي الأمي وكتابه وأسلموا لله رب العالمين.", "فضيلة من يدرأ بالحسنة السيئة، وينفق مما رزقه الله.", "فضيلة من يُعرض عن اللغو وأهل الجهالات ويقول ما يسلم به من القول، وهذا السلام ليس سلام تحية وإنما هو سلام متاركة."], "k": "«وإذا سمعوا اللغو أعرضوا عنه»… كم من وقتي يذهب في لغو لا ينفع معاشاً ولا معاداً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (281, 28, 56, 67, 'سورة القصص ٥٦ – ٦٧', '«إنك لا تهدي من أحببت»، و«وما أوتيتم من شيء فمتاع الحياة الدنيا»، و«ماذا أجبتم المرسلين»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 281) = $j$[{"lbl": "الآيات ٥٦ – ٥٩", "q": "إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ﴿٥٦﴾ وَقَالُوٓاْ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَآۚ أَوَلَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنٗا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٖ رِّزۡقٗا مِّن لَّدُنَّا وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٥٧﴾ وَكَمۡ أَهۡلَكۡنَا مِن قَرۡيَةِۭ بَطِرَتۡ مَعِيشَتَهَاۖ فَتِلۡكَ مَسَٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِيلٗاۖ وَكُنَّا نَحۡنُ ٱلۡوَٰرِثِينَ ﴿٥٨﴾ وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ يَبۡعَثَ فِيٓ أُمِّهَا رَسُولٗا يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِي ٱلۡقُرَىٰٓ إِلَّا وَأَهۡلُهَا ظَٰلِمُونَ ﴿٥٩﴾", "w": [["إنك لا تهدي من أحببت", "هدايته، كأبي طالب، بأن يُسلم ويحسن إسلامه."], ["وقالوا", "مشركو قريش."], ["إن نتّبع الهدى معك", "إن نتّبعك على الإسلام."], ["نُتخطّف من أرضنا", "تجترئ علينا قبائل العرب فيأخذوننا."], ["يُجبى إليه ثمرات كل شيء", "يُحمل ويُساق إليه من كل الأنحاء."], ["رزقاً من لدنّا", "رزقاً لكم من عندنا يا أهل الحرم."], ["بطرت معيشتها", "كفرت نعمة الله عليها فأسرفت في الذنوب."], ["في أمّها رسولاً", "في أعظم مدنها، وهي العاصمة."], ["إلا وأهلها ظالمون", "بالتكذيب للرسول والإصرار على الشرك والمعاصي."]], "m": "نزلت «إنك لا تهدي من أحببت» في أبي طالب عمّ الرسول ﷺ، كان يرغب في إسلامه لما له من وقوف إلى جانبه، فلما حضرته الوفاة عرض عليه الشهادتين، وكان حوله مشايخ قريش ينهونه حتى قال: هو على ملة عبد المطلب، ومات، فقال ﷺ: «لأستغفرنّ لك ما لم أُنه عنك»، فنُهي، ونزلت الآية تعزية له: إنك لا تهدي من أحببت هدايته، ولكن الله يهدي من يشاء، وهو أعلم بالمهتدين. وقال بعض رجالات قريش معتذرين: إن نتّبع الهدى معك تتألّب علينا العرب فنُتخطّف من أرضنا ونُحرم الأمن والرخاء. فردّ تعالى هذا الاعتذار البارد: أوَلم نمكّن لهم حرماً آمناً لا يُسفك فيه دم، يُساق إليه ثمرات كل شيء رزقاً من عندنا؟ أليس الذي جعل لهم ذلك قادراً على أن يؤمنهم إذا أسلموا؟ ولكن أكثرهم لا يعلمون. وكم أهلكنا من قرية بطرت معيشتها فلم تشكر، فتلك مساكنهم لم تُسكن من بعدهم إلا قليلاً، وكنا نحن الوارثين. وما كان ربك مهلك القرى حتى يبعث في أعظم مدنها رسولاً يتلو عليهم آياتنا، وما كنا مهلكي القرى إلا وأهلها ظالمون، وهذا من عدل الله ورحمته.", "h": ["تقرير مبدأ: لا هادي إلا الله؛ والهداية المنفية هي إنارة القلب والتوفيق للإيمان، والمثبتة للرسول هي هداية الدعوة والإرشاد.", "مظاهر قدرة الله وعلمه ورحمته فيما ألقاه في قلوب العرب من تعظيم الحرم وأهله، ليهيّئ لسكانه أمناً وعيشاً.", "من رحمة الله وعدله ألا يهلك أمة إلا إذا توفّر لهلاكها شرطان: أن يبعث فيهم رسولاً يتلو عليهم آيات الله، وأن يظلم أهلها بالتكذيب والإصرار على الكفر والمعاصي.", "التاريخ يعيد نفسه، فما اعتذر به المشركون عن قبول الإسلام بحجة تألّب العرب عليهم وتعطيل تجارتهم يعتذر به اليوم كثيرون عن العمل بأحكام الدين، خوفاً على مصالحهم الدنيوية."], "k": "«إن نتّبع الهدى معك نُتخطّف من أرضنا»… ما الخوف الدنيوي الذي يؤخّرني عن طاعة أعرفها؟"}, {"lbl": "الآيتان ٦٠ – ٦١", "q": "وَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ ﴿٦٠﴾ أَفَمَن وَعَدۡنَٰهُ وَعۡدًا حَسَنٗا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعۡنَٰهُ مَتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا ثُمَّ هُوَ يَوۡمَ ٱلۡقِيَٰمَةِ مِنَ ٱلۡمُحۡضَرِينَ ﴿٦١﴾", "w": [["وما أوتيتم من شيء", "وما أعطاكم الله من مال أو متاع."], ["فمتاع الحياة الدنيا وزينتها", "تتمتّعون به وتتزيّنون ثم يزول ويفنى."], ["وما عند الله خير وأبقى", "من ثواب، وهو الجنة."], ["أفلا تعقلون", "لأن من يؤثر القليل الفاني على الكثير الباقي لا عقل له."], ["وعداً حسناً", "الجنة."], ["فهو لاقيه", "مصيبه وظافر به لا محالة."], ["من المحضرين", "في نار جهنم."]], "m": "لما اعتذر المشركون عن الإسلام بعذر مادي بحت قال تعالى لهم ولكل من يؤثر الدنيا فيستحلّ المحرمات ويضيّع الفرائض لتعارضها في نظره مع جمع المال: وما أوتيتم من مال ومتاع وإن كثر فهو متاع الحياة الدنيا وزينتها، تتمتّعون به أياماً أو أعواماً ثم ينفد، أو تموتون عنه وتتركونه، وما عند الله من نعيم الجنة خير في نوعه، خالٍ من المنغّصات، وأبقى في مدته لا يبلى ولا يفنى، أفلا تعقلون يا من تؤثرون الفاني على الباقي؟ أفمن وعدناه الجنة، وهو المؤمن الصادق المؤكّد إيمانه بصالح عمله، فهو لاقٍ موعده بإذن الله بمجرد أن تعرج روحه، كمن متّعناه متاع الحياة الدنيا يأكل ويشرب كالبهائم، ثم هو يوم القيامة من المحضرين في العذاب؟ لا يستويان أبداً.", "h": ["فائدة العقل أن يعقل صاحبه عما يضرّه ويبعثه على ما ينفعه، فإن لم يفعل ذلك فوجوده كعدمه.", "بيان فضل الآخرة على الدنيا.", "وعد الله للمؤمن بالجنة خير مما يُؤتاه الكافر من مال ومتاع وزينة في الحياة الدنيا."], "k": "«وما عند الله خير وأبقى أفلا تعقلون»… أي متاع أطارده اليوم يستحق أن أبيع به ما يبقى؟"}, {"lbl": "الآيات ٦٢ – ٦٧", "q": "وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ ﴿٦٢﴾ قَالَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَـٰٓؤُلَآءِ ٱلَّذِينَ أَغۡوَيۡنَآ أَغۡوَيۡنَٰهُمۡ كَمَا غَوَيۡنَاۖ تَبَرَّأۡنَآ إِلَيۡكَۖ مَا كَانُوٓاْ إِيَّانَا يَعۡبُدُونَ ﴿٦٣﴾ وَقِيلَ ٱدۡعُواْ شُرَكَآءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَرَأَوُاْ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُواْ يَهۡتَدُونَ ﴿٦٤﴾ وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ مَاذَآ أَجَبۡتُمُ ٱلۡمُرۡسَلِينَ ﴿٦٥﴾ فَعَمِيَتۡ عَلَيۡهِمُ ٱلۡأَنۢبَآءُ يَوۡمَئِذٖ فَهُمۡ لَا يَتَسَآءَلُونَ ﴿٦٦﴾ فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلۡمُفۡلِحِينَ ﴿٦٧﴾", "w": [["ويوم يناديهم", "الرب سبحانه وتعالى."], ["الذين كنتم تزعمون", "أنهم شركاء لي فعبدتموهم معي."], ["حقّ عليهم القول", "وجب عليهم العذاب، وهم أئمة الضلال."], ["أغويناهم كما غوينا", "لم نكرههم على الغيّ."], ["تبرّأنا إليك", "منهم، ما كانوا يعبدوننا بل كانوا يعبدون أهواءهم."], ["وقيل ادعوا شركاءكم", "نادوهم ليخلّصوكم."], ["لو أنهم كانوا يهتدون", "لما رأوا العذاب ودّوا لو كانوا في الدنيا من المهتدين."], ["فعميت عليهم الأنباء", "خفيت عليهم الأخبار التي يمكنهم أن يحتجّوا بها."], ["فهم لا يتساءلون", "انقطعوا عن الكلام."], ["فعسى أن يكون من المفلحين", "الفائزين، وعسى من الله لتحقيق الموعود به."]], "m": "واذكر يوم ينادي ربك المشركين الذين ماتوا على شركهم فيقول: أين شركائي الذين كنتم تزعمون؟ سؤال تقريع، والتقريع عذاب روحي أشد من العذاب الجسماني. قال أئمة الضلال الذين حقّ عليهم العذاب: ربنا هؤلاء الذين أغوينا، أغويناهم كما غوينا، ما أكرهناهم، تبرّأنا إليك منهم، ما كانوا إيانا يعبدون بل يعبدون أهواءهم. وقيل للمشركين تهكّماً: ادعوا شركاءكم لينصروكم، فدعوهم فلم يستجيبوا لهم، ورأوا العذاب بأعينهم فودّوا لو كانوا في الدنيا من المهتدين. ويوم يناديهم فيقول: ماذا أجبتم المرسلين؟ فخفيت عليهم الحجج فلم يجدوا حجة واحدة، فهم لا يسأل بعضهم بعضاً لأنهم علموا أنهم صالو الجحيم. فأما من تاب اليوم من الشرك وآمن وعمل صالحاً بأداء الفرائض فعسى أن يكون من الفائزين بالنجاة ودخول الجنة، فهذه دعوة سخيّة لكل مشرك وفاسق أن يتخلّى عن الباطل.", "h": ["التنديد بالشرك والمشركين.", "براءة الرؤساء في الضلالة من المرؤوسين.", "التحذير من الغواية، وهي الضلال والانغماس في الذنوب والآثام.", "خذلان المعبودين عابديهم يوم القيامة وتبرّؤهم منهم.", "باب التوبة مفتوح لكل عبد مهما كانت ذنوبه، ولا يهلك على الله إلا هالك."], "k": "«ماذا أجبتم المرسلين»… سؤال سيُطرح عليّ يومها؛ فماذا أُعدّ له من جواب اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 281;
insert into public.tdb_cards(topic, i, body) select 281, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٦ – ٥٩", "q": "إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ﴿٥٦﴾ وَقَالُوٓاْ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَآۚ أَوَلَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنٗا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٖ رِّزۡقٗا مِّن لَّدُنَّا وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٥٧﴾ وَكَمۡ أَهۡلَكۡنَا مِن قَرۡيَةِۭ بَطِرَتۡ مَعِيشَتَهَاۖ فَتِلۡكَ مَسَٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِيلٗاۖ وَكُنَّا نَحۡنُ ٱلۡوَٰرِثِينَ ﴿٥٨﴾ وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ يَبۡعَثَ فِيٓ أُمِّهَا رَسُولٗا يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِي ٱلۡقُرَىٰٓ إِلَّا وَأَهۡلُهَا ظَٰلِمُونَ ﴿٥٩﴾", "w": [["إنك لا تهدي من أحببت", "هدايته، كأبي طالب، بأن يُسلم ويحسن إسلامه."], ["وقالوا", "مشركو قريش."], ["إن نتّبع الهدى معك", "إن نتّبعك على الإسلام."], ["نُتخطّف من أرضنا", "تجترئ علينا قبائل العرب فيأخذوننا."], ["يُجبى إليه ثمرات كل شيء", "يُحمل ويُساق إليه من كل الأنحاء."], ["رزقاً من لدنّا", "رزقاً لكم من عندنا يا أهل الحرم."], ["بطرت معيشتها", "كفرت نعمة الله عليها فأسرفت في الذنوب."], ["في أمّها رسولاً", "في أعظم مدنها، وهي العاصمة."], ["إلا وأهلها ظالمون", "بالتكذيب للرسول والإصرار على الشرك والمعاصي."]], "m": "نزلت «إنك لا تهدي من أحببت» في أبي طالب عمّ الرسول ﷺ، كان يرغب في إسلامه لما له من وقوف إلى جانبه، فلما حضرته الوفاة عرض عليه الشهادتين، وكان حوله مشايخ قريش ينهونه حتى قال: هو على ملة عبد المطلب، ومات، فقال ﷺ: «لأستغفرنّ لك ما لم أُنه عنك»، فنُهي، ونزلت الآية تعزية له: إنك لا تهدي من أحببت هدايته، ولكن الله يهدي من يشاء، وهو أعلم بالمهتدين. وقال بعض رجالات قريش معتذرين: إن نتّبع الهدى معك تتألّب علينا العرب فنُتخطّف من أرضنا ونُحرم الأمن والرخاء. فردّ تعالى هذا الاعتذار البارد: أوَلم نمكّن لهم حرماً آمناً لا يُسفك فيه دم، يُساق إليه ثمرات كل شيء رزقاً من عندنا؟ أليس الذي جعل لهم ذلك قادراً على أن يؤمنهم إذا أسلموا؟ ولكن أكثرهم لا يعلمون. وكم أهلكنا من قرية بطرت معيشتها فلم تشكر، فتلك مساكنهم لم تُسكن من بعدهم إلا قليلاً، وكنا نحن الوارثين. وما كان ربك مهلك القرى حتى يبعث في أعظم مدنها رسولاً يتلو عليهم آياتنا، وما كنا مهلكي القرى إلا وأهلها ظالمون، وهذا من عدل الله ورحمته.", "h": ["تقرير مبدأ: لا هادي إلا الله؛ والهداية المنفية هي إنارة القلب والتوفيق للإيمان، والمثبتة للرسول هي هداية الدعوة والإرشاد.", "مظاهر قدرة الله وعلمه ورحمته فيما ألقاه في قلوب العرب من تعظيم الحرم وأهله، ليهيّئ لسكانه أمناً وعيشاً.", "من رحمة الله وعدله ألا يهلك أمة إلا إذا توفّر لهلاكها شرطان: أن يبعث فيهم رسولاً يتلو عليهم آيات الله، وأن يظلم أهلها بالتكذيب والإصرار على الكفر والمعاصي.", "التاريخ يعيد نفسه، فما اعتذر به المشركون عن قبول الإسلام بحجة تألّب العرب عليهم وتعطيل تجارتهم يعتذر به اليوم كثيرون عن العمل بأحكام الدين، خوفاً على مصالحهم الدنيوية."], "k": "«إن نتّبع الهدى معك نُتخطّف من أرضنا»… ما الخوف الدنيوي الذي يؤخّرني عن طاعة أعرفها؟"}, {"lbl": "الآيتان ٦٠ – ٦١", "q": "وَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ ﴿٦٠﴾ أَفَمَن وَعَدۡنَٰهُ وَعۡدًا حَسَنٗا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعۡنَٰهُ مَتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا ثُمَّ هُوَ يَوۡمَ ٱلۡقِيَٰمَةِ مِنَ ٱلۡمُحۡضَرِينَ ﴿٦١﴾", "w": [["وما أوتيتم من شيء", "وما أعطاكم الله من مال أو متاع."], ["فمتاع الحياة الدنيا وزينتها", "تتمتّعون به وتتزيّنون ثم يزول ويفنى."], ["وما عند الله خير وأبقى", "من ثواب، وهو الجنة."], ["أفلا تعقلون", "لأن من يؤثر القليل الفاني على الكثير الباقي لا عقل له."], ["وعداً حسناً", "الجنة."], ["فهو لاقيه", "مصيبه وظافر به لا محالة."], ["من المحضرين", "في نار جهنم."]], "m": "لما اعتذر المشركون عن الإسلام بعذر مادي بحت قال تعالى لهم ولكل من يؤثر الدنيا فيستحلّ المحرمات ويضيّع الفرائض لتعارضها في نظره مع جمع المال: وما أوتيتم من مال ومتاع وإن كثر فهو متاع الحياة الدنيا وزينتها، تتمتّعون به أياماً أو أعواماً ثم ينفد، أو تموتون عنه وتتركونه، وما عند الله من نعيم الجنة خير في نوعه، خالٍ من المنغّصات، وأبقى في مدته لا يبلى ولا يفنى، أفلا تعقلون يا من تؤثرون الفاني على الباقي؟ أفمن وعدناه الجنة، وهو المؤمن الصادق المؤكّد إيمانه بصالح عمله، فهو لاقٍ موعده بإذن الله بمجرد أن تعرج روحه، كمن متّعناه متاع الحياة الدنيا يأكل ويشرب كالبهائم، ثم هو يوم القيامة من المحضرين في العذاب؟ لا يستويان أبداً.", "h": ["فائدة العقل أن يعقل صاحبه عما يضرّه ويبعثه على ما ينفعه، فإن لم يفعل ذلك فوجوده كعدمه.", "بيان فضل الآخرة على الدنيا.", "وعد الله للمؤمن بالجنة خير مما يُؤتاه الكافر من مال ومتاع وزينة في الحياة الدنيا."], "k": "«وما عند الله خير وأبقى أفلا تعقلون»… أي متاع أطارده اليوم يستحق أن أبيع به ما يبقى؟"}, {"lbl": "الآيات ٦٢ – ٦٧", "q": "وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ ﴿٦٢﴾ قَالَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَـٰٓؤُلَآءِ ٱلَّذِينَ أَغۡوَيۡنَآ أَغۡوَيۡنَٰهُمۡ كَمَا غَوَيۡنَاۖ تَبَرَّأۡنَآ إِلَيۡكَۖ مَا كَانُوٓاْ إِيَّانَا يَعۡبُدُونَ ﴿٦٣﴾ وَقِيلَ ٱدۡعُواْ شُرَكَآءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَرَأَوُاْ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُواْ يَهۡتَدُونَ ﴿٦٤﴾ وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ مَاذَآ أَجَبۡتُمُ ٱلۡمُرۡسَلِينَ ﴿٦٥﴾ فَعَمِيَتۡ عَلَيۡهِمُ ٱلۡأَنۢبَآءُ يَوۡمَئِذٖ فَهُمۡ لَا يَتَسَآءَلُونَ ﴿٦٦﴾ فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلۡمُفۡلِحِينَ ﴿٦٧﴾", "w": [["ويوم يناديهم", "الرب سبحانه وتعالى."], ["الذين كنتم تزعمون", "أنهم شركاء لي فعبدتموهم معي."], ["حقّ عليهم القول", "وجب عليهم العذاب، وهم أئمة الضلال."], ["أغويناهم كما غوينا", "لم نكرههم على الغيّ."], ["تبرّأنا إليك", "منهم، ما كانوا يعبدوننا بل كانوا يعبدون أهواءهم."], ["وقيل ادعوا شركاءكم", "نادوهم ليخلّصوكم."], ["لو أنهم كانوا يهتدون", "لما رأوا العذاب ودّوا لو كانوا في الدنيا من المهتدين."], ["فعميت عليهم الأنباء", "خفيت عليهم الأخبار التي يمكنهم أن يحتجّوا بها."], ["فهم لا يتساءلون", "انقطعوا عن الكلام."], ["فعسى أن يكون من المفلحين", "الفائزين، وعسى من الله لتحقيق الموعود به."]], "m": "واذكر يوم ينادي ربك المشركين الذين ماتوا على شركهم فيقول: أين شركائي الذين كنتم تزعمون؟ سؤال تقريع، والتقريع عذاب روحي أشد من العذاب الجسماني. قال أئمة الضلال الذين حقّ عليهم العذاب: ربنا هؤلاء الذين أغوينا، أغويناهم كما غوينا، ما أكرهناهم، تبرّأنا إليك منهم، ما كانوا إيانا يعبدون بل يعبدون أهواءهم. وقيل للمشركين تهكّماً: ادعوا شركاءكم لينصروكم، فدعوهم فلم يستجيبوا لهم، ورأوا العذاب بأعينهم فودّوا لو كانوا في الدنيا من المهتدين. ويوم يناديهم فيقول: ماذا أجبتم المرسلين؟ فخفيت عليهم الحجج فلم يجدوا حجة واحدة، فهم لا يسأل بعضهم بعضاً لأنهم علموا أنهم صالو الجحيم. فأما من تاب اليوم من الشرك وآمن وعمل صالحاً بأداء الفرائض فعسى أن يكون من الفائزين بالنجاة ودخول الجنة، فهذه دعوة سخيّة لكل مشرك وفاسق أن يتخلّى عن الباطل.", "h": ["التنديد بالشرك والمشركين.", "براءة الرؤساء في الضلالة من المرؤوسين.", "التحذير من الغواية، وهي الضلال والانغماس في الذنوب والآثام.", "خذلان المعبودين عابديهم يوم القيامة وتبرّؤهم منهم.", "باب التوبة مفتوح لكل عبد مهما كانت ذنوبه، ولا يهلك على الله إلا هالك."], "k": "«ماذا أجبتم المرسلين»… سؤال سيُطرح عليّ يومها؛ فماذا أُعدّ له من جواب اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (282, 28, 68, 78, 'سورة القصص ٦٨ – ٧٨', '«وربك يخلق ما يشاء ويختار»، و«قل أرأيتم إن جعل الله عليكم الليل سرمداً»، و«إن قارون كان من قوم موسى فبغى عليهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 282) = $j$[{"lbl": "الآيات ٦٨ – ٧٠", "q": "وَرَبُّكَ يَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ سُبۡحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٦٨﴾ وَرَبُّكَ يَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ ﴿٦٩﴾ وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡحَمۡدُ فِي ٱلۡأُولَىٰ وَٱلۡأٓخِرَةِۖ وَلَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٧٠﴾", "w": [["يخلق ما يشاء", "من خلقه."], ["ويختار", "من يشاء لنبوّته وطاعته."], ["ما كان لهم الخيرة", "ليس للمشركين الاختيار في شيء."], ["سبحان الله", "تنزيهاً لله عن الشرك."], ["ما تُكنّ صدورهم", "ما تُسرّ وتُخفي من الكفر وغيره."], ["له الحمد في الأولى", "في الدنيا، لأنه مولى كل نعمة."], ["والآخرة", "في الجنة."], ["وله الحكم", "القضاء النافذ."]], "m": "بعد توبيخ المشركين على شركهم، وكان باختيارهم، كشف تعالى عن خطئهم من وجهين: الأول أنه لا حق لهم في الاختيار، إذ الاختيار لخالق المخلوقات، والثاني أنهم مخلوقون مربوبون يعلمون ذلك، فكان عليهم أن يطلبوا من خالقهم أن يختار لهم ما يعبدون وكيف يعبدون، لا أن يختاروا بأنفسهم. وربك يخلق ما يشاء ويختار من يشاء لما يشاء، وما كان لعبيده الخيرة، بل الذي يختاره الله هو الذي يجب أن يختاره العبد، وكان النبي ﷺ يدعو: «اللهم خِر لي واختر لي»، ويعلّم أصحابه الاستخارة كما يعلّمهم السورة من القرآن. سبحان الله وتعالى عما يشركون، وربك يعلم ما تُكنّ صدورهم وما يعلنون، والذي يعلم الظواهر والبواطن والعواقب هو الذي يختار، أما من لا يعلم ما في صدر أخيه فكيف يصح منه الاختيار؟ وهو الله لا إله إلا هو، له الحمد في الدنيا والآخرة، وله القضاء، وإليه ترجعون.", "h": ["تقرير مبدأ أنه ليس من حق العبد أن يختار إلا ما اختار الله له.", "تعيّن طلب الاختيار في الأمر كله من الله تعالى بقول العبد: «اللهم خِر لي واختر لي».", "تأكيد سنّة الاستخارة، وهي إذا همّ العبد بالأمر صلّى ركعتين في غير وقت كراهة، ثم دعا بدعاء الاستخارة الوارد في الصحيح، وسمّى حاجته من سفر أو زواج أو تجارة ونحوها.", "تقرير التوحيد وإبطال التنديد.", "وجوب حمد الله وشكره على كل حال، لتجدّد النعمة في كل آن."], "k": "«ما كان لهم الخيرة»… في أي أمر قادم أحتاج أن أستخير ربي بدل أن أختار وحدي؟"}, {"lbl": "الآيات ٧١ – ٧٥", "q": "قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ ﴿٧١﴾ قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلنَّهَارَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِلَيۡلٖ تَسۡكُنُونَ فِيهِۚ أَفَلَا تُبۡصِرُونَ ﴿٧٢﴾ وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿٧٣﴾ وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ ﴿٧٤﴾ وَنَزَعۡنَا مِن كُلِّ أُمَّةٖ شَهِيدٗا فَقُلۡنَا هَاتُواْ بُرۡهَٰنَكُمۡ فَعَلِمُوٓاْ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٧٥﴾", "w": [["أرأيتم", "أخبروني."], ["سرمداً", "دائماً، ليلاً واحداً متصلاً لا يعقبه نهار."], ["بليل تسكنون فيه", "تنامون فتسكن جوارحكم وتستريح."], ["ولتبتغوا من فضله", "تطلبوا الرزق في النهار."], ["ولعلكم تشكرون", "كي تشكروا ربكم بطاعته."], ["ونزعنا من كل أمة شهيداً", "أحضرنا من كل أمة نبيّها يشهد عليها."], ["هاتوا برهانكم", "حججكم على صحة الشرك."], ["فعلموا أن الحق لله", "تبيّن لهم أن العبادة والدين الحق لله لا لسواه."], ["وضلّ عنهم ما كانوا يفترون", "غاب عنهم ما كانوا يكذبونه من الأقوال الباطلة."]], "m": "ما زال السياق في تقرير التوحيد: قل للمشركين: أخبروني إن جعل الله عليكم الليل دائماً متصلاً إلى يوم القيامة، من إله غير الله يأتيكم بضياء؟ لا أحد، أفلا تسمعون؟ وأخبروني إن جعل عليكم النهار دائماً إلى يوم القيامة، من إله غير الله يأتيكم بليل تسكنون فيه؟ أفلا تبصرون هذه الآيات؟ ومن رحمته، لا وجوباً عليه، جعل لكم الليل لتسكنوا فيه والنهار لتبتغوا من فضله الرزق، ولعلكم تشكرون، فالليل والنهار ظرف للعبادة التي هي الشكر: الصيام بالنهار، والقيام بالليل. ويوم يناديهم فيقول: أين شركائي الذين كنتم تزعمون؟ سؤال تبكيت، وأحضرنا من كل أمة نبيّها يشهد أنه بلّغ، فقلنا لهم: هاتوا حجتكم على صحة ما كنتم تعبدون، فعلموا أن الحق لله وحده، وغاب عنهم ما كانوا يفترون.", "h": ["إشارة علمية إلى أن السماع يكون مع السكون وقلّة الضجيج، وأن الإبصار يكون مع الضوء ولا يتم مع الظلام.", "البرهنة القوية على وجوب توحيد الله، إذ لا رب يدبّر الكون سواه.", "كون الليل والنهار ظرفين للسكون وطلب العيش من رحمة الله، أمر يقتضي شكر الله بحمده وصرف النعمة فيما يرضيه.", "بيان أهوال القيامة بذكر بعض المواقف الصعبة فيها.", "إذا كان يوم القيامة بطل كل كذب، ولم يبق إلا قول الحق والصدق."], "k": "«ومن رحمته جعل لكم الليل والنهار»… تعاقب يومي رحمة؛ فما نصيب ليلي من القيام ونهاري من الشكر؟"}, {"lbl": "الآيات ٧٦ – ٧٨", "q": "۞إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ ﴿٧٦﴾ وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ ﴿٧٧﴾ قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ ﴿٧٨﴾", "w": [["إن قارون كان من قوم موسى", "ابن عمّ موسى ﵇."], ["فبغى عليهم", "ظلمهم واستطال عليهم."], ["ما إن مفاتحه لتنوء بالعصبة", "أعطاه الله من المال ما يثقل على الجماعة حمل مفاتح خزائنه."], ["لا تفرح إن الله لا يحب الفرحين", "فرح البطر والأشر."], ["وابتغ فيما آتاك الله الدار الآخرة", "اطلب في المال الذي أوتيته الدار الآخرة بفعل الخير."], ["على علم عندي", "لعلم الله تعالى بأني أهل لذلك."], ["وأكثر جمعاً", "للمال."], ["ولا يُسأل عن ذنوبهم المجرمون", "لعلم الله بهم، فيدخلون النار بلا حساب."]], "m": "هذا بداية قصص قارون الباغي، ابن عمّ موسى ﵇، وكان يُلقّب المنوّر لحسن صورته، ونافق كما نافق السامري: إن قارون كان من بني إسرائيل فظلمهم وطغى عليهم، ولعل فرعون أسند إليه إمارة عليهم فأطغته، وآتيناه من الكنوز ما إن مفاتحه لتُثقل الجماعة من الرجال الأقوياء. إذ قال له الصالحون من قومه واعظين: لا تفرح بأموالك فرح البطر، إن الله لا يحب الفرحين المختالين، واطلب فيما آتاك الله الدار الآخرة بالصدقة والإنفاق في وجوه البر كبناء مسجد أو مدرسة أو ملجأ، ولا تنس نصيبك من الدنيا فكُل واشرب والبس واسكن في غير إسراف ولا خيلاء، وأحسن عبادة الله وأحسن إلى عباده كما أحسن الله إليك، ولا تبغ الفساد في الأرض بترك الفرائض وارتكاب المحرمات. فردّ الطاغية: إنما أوتيته على علم عندي، أي آتانيه الله لعلمه بأني أهل له. أوَلم يعلم أن الله قد أهلك من قبله من القرون من هو أشد منه قوة وأكثر مالاً، كعاد وثمود؟ فلو كانت كثرة المال دليلاً على رضا الله ما أهلكهم. ولا يُسأل عن ذنوبهم المجرمون إذا حقّ عليهم العذاب، بل يُؤخذون فجأة.", "h": ["المال والمنصب العالي عرضة لإفساد المرء إلا من رحم الله عز وجل، وقليل ما هم.", "حرمة الفرح بالمال والإمارة إذا كان فرح بطر وفخر وكبر وخيلاء.", "من فضل الله على الأمة أن يوجد فيها علماء ينصحون ويرشدون ويوجّهون.", "من الحزم للمرء أن يطلب بالمال والجاه والمنصب أعلى الدرجات في الجنة.", "حلّية الأكل والشرب من الطيّب واللبس والركوب والسكن من غير إسراف ولا خيلاء ولا كبر.", "العافية والمال وعزّ السلطان يُصاب صاحبها بالاغترار إلا من رحم الله."], "k": "«وأحسن كما أحسن الله إليك»… أعدّ إحسان الله إليّ، ثم أسأل: من أحسنت إليه بالمقابل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 282;
insert into public.tdb_cards(topic, i, body) select 282, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٨ – ٧٠", "q": "وَرَبُّكَ يَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ سُبۡحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٦٨﴾ وَرَبُّكَ يَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ ﴿٦٩﴾ وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡحَمۡدُ فِي ٱلۡأُولَىٰ وَٱلۡأٓخِرَةِۖ وَلَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٧٠﴾", "w": [["يخلق ما يشاء", "من خلقه."], ["ويختار", "من يشاء لنبوّته وطاعته."], ["ما كان لهم الخيرة", "ليس للمشركين الاختيار في شيء."], ["سبحان الله", "تنزيهاً لله عن الشرك."], ["ما تُكنّ صدورهم", "ما تُسرّ وتُخفي من الكفر وغيره."], ["له الحمد في الأولى", "في الدنيا، لأنه مولى كل نعمة."], ["والآخرة", "في الجنة."], ["وله الحكم", "القضاء النافذ."]], "m": "بعد توبيخ المشركين على شركهم، وكان باختيارهم، كشف تعالى عن خطئهم من وجهين: الأول أنه لا حق لهم في الاختيار، إذ الاختيار لخالق المخلوقات، والثاني أنهم مخلوقون مربوبون يعلمون ذلك، فكان عليهم أن يطلبوا من خالقهم أن يختار لهم ما يعبدون وكيف يعبدون، لا أن يختاروا بأنفسهم. وربك يخلق ما يشاء ويختار من يشاء لما يشاء، وما كان لعبيده الخيرة، بل الذي يختاره الله هو الذي يجب أن يختاره العبد، وكان النبي ﷺ يدعو: «اللهم خِر لي واختر لي»، ويعلّم أصحابه الاستخارة كما يعلّمهم السورة من القرآن. سبحان الله وتعالى عما يشركون، وربك يعلم ما تُكنّ صدورهم وما يعلنون، والذي يعلم الظواهر والبواطن والعواقب هو الذي يختار، أما من لا يعلم ما في صدر أخيه فكيف يصح منه الاختيار؟ وهو الله لا إله إلا هو، له الحمد في الدنيا والآخرة، وله القضاء، وإليه ترجعون.", "h": ["تقرير مبدأ أنه ليس من حق العبد أن يختار إلا ما اختار الله له.", "تعيّن طلب الاختيار في الأمر كله من الله تعالى بقول العبد: «اللهم خِر لي واختر لي».", "تأكيد سنّة الاستخارة، وهي إذا همّ العبد بالأمر صلّى ركعتين في غير وقت كراهة، ثم دعا بدعاء الاستخارة الوارد في الصحيح، وسمّى حاجته من سفر أو زواج أو تجارة ونحوها.", "تقرير التوحيد وإبطال التنديد.", "وجوب حمد الله وشكره على كل حال، لتجدّد النعمة في كل آن."], "k": "«ما كان لهم الخيرة»… في أي أمر قادم أحتاج أن أستخير ربي بدل أن أختار وحدي؟"}, {"lbl": "الآيات ٧١ – ٧٥", "q": "قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ ﴿٧١﴾ قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلنَّهَارَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِلَيۡلٖ تَسۡكُنُونَ فِيهِۚ أَفَلَا تُبۡصِرُونَ ﴿٧٢﴾ وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿٧٣﴾ وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ ﴿٧٤﴾ وَنَزَعۡنَا مِن كُلِّ أُمَّةٖ شَهِيدٗا فَقُلۡنَا هَاتُواْ بُرۡهَٰنَكُمۡ فَعَلِمُوٓاْ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٧٥﴾", "w": [["أرأيتم", "أخبروني."], ["سرمداً", "دائماً، ليلاً واحداً متصلاً لا يعقبه نهار."], ["بليل تسكنون فيه", "تنامون فتسكن جوارحكم وتستريح."], ["ولتبتغوا من فضله", "تطلبوا الرزق في النهار."], ["ولعلكم تشكرون", "كي تشكروا ربكم بطاعته."], ["ونزعنا من كل أمة شهيداً", "أحضرنا من كل أمة نبيّها يشهد عليها."], ["هاتوا برهانكم", "حججكم على صحة الشرك."], ["فعلموا أن الحق لله", "تبيّن لهم أن العبادة والدين الحق لله لا لسواه."], ["وضلّ عنهم ما كانوا يفترون", "غاب عنهم ما كانوا يكذبونه من الأقوال الباطلة."]], "m": "ما زال السياق في تقرير التوحيد: قل للمشركين: أخبروني إن جعل الله عليكم الليل دائماً متصلاً إلى يوم القيامة، من إله غير الله يأتيكم بضياء؟ لا أحد، أفلا تسمعون؟ وأخبروني إن جعل عليكم النهار دائماً إلى يوم القيامة، من إله غير الله يأتيكم بليل تسكنون فيه؟ أفلا تبصرون هذه الآيات؟ ومن رحمته، لا وجوباً عليه، جعل لكم الليل لتسكنوا فيه والنهار لتبتغوا من فضله الرزق، ولعلكم تشكرون، فالليل والنهار ظرف للعبادة التي هي الشكر: الصيام بالنهار، والقيام بالليل. ويوم يناديهم فيقول: أين شركائي الذين كنتم تزعمون؟ سؤال تبكيت، وأحضرنا من كل أمة نبيّها يشهد أنه بلّغ، فقلنا لهم: هاتوا حجتكم على صحة ما كنتم تعبدون، فعلموا أن الحق لله وحده، وغاب عنهم ما كانوا يفترون.", "h": ["إشارة علمية إلى أن السماع يكون مع السكون وقلّة الضجيج، وأن الإبصار يكون مع الضوء ولا يتم مع الظلام.", "البرهنة القوية على وجوب توحيد الله، إذ لا رب يدبّر الكون سواه.", "كون الليل والنهار ظرفين للسكون وطلب العيش من رحمة الله، أمر يقتضي شكر الله بحمده وصرف النعمة فيما يرضيه.", "بيان أهوال القيامة بذكر بعض المواقف الصعبة فيها.", "إذا كان يوم القيامة بطل كل كذب، ولم يبق إلا قول الحق والصدق."], "k": "«ومن رحمته جعل لكم الليل والنهار»… تعاقب يومي رحمة؛ فما نصيب ليلي من القيام ونهاري من الشكر؟"}, {"lbl": "الآيات ٧٦ – ٧٨", "q": "۞إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ ﴿٧٦﴾ وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ ﴿٧٧﴾ قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ ﴿٧٨﴾", "w": [["إن قارون كان من قوم موسى", "ابن عمّ موسى ﵇."], ["فبغى عليهم", "ظلمهم واستطال عليهم."], ["ما إن مفاتحه لتنوء بالعصبة", "أعطاه الله من المال ما يثقل على الجماعة حمل مفاتح خزائنه."], ["لا تفرح إن الله لا يحب الفرحين", "فرح البطر والأشر."], ["وابتغ فيما آتاك الله الدار الآخرة", "اطلب في المال الذي أوتيته الدار الآخرة بفعل الخير."], ["على علم عندي", "لعلم الله تعالى بأني أهل لذلك."], ["وأكثر جمعاً", "للمال."], ["ولا يُسأل عن ذنوبهم المجرمون", "لعلم الله بهم، فيدخلون النار بلا حساب."]], "m": "هذا بداية قصص قارون الباغي، ابن عمّ موسى ﵇، وكان يُلقّب المنوّر لحسن صورته، ونافق كما نافق السامري: إن قارون كان من بني إسرائيل فظلمهم وطغى عليهم، ولعل فرعون أسند إليه إمارة عليهم فأطغته، وآتيناه من الكنوز ما إن مفاتحه لتُثقل الجماعة من الرجال الأقوياء. إذ قال له الصالحون من قومه واعظين: لا تفرح بأموالك فرح البطر، إن الله لا يحب الفرحين المختالين، واطلب فيما آتاك الله الدار الآخرة بالصدقة والإنفاق في وجوه البر كبناء مسجد أو مدرسة أو ملجأ، ولا تنس نصيبك من الدنيا فكُل واشرب والبس واسكن في غير إسراف ولا خيلاء، وأحسن عبادة الله وأحسن إلى عباده كما أحسن الله إليك، ولا تبغ الفساد في الأرض بترك الفرائض وارتكاب المحرمات. فردّ الطاغية: إنما أوتيته على علم عندي، أي آتانيه الله لعلمه بأني أهل له. أوَلم يعلم أن الله قد أهلك من قبله من القرون من هو أشد منه قوة وأكثر مالاً، كعاد وثمود؟ فلو كانت كثرة المال دليلاً على رضا الله ما أهلكهم. ولا يُسأل عن ذنوبهم المجرمون إذا حقّ عليهم العذاب، بل يُؤخذون فجأة.", "h": ["المال والمنصب العالي عرضة لإفساد المرء إلا من رحم الله عز وجل، وقليل ما هم.", "حرمة الفرح بالمال والإمارة إذا كان فرح بطر وفخر وكبر وخيلاء.", "من فضل الله على الأمة أن يوجد فيها علماء ينصحون ويرشدون ويوجّهون.", "من الحزم للمرء أن يطلب بالمال والجاه والمنصب أعلى الدرجات في الجنة.", "حلّية الأكل والشرب من الطيّب واللبس والركوب والسكن من غير إسراف ولا خيلاء ولا كبر.", "العافية والمال وعزّ السلطان يُصاب صاحبها بالاغترار إلا من رحم الله."], "k": "«وأحسن كما أحسن الله إليك»… أعدّ إحسان الله إليّ، ثم أسأل: من أحسنت إليه بالمقابل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (283, 28, 79, 88, 'سورة القصص ٧٩ – ٨٨', '«يا ليت لنا مثل ما أوتي قارون»، و«فخسفنا به وبداره الأرض»، و«تلك الدار الآخرة نجعلها للذين لا يريدون علوّاً في الأرض ولا فساداً»، و«كل شيء هالك إلا وجهه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 283) = $j$[{"lbl": "الآيات ٧٩ – ٨٢", "q": "فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِي زِينَتِهِۦۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا يَٰلَيۡتَ لَنَا مِثۡلَ مَآ أُوتِيَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٖ ﴿٧٩﴾ وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّـٰبِرُونَ ﴿٨٠﴾ فَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةٖ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِينَ ﴿٨١﴾ وَأَصۡبَحَ ٱلَّذِينَ تَمَنَّوۡاْ مَكَانَهُۥ بِٱلۡأَمۡسِ يَقُولُونَ وَيۡكَأَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُۖ لَوۡلَآ أَن مَّنَّ ٱللَّهُ عَلَيۡنَا لَخَسَفَ بِنَاۖ وَيۡكَأَنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ ﴿٨٢﴾", "w": [["في زينته", "لباس الأعياد والحفلات الرسمية."], ["يا ليت لنا مثل ما أوتي قارون", "تمنّوا أن لو أُعطوا من المال والزينة ما أُعطي."], ["لذو حظ عظيم", "لذو بخت ونصيب."], ["وقال الذين أوتوا العلم", "العلم الديني بمعرفة الله والدار الآخرة."], ["ويلكم", "حضر هلاككم بتمنّيكم زخرف الدنيا."], ["ولا يُلقّاها إلا الصابرون", "ولا يُوفَّق لقول هذه الكلمة إلا الصابرون على الإيمان والطاعة."], ["فخسفنا به وبداره الأرض", "أسخنا الأرض من تحته فساخت به وبداره ومن معه."], ["تمنّوا مكانه بالأمس", "مكانته من الإمارة والزينة والمال."], ["ويكأنّ الله يبسط الرزق", "أعجب عالماً أن الله يبسط الرزق لمن يشاء."], ["ويقدر", "يضيّق."]], "m": "خرج قارون على قومه في زينته الخاصة من الثياب والمراكب، فقال المفتونون بالدنيا من أهل الغفلة عن الآخرة، وما أكثرهم في كل زمان: يا ليت لنا مثل ما أوتي قارون، إنه لذو بخت عظيم. وقال الذين أوتوا العلم الديني: ويلكم، ثواب الله، وهو الجنة، خير من هذا الزخرف الفاني لمن آمن وعمل صالحاً، ولا يُلقّى هذه الكلمة إلا الصابرون من أهل الإيمان والتقوى لصفاء أرواحهم. فخسفنا به وبداره الأرض انتقاماً منه لكفره وبغيه وكبريائه، فما كان له من جماعة ينصرونه من دون الله، وما كان من المنتصرين لنفسه. وأصبح الذين تمنّوا مكانته بالأمس يقولون: عجباً، إن الله يبسط الرزق لمن يشاء من عباده ويضيّقه، فالبسط والقبض بيده، لولا أن منّ الله علينا لخسف بنا، عجباً إنه لا يفلح الكافرون.", "h": ["بيان أن الفتنة أسرع إلى قلوب الماديّين أبناء الدنيا، والعياذ بالله تعالى.", "بيان موقف أهل العلم الديني، وأنهم حكماء يأمرون بالمعروف وينهون عن المنكر.", "بيان أن البغي يُؤخذ به البغاة في الدنيا ويُعذّبون به في الآخرة.", "بيان أن وجود الإيمان خير من عدمه وإن قلّ، وأن ذا الإيمان أقرب إلى التوبة ممن لا إيمان له."], "k": "«يا ليت لنا مثل ما أوتي قارون»… أي «يا ليت» تتردّد في قلبي حين أرى ما عند الناس؟"}, {"lbl": "الآيتان ٨٣ – ٨٤", "q": "تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ ﴿٨٣﴾ مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَى ٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُواْ يَعۡمَلُونَ ﴿٨٤﴾", "w": [["تلك الدار الآخرة", "الجنة."], ["لا يريدون علوّاً في الأرض", "بغياً ولا استطالة على الناس."], ["ولا فساداً", "بعمل المعاصي."], ["والعاقبة", "المحمودة في الدنيا والآخرة."], ["للمتقين", "الذين يتّقون مساخط الله فلا يعتقدون ولا يقولون ولا يعملون ما لا يرضاه."], ["من جاء بالحسنة", "يوم القيامة، والحسنة أثر طاعة الله يُجزى به العبد."], ["فله خير منها", "تُضاعف له عشرة أضعاف."], ["ومن جاء بالسيئة", "والسيئة أثر معصية الله يُعاقب به العبد إن لم يعفُ الله عنه."]], "m": "تلك الدار الآخرة، الجنة، آخر دار يسكنها المتقون فلا يخرجون منها، نجعلها مأوى للذين لا يريدون استطالة على الناس ولا تكبّراً ولا بغياً، ولا فساداً بارتكاب المعاصي كالقتل والزنا والسرقة وشرب الخمر، والعاقبة المحمودة في الدارين للمتقين الذين يفعلون المأمورات ويجتنبون المنهيات. من جاء يوم القيامة بالطاعات فله جزاء مضاعف، الحسنة بعشر أمثالها وقد تُضاعف إلى أكثر، والمضاعفة للحسنة التي باشرها العبد، لا لحسنة أُخذت له من ظالمه في الدنيا، ولا لحسنة همّ بها ولم يعملها فإنها تُكتب له حسنة واحدة. ومن جاء بالسيئة فلا يُجزى إلا مثلها، لعدل الله ورأفته بعباده، إذ الدنيا دار العمل والآخرة دار الجزاء.", "h": ["حرمة التكبّر والاستطالة على الناس والعمل بالمعاصي، وأنه الفساد في الأرض.", "بيان فضل الله ورحمته وعدله بين عباده بمضاعفة الحسنات وعدم مضاعفة السيئات.", "العاقبة الحسنى، وهي الجنة، لأهل الإيمان والتقوى."], "k": "«للذين لا يريدون علوّاً في الأرض»… الشرط في الإرادة لا الفعل فقط؛ فهل في قلبي رغبة في العلوّ على أحد؟"}, {"lbl": "الآيات ٨٥ – ٨٨", "q": "إِنَّ ٱلَّذِي فَرَضَ عَلَيۡكَ ٱلۡقُرۡءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٖۚ قُل رَّبِّيٓ أَعۡلَمُ مَن جَآءَ بِٱلۡهُدَىٰ وَمَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٨٥﴾ وَمَا كُنتَ تَرۡجُوٓاْ أَن يُلۡقَىٰٓ إِلَيۡكَ ٱلۡكِتَٰبُ إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۖ فَلَا تَكُونَنَّ ظَهِيرٗا لِّلۡكَٰفِرِينَ ﴿٨٦﴾ وَلَا يَصُدُّنَّكَ عَنۡ ءَايَٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَيۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ﴿٨٧﴾ وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۘ لَآ إِلَٰهَ إِلَّا هُوَۚ كُلُّ شَيۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٨٨﴾", "w": [["إن الذي فرض عليك القرآن", "الله الذي أنزله عليك وفرض عليك قراءته والعمل بما فيه وتبليغه."], ["لرادّك إلى معاد", "لمرجعك إلى مكة فاتحاً، إذ معاد الرجل بلده."], ["وما كنت ترجو", "تأمل أن يُنزل عليك القرآن."], ["إلا رحمة من ربك", "لكن برحمة من الله وفضل أنزله عليك."], ["فلا تكوننّ ظهيراً", "من شكر هذه النعمة ألا تكون معيناً للكافرين."], ["ولا يصدّنّك", "لا يصرفنّك عن العمل بآيات الله."], ["ولا تدع مع الله إلهاً آخر", "لا تعبد معه غيره بدعاء ولا ذبح ولا نذر."], ["كل شيء هالك", "فانٍ."], ["إلا وجهه", "إلا الله سبحانه، فلا يهلك كما يهلك ما عداه."]], "m": "هذه خاتمة الدعوة إلى أصول الدين الثلاثة في هذه السورة: إن الذي أنزل عليك القرآن وفرض عليك تلاوته وتبليغه والعمل به لرادّك إلى مكة بعد خروجك منها واشتياقك إليها، وإلى الجنة بعد وفاتك. قل للمشركين الذين اتّهموك بالضلال: ربي أعلم بمن جاء بالهدى ومن هو في ضلال مبين. وما كنت تأمل قبل بعثتك أن يُنزل عليك القرآن، لكن رحمة ربك اقتضت إنزاله لتكون رسول الله للعالمين، فاشكره: فلا تكوننّ معيناً للكافرين، ولا يصرفنّك عن تلاوة آيات الله وإبلاغها والعمل بها بعد إذ أُنزلت إليك، وادع الناس إلى توحيد ربك، ولا تكوننّ من المشركين، ولا تعبد مع الله إلهاً آخر بدعاء ولا نذر ولا ذبح، لا إله إلا هو. كل شيء هالك إلا وجهه، فكل عمل لا يُراد به وجه الله باطل ذاهب بلا مثوبة، وكل شيء سوى الله فانٍ، له القضاء العادل، وإليه ترجعون للحساب والجزاء.", "h": ["معجزة القرآن في وقوع الغيب بعد الإخبار به، حيث عاد الرسول ﷺ إلى مكة فاتحاً.", "مشروعية الملاينة في الجدال والمناظرة أثناء الدعوة.", "حرمة معاونة الكفار ومناصرتهم، لا سيما ضد المؤمنين.", "وجوب الثبات والصبر على الدعوة حتى نجاحها ببلوغها الناس واستجابتهم لها.", "تقرير التوحيد والبعث والنبوة المحمدية.", "فناء كل شيء إلا الله تعالى، إلا ما ورد الدليل بعدم فنائه."], "k": "«كل شيء هالك إلا وجهه»… ما الذي أعمله اليوم سيبقى لأنه أُريد به وجهه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 283;
insert into public.tdb_cards(topic, i, body) select 283, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٩ – ٨٢", "q": "فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِي زِينَتِهِۦۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا يَٰلَيۡتَ لَنَا مِثۡلَ مَآ أُوتِيَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٖ ﴿٧٩﴾ وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّـٰبِرُونَ ﴿٨٠﴾ فَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةٖ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِينَ ﴿٨١﴾ وَأَصۡبَحَ ٱلَّذِينَ تَمَنَّوۡاْ مَكَانَهُۥ بِٱلۡأَمۡسِ يَقُولُونَ وَيۡكَأَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُۖ لَوۡلَآ أَن مَّنَّ ٱللَّهُ عَلَيۡنَا لَخَسَفَ بِنَاۖ وَيۡكَأَنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ ﴿٨٢﴾", "w": [["في زينته", "لباس الأعياد والحفلات الرسمية."], ["يا ليت لنا مثل ما أوتي قارون", "تمنّوا أن لو أُعطوا من المال والزينة ما أُعطي."], ["لذو حظ عظيم", "لذو بخت ونصيب."], ["وقال الذين أوتوا العلم", "العلم الديني بمعرفة الله والدار الآخرة."], ["ويلكم", "حضر هلاككم بتمنّيكم زخرف الدنيا."], ["ولا يُلقّاها إلا الصابرون", "ولا يُوفَّق لقول هذه الكلمة إلا الصابرون على الإيمان والطاعة."], ["فخسفنا به وبداره الأرض", "أسخنا الأرض من تحته فساخت به وبداره ومن معه."], ["تمنّوا مكانه بالأمس", "مكانته من الإمارة والزينة والمال."], ["ويكأنّ الله يبسط الرزق", "أعجب عالماً أن الله يبسط الرزق لمن يشاء."], ["ويقدر", "يضيّق."]], "m": "خرج قارون على قومه في زينته الخاصة من الثياب والمراكب، فقال المفتونون بالدنيا من أهل الغفلة عن الآخرة، وما أكثرهم في كل زمان: يا ليت لنا مثل ما أوتي قارون، إنه لذو بخت عظيم. وقال الذين أوتوا العلم الديني: ويلكم، ثواب الله، وهو الجنة، خير من هذا الزخرف الفاني لمن آمن وعمل صالحاً، ولا يُلقّى هذه الكلمة إلا الصابرون من أهل الإيمان والتقوى لصفاء أرواحهم. فخسفنا به وبداره الأرض انتقاماً منه لكفره وبغيه وكبريائه، فما كان له من جماعة ينصرونه من دون الله، وما كان من المنتصرين لنفسه. وأصبح الذين تمنّوا مكانته بالأمس يقولون: عجباً، إن الله يبسط الرزق لمن يشاء من عباده ويضيّقه، فالبسط والقبض بيده، لولا أن منّ الله علينا لخسف بنا، عجباً إنه لا يفلح الكافرون.", "h": ["بيان أن الفتنة أسرع إلى قلوب الماديّين أبناء الدنيا، والعياذ بالله تعالى.", "بيان موقف أهل العلم الديني، وأنهم حكماء يأمرون بالمعروف وينهون عن المنكر.", "بيان أن البغي يُؤخذ به البغاة في الدنيا ويُعذّبون به في الآخرة.", "بيان أن وجود الإيمان خير من عدمه وإن قلّ، وأن ذا الإيمان أقرب إلى التوبة ممن لا إيمان له."], "k": "«يا ليت لنا مثل ما أوتي قارون»… أي «يا ليت» تتردّد في قلبي حين أرى ما عند الناس؟"}, {"lbl": "الآيتان ٨٣ – ٨٤", "q": "تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ ﴿٨٣﴾ مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَى ٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُواْ يَعۡمَلُونَ ﴿٨٤﴾", "w": [["تلك الدار الآخرة", "الجنة."], ["لا يريدون علوّاً في الأرض", "بغياً ولا استطالة على الناس."], ["ولا فساداً", "بعمل المعاصي."], ["والعاقبة", "المحمودة في الدنيا والآخرة."], ["للمتقين", "الذين يتّقون مساخط الله فلا يعتقدون ولا يقولون ولا يعملون ما لا يرضاه."], ["من جاء بالحسنة", "يوم القيامة، والحسنة أثر طاعة الله يُجزى به العبد."], ["فله خير منها", "تُضاعف له عشرة أضعاف."], ["ومن جاء بالسيئة", "والسيئة أثر معصية الله يُعاقب به العبد إن لم يعفُ الله عنه."]], "m": "تلك الدار الآخرة، الجنة، آخر دار يسكنها المتقون فلا يخرجون منها، نجعلها مأوى للذين لا يريدون استطالة على الناس ولا تكبّراً ولا بغياً، ولا فساداً بارتكاب المعاصي كالقتل والزنا والسرقة وشرب الخمر، والعاقبة المحمودة في الدارين للمتقين الذين يفعلون المأمورات ويجتنبون المنهيات. من جاء يوم القيامة بالطاعات فله جزاء مضاعف، الحسنة بعشر أمثالها وقد تُضاعف إلى أكثر، والمضاعفة للحسنة التي باشرها العبد، لا لحسنة أُخذت له من ظالمه في الدنيا، ولا لحسنة همّ بها ولم يعملها فإنها تُكتب له حسنة واحدة. ومن جاء بالسيئة فلا يُجزى إلا مثلها، لعدل الله ورأفته بعباده، إذ الدنيا دار العمل والآخرة دار الجزاء.", "h": ["حرمة التكبّر والاستطالة على الناس والعمل بالمعاصي، وأنه الفساد في الأرض.", "بيان فضل الله ورحمته وعدله بين عباده بمضاعفة الحسنات وعدم مضاعفة السيئات.", "العاقبة الحسنى، وهي الجنة، لأهل الإيمان والتقوى."], "k": "«للذين لا يريدون علوّاً في الأرض»… الشرط في الإرادة لا الفعل فقط؛ فهل في قلبي رغبة في العلوّ على أحد؟"}, {"lbl": "الآيات ٨٥ – ٨٨", "q": "إِنَّ ٱلَّذِي فَرَضَ عَلَيۡكَ ٱلۡقُرۡءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٖۚ قُل رَّبِّيٓ أَعۡلَمُ مَن جَآءَ بِٱلۡهُدَىٰ وَمَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٨٥﴾ وَمَا كُنتَ تَرۡجُوٓاْ أَن يُلۡقَىٰٓ إِلَيۡكَ ٱلۡكِتَٰبُ إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۖ فَلَا تَكُونَنَّ ظَهِيرٗا لِّلۡكَٰفِرِينَ ﴿٨٦﴾ وَلَا يَصُدُّنَّكَ عَنۡ ءَايَٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَيۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ﴿٨٧﴾ وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۘ لَآ إِلَٰهَ إِلَّا هُوَۚ كُلُّ شَيۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٨٨﴾", "w": [["إن الذي فرض عليك القرآن", "الله الذي أنزله عليك وفرض عليك قراءته والعمل بما فيه وتبليغه."], ["لرادّك إلى معاد", "لمرجعك إلى مكة فاتحاً، إذ معاد الرجل بلده."], ["وما كنت ترجو", "تأمل أن يُنزل عليك القرآن."], ["إلا رحمة من ربك", "لكن برحمة من الله وفضل أنزله عليك."], ["فلا تكوننّ ظهيراً", "من شكر هذه النعمة ألا تكون معيناً للكافرين."], ["ولا يصدّنّك", "لا يصرفنّك عن العمل بآيات الله."], ["ولا تدع مع الله إلهاً آخر", "لا تعبد معه غيره بدعاء ولا ذبح ولا نذر."], ["كل شيء هالك", "فانٍ."], ["إلا وجهه", "إلا الله سبحانه، فلا يهلك كما يهلك ما عداه."]], "m": "هذه خاتمة الدعوة إلى أصول الدين الثلاثة في هذه السورة: إن الذي أنزل عليك القرآن وفرض عليك تلاوته وتبليغه والعمل به لرادّك إلى مكة بعد خروجك منها واشتياقك إليها، وإلى الجنة بعد وفاتك. قل للمشركين الذين اتّهموك بالضلال: ربي أعلم بمن جاء بالهدى ومن هو في ضلال مبين. وما كنت تأمل قبل بعثتك أن يُنزل عليك القرآن، لكن رحمة ربك اقتضت إنزاله لتكون رسول الله للعالمين، فاشكره: فلا تكوننّ معيناً للكافرين، ولا يصرفنّك عن تلاوة آيات الله وإبلاغها والعمل بها بعد إذ أُنزلت إليك، وادع الناس إلى توحيد ربك، ولا تكوننّ من المشركين، ولا تعبد مع الله إلهاً آخر بدعاء ولا نذر ولا ذبح، لا إله إلا هو. كل شيء هالك إلا وجهه، فكل عمل لا يُراد به وجه الله باطل ذاهب بلا مثوبة، وكل شيء سوى الله فانٍ، له القضاء العادل، وإليه ترجعون للحساب والجزاء.", "h": ["معجزة القرآن في وقوع الغيب بعد الإخبار به، حيث عاد الرسول ﷺ إلى مكة فاتحاً.", "مشروعية الملاينة في الجدال والمناظرة أثناء الدعوة.", "حرمة معاونة الكفار ومناصرتهم، لا سيما ضد المؤمنين.", "وجوب الثبات والصبر على الدعوة حتى نجاحها ببلوغها الناس واستجابتهم لها.", "تقرير التوحيد والبعث والنبوة المحمدية.", "فناء كل شيء إلا الله تعالى، إلا ما ورد الدليل بعدم فنائه."], "k": "«كل شيء هالك إلا وجهه»… ما الذي أعمله اليوم سيبقى لأنه أُريد به وجهه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (284, 29, 1, 13, 'سورة العنكبوت ١ – ١٣', '«أحسب الناس أن يُتركوا أن يقولوا آمنا وهم لا يُفتنون»، و«ووصّينا الإنسان بوالديه حسناً»، و«فإذا أوذي في الله جعل فتنة الناس كعذاب الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 284) = $j$[{"lbl": "الآيات ١ – ٧", "q": "الٓمٓ ﴿١﴾ أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ ﴿٢﴾ وَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ ﴿٣﴾ أَمۡ حَسِبَ ٱلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسۡبِقُونَاۚ سَآءَ مَا يَحۡكُمُونَ ﴿٤﴾ مَن كَانَ يَرۡجُواْ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَأٓتٖۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٥﴾ وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفۡسِهِۦٓۚ إِنَّ ٱللَّهَ لَغَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ ﴿٦﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَنَجۡزِيَنَّهُمۡ أَحۡسَنَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ ﴿٧﴾", "w": [["الم", "تُكتب ألم وتُقرأ: ألف لام ميم."], ["وهم لا يُفتنون", "لا يُختبرون بما يتبيّن به حقيقة إيمانهم من التكاليف، ومنها الصبر على الأذى."], ["ولقد فتنّا الذين من قبلهم", "اختبرنا من قبلهم، إذ هي سنّة جارية في الناس."], ["فليعلمنّ الله الذين صدقوا", "في إيمانهم، ويعلم الكاذبين فيه بما يظهر منهم."], ["أن يسبقونا", "يفوتونا فلا ننتقم منهم."], ["ساء ما يحكمون", "بئس الحكم حسبانهم أنهم يفوتون الله."], ["من كان يرجو لقاء الله", "من كان يؤمن بلقاء الله وينتظره فليستعدّ له بالإيمان وصالح الأعمال."], ["ومن جاهد", "بذل الجهد في حرب الكفار أو النفس."], ["فإنما يجاهد لنفسه", "منفعة الجهاد من الأجر عائدة عليه."], ["ولنجزينّهم أحسن", "نجزيهم بأحسن عمل كانوا عملوه."]], "m": "الم، الله أعلم بمراده به، وهذا مذهب السلف: تفويض علمها إلى منزّلها. أظنّ الناس أن يُكتفى منهم بقولهم: آمنا، ولا يُختبرون بالتكاليف الشاقة كالهجرة والجهاد والصلاة والصيام والزكاة وترك الشهوات والصبر على الأذى؟ والآية وإن نزلت في مثل عمار وبلال وعياش فهي عامة، إذ العبرة بعموم اللفظ. ولقد فتنّا الذين من قبلهم، فهي سنّة ماضية، فليُظهرنّ الله الصادقين في إيمانهم بقيامهم بالتكاليف، وليُظهرنّ الكاذبين الذين ادّعوا الإيمان فلما ابتُلوا لم يقوموا بها. أم ظن الذين يعملون السيئات أن يفوتونا فلا نأخذهم؟ بئس ما يحكمون. من كان يرجو لقاء الله يوم القيامة فإن أجله آتٍ قطعاً، فليستعدّ له بالإيمان والعمل الصالح، فدعوى رجاء اللقاء بلا عمل صالح لا تصح، وهو السميع لأقوال عباده العليم بنياتهم. ومن جاهد فإنما منفعة جهاده لنفسه، إن الله لغني عن العالمين. والذين آمنوا وعملوا الصالحات لنكفّرنّ عنهم سيئاتهم فنسترها ولا نطالبهم بها، ولنجزينّهم بأحسن ما عملوا، يجزي بالحسنة أضعافها.", "h": ["بيان سنّة أن الإيمان يُصدَّق بالأعمال أو يُكذَّب.", "بيان إمكان التكليف بما يشق على النفس فعله أو تركه، ولكن ليس بما لا يُطاق.", "تحذير المغترّين من العقوبة وإن تأخرت زمناً ما، فإنها واقعة لا محالة.", "ثمرة الجهاد عائدة على المجاهد نفسه، فلذا لا ينبغي أن يمنّ بها على الله تعالى.", "تقرير عقيدة البعث والجزاء بذكر الوعد للذين آمنوا وعملوا الصالحات بتكفير السيئات والجزاء الأحسن."], "k": "«أحسب الناس أن يُتركوا أن يقولوا آمنا وهم لا يُفتنون»… الاختبار الذي أمرّ به الآن، هل أراه امتحاناً لصدقي؟"}, {"lbl": "الآيات ٨ – ١٣", "q": "وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حُسۡنٗاۖ وَإِن جَٰهَدَاكَ لِتُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَآۚ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٨﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَنُدۡخِلَنَّهُمۡ فِي ٱلصَّـٰلِحِينَ ﴿٩﴾ وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِيَ فِي ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ وَلَئِن جَآءَ نَصۡرٞ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمۡۚ أَوَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِمَا فِي صُدُورِ ٱلۡعَٰلَمِينَ ﴿١٠﴾ وَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَلَيَعۡلَمَنَّ ٱلۡمُنَٰفِقِينَ ﴿١١﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ ٱتَّبِعُواْ سَبِيلَنَا وَلۡنَحۡمِلۡ خَطَٰيَٰكُمۡ وَمَا هُم بِحَٰمِلِينَ مِنۡ خَطَٰيَٰهُم مِّن شَيۡءٍۖ إِنَّهُمۡ لَكَٰذِبُونَ ﴿١٢﴾ وَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡۖ وَلَيُسۡـَٔلُنَّ يَوۡمَ ٱلۡقِيَٰمَةِ عَمَّا كَانُواْ يَفۡتَرُونَ ﴿١٣﴾", "w": [["ووصّينا الإنسان", "عهدنا إليه بطريق الوحي."], ["بوالديه حسناً", "إيصاءً ذا حسن، وذلك ببرّهما وعدم عقوقهما."], ["وإن جاهداك", "بذلا الجهد في حملك على أن تشرك."], ["لندخلنّهم في الصالحين", "لندخلنّهم مدخلهم في الجنة."], ["فتنة الناس", "أذاهم له."], ["كعذاب الله", "في الخوف منه، فيطيعهم فينافق."], ["إنا كنا معكم", "في الإيمان، وإنما أُكرهنا."], ["اتّبعوا سبيلنا", "ديننا وما نحن عليه."], ["ولنحمل خطاياكم", "إن كان بعث كما يقول محمد فنحن نحملها عنكم."], ["وليحملنّ أثقالهم", "أوزارهم وذنوبهم."], ["وأثقالاً مع أثقالهم", "أوزار من أضلّوهم."]], "m": "نزلت في سعد بن أبي وقاص لما أسلم، فأقسمت أمه ألا تأكل ولا تشرب حتى يرجع عن دينه أو تموت، فمكثت يومين، فقال لها: يا أماه لو كانت لك مئة نفس فخرجت نفساً نفساً ما تركت ديني، فكُلي إن شئت. ووصّينا الإنسان بوالديه إيصاءً ذا حسن ببرّهما في المعروف وترك أذاهما، وإن جاهداك لتشرك بي فلا تطعهما، إليّ مرجعكم أولاداً ووالدين فأنبّئكم بما كنتم تعملون، فقدّموا طاعتي على طاعة الوالدين. والذين آمنوا وعملوا الصالحات الخالية من الشرك والرياء لندخلنّهم في مدخل الصالحين من الأنبياء والأولياء. ومن الناس من يقول: آمنا بالله، فإذا آذاه المشركون في الله جعل أذاهم كعذاب الله فوافقهم على الكفر، ولئن جاء نصر من ربك قالوا: إنا كنا معكم، أوليس الله بأعلم بما في صدور العالمين؟ وليُظهرنّ الله المؤمنين والمنافقين ليترتب الجزاء. وقال رؤساء قريش للمؤمنين: اتّبعوا ديننا، وإن كان بعث فنحن نحمل خطاياكم، وما هم بحاملين منها من شيء إنهم لكاذبون، وليحملنّ أوزارهم وأوزار من أضلّوهم، وليُسألنّ يوم القيامة عما كانوا يفترون.", "h": ["وجوب برّ الوالدين في المعروف، وعدم طاعتهما فيما هو منكر كالشرك والمعاصي.", "بشرى المؤمنين العاملين للصالحات بإدخالهم الجنة مع النبيين والصديقين.", "ذمّ النفاق وكفر المنافقين وإن ادّعوا الإيمان، فما هم بمؤمنين.", "بيان ما كان عليه غلاة الكفر في مكة من العتوّ والطغيان.", "تقرير مبدأ: من سنّ سنّة سيئة فعليه وزرها ووزر من عمل بها، كما في الحديث الصحيح."], "k": "«جعل فتنة الناس كعذاب الله»… هل أخاف كلام الناس أكثر مما أخاف الله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 284;
insert into public.tdb_cards(topic, i, body) select 284, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٧", "q": "الٓمٓ ﴿١﴾ أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ ﴿٢﴾ وَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ ﴿٣﴾ أَمۡ حَسِبَ ٱلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسۡبِقُونَاۚ سَآءَ مَا يَحۡكُمُونَ ﴿٤﴾ مَن كَانَ يَرۡجُواْ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَأٓتٖۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٥﴾ وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفۡسِهِۦٓۚ إِنَّ ٱللَّهَ لَغَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ ﴿٦﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَنَجۡزِيَنَّهُمۡ أَحۡسَنَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ ﴿٧﴾", "w": [["الم", "تُكتب ألم وتُقرأ: ألف لام ميم."], ["وهم لا يُفتنون", "لا يُختبرون بما يتبيّن به حقيقة إيمانهم من التكاليف، ومنها الصبر على الأذى."], ["ولقد فتنّا الذين من قبلهم", "اختبرنا من قبلهم، إذ هي سنّة جارية في الناس."], ["فليعلمنّ الله الذين صدقوا", "في إيمانهم، ويعلم الكاذبين فيه بما يظهر منهم."], ["أن يسبقونا", "يفوتونا فلا ننتقم منهم."], ["ساء ما يحكمون", "بئس الحكم حسبانهم أنهم يفوتون الله."], ["من كان يرجو لقاء الله", "من كان يؤمن بلقاء الله وينتظره فليستعدّ له بالإيمان وصالح الأعمال."], ["ومن جاهد", "بذل الجهد في حرب الكفار أو النفس."], ["فإنما يجاهد لنفسه", "منفعة الجهاد من الأجر عائدة عليه."], ["ولنجزينّهم أحسن", "نجزيهم بأحسن عمل كانوا عملوه."]], "m": "الم، الله أعلم بمراده به، وهذا مذهب السلف: تفويض علمها إلى منزّلها. أظنّ الناس أن يُكتفى منهم بقولهم: آمنا، ولا يُختبرون بالتكاليف الشاقة كالهجرة والجهاد والصلاة والصيام والزكاة وترك الشهوات والصبر على الأذى؟ والآية وإن نزلت في مثل عمار وبلال وعياش فهي عامة، إذ العبرة بعموم اللفظ. ولقد فتنّا الذين من قبلهم، فهي سنّة ماضية، فليُظهرنّ الله الصادقين في إيمانهم بقيامهم بالتكاليف، وليُظهرنّ الكاذبين الذين ادّعوا الإيمان فلما ابتُلوا لم يقوموا بها. أم ظن الذين يعملون السيئات أن يفوتونا فلا نأخذهم؟ بئس ما يحكمون. من كان يرجو لقاء الله يوم القيامة فإن أجله آتٍ قطعاً، فليستعدّ له بالإيمان والعمل الصالح، فدعوى رجاء اللقاء بلا عمل صالح لا تصح، وهو السميع لأقوال عباده العليم بنياتهم. ومن جاهد فإنما منفعة جهاده لنفسه، إن الله لغني عن العالمين. والذين آمنوا وعملوا الصالحات لنكفّرنّ عنهم سيئاتهم فنسترها ولا نطالبهم بها، ولنجزينّهم بأحسن ما عملوا، يجزي بالحسنة أضعافها.", "h": ["بيان سنّة أن الإيمان يُصدَّق بالأعمال أو يُكذَّب.", "بيان إمكان التكليف بما يشق على النفس فعله أو تركه، ولكن ليس بما لا يُطاق.", "تحذير المغترّين من العقوبة وإن تأخرت زمناً ما، فإنها واقعة لا محالة.", "ثمرة الجهاد عائدة على المجاهد نفسه، فلذا لا ينبغي أن يمنّ بها على الله تعالى.", "تقرير عقيدة البعث والجزاء بذكر الوعد للذين آمنوا وعملوا الصالحات بتكفير السيئات والجزاء الأحسن."], "k": "«أحسب الناس أن يُتركوا أن يقولوا آمنا وهم لا يُفتنون»… الاختبار الذي أمرّ به الآن، هل أراه امتحاناً لصدقي؟"}, {"lbl": "الآيات ٨ – ١٣", "q": "وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حُسۡنٗاۖ وَإِن جَٰهَدَاكَ لِتُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَآۚ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٨﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَنُدۡخِلَنَّهُمۡ فِي ٱلصَّـٰلِحِينَ ﴿٩﴾ وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِيَ فِي ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ وَلَئِن جَآءَ نَصۡرٞ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمۡۚ أَوَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِمَا فِي صُدُورِ ٱلۡعَٰلَمِينَ ﴿١٠﴾ وَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَلَيَعۡلَمَنَّ ٱلۡمُنَٰفِقِينَ ﴿١١﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ ٱتَّبِعُواْ سَبِيلَنَا وَلۡنَحۡمِلۡ خَطَٰيَٰكُمۡ وَمَا هُم بِحَٰمِلِينَ مِنۡ خَطَٰيَٰهُم مِّن شَيۡءٍۖ إِنَّهُمۡ لَكَٰذِبُونَ ﴿١٢﴾ وَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡۖ وَلَيُسۡـَٔلُنَّ يَوۡمَ ٱلۡقِيَٰمَةِ عَمَّا كَانُواْ يَفۡتَرُونَ ﴿١٣﴾", "w": [["ووصّينا الإنسان", "عهدنا إليه بطريق الوحي."], ["بوالديه حسناً", "إيصاءً ذا حسن، وذلك ببرّهما وعدم عقوقهما."], ["وإن جاهداك", "بذلا الجهد في حملك على أن تشرك."], ["لندخلنّهم في الصالحين", "لندخلنّهم مدخلهم في الجنة."], ["فتنة الناس", "أذاهم له."], ["كعذاب الله", "في الخوف منه، فيطيعهم فينافق."], ["إنا كنا معكم", "في الإيمان، وإنما أُكرهنا."], ["اتّبعوا سبيلنا", "ديننا وما نحن عليه."], ["ولنحمل خطاياكم", "إن كان بعث كما يقول محمد فنحن نحملها عنكم."], ["وليحملنّ أثقالهم", "أوزارهم وذنوبهم."], ["وأثقالاً مع أثقالهم", "أوزار من أضلّوهم."]], "m": "نزلت في سعد بن أبي وقاص لما أسلم، فأقسمت أمه ألا تأكل ولا تشرب حتى يرجع عن دينه أو تموت، فمكثت يومين، فقال لها: يا أماه لو كانت لك مئة نفس فخرجت نفساً نفساً ما تركت ديني، فكُلي إن شئت. ووصّينا الإنسان بوالديه إيصاءً ذا حسن ببرّهما في المعروف وترك أذاهما، وإن جاهداك لتشرك بي فلا تطعهما، إليّ مرجعكم أولاداً ووالدين فأنبّئكم بما كنتم تعملون، فقدّموا طاعتي على طاعة الوالدين. والذين آمنوا وعملوا الصالحات الخالية من الشرك والرياء لندخلنّهم في مدخل الصالحين من الأنبياء والأولياء. ومن الناس من يقول: آمنا بالله، فإذا آذاه المشركون في الله جعل أذاهم كعذاب الله فوافقهم على الكفر، ولئن جاء نصر من ربك قالوا: إنا كنا معكم، أوليس الله بأعلم بما في صدور العالمين؟ وليُظهرنّ الله المؤمنين والمنافقين ليترتب الجزاء. وقال رؤساء قريش للمؤمنين: اتّبعوا ديننا، وإن كان بعث فنحن نحمل خطاياكم، وما هم بحاملين منها من شيء إنهم لكاذبون، وليحملنّ أوزارهم وأوزار من أضلّوهم، وليُسألنّ يوم القيامة عما كانوا يفترون.", "h": ["وجوب برّ الوالدين في المعروف، وعدم طاعتهما فيما هو منكر كالشرك والمعاصي.", "بشرى المؤمنين العاملين للصالحات بإدخالهم الجنة مع النبيين والصديقين.", "ذمّ النفاق وكفر المنافقين وإن ادّعوا الإيمان، فما هم بمؤمنين.", "بيان ما كان عليه غلاة الكفر في مكة من العتوّ والطغيان.", "تقرير مبدأ: من سنّ سنّة سيئة فعليه وزرها ووزر من عمل بها، كما في الحديث الصحيح."], "k": "«جعل فتنة الناس كعذاب الله»… هل أخاف كلام الناس أكثر مما أخاف الله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (285, 29, 14, 23, 'سورة العنكبوت ١٤ – ٢٣', '«فلبث فيهم ألف سنة إلا خمسين عاماً»، و«فابتغوا عند الله الرزق واعبدوه واشكروا له»، و«قل سيروا في الأرض فانظروا كيف بدأ الخلق»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 285) = $j$[{"lbl": "الآيتان ١٤ – ١٥", "q": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ ﴿١٤﴾ فَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ ﴿١٥﴾", "w": [["ولقد أرسلنا نوحاً إلى قومه", "وهو من ذرية آدم ﵇، وقومه يومئذ البشرية جمعاء."], ["فلبث فيهم ألف سنة إلا خمسين عاماً", "مكث فيهم يدعوهم إلى الله تسعمئة وخمسين سنة."], ["فأخذهم الطوفان", "الماء الكثير الذي طاف بهم وعلاهم."], ["وهم ظالمون", "مشركون."], ["وجعلناها آية للعالمين", "عبرة للناس يعتبرون بها فلا يشركون."]], "m": "لما ذكر ما يلاقيه رسوله والمؤمنون من مشركي قريش ذكر نوحاً وإبراهيم، وكلاهما لاقى ما لم يلقه محمد ﷺ وأصحابه، تسلية لهم: ولقد أرسلنا نوحاً إلى قومه، يدعوهم إلى توحيد الله وترك أصنامهم الخمسة: ودّ وسواع ويغوث ويعوق ونسر، وكانوا رجالاً صالحين فلما ماتوا بنوا على قبورهم ووضعوا لهم تماثيل بحجة أنها تذكّرهم بالله، ثم زيّن لهم الشيطان عبادتهم فعبدوهم. فلبث فيهم ألف سنة إلا خمسين عاماً يدعوهم فلم يستجيبوا، فدعا ربه أني مغلوب فانتصر، فأخذهم الطوفان وهم ظالمون لأنفسهم بالشرك، فأنجيناه وأصحاب السفينة، وكانوا قرابة الثمانين، ومن أبنائه عُمرت الأرض، وجعلنا حادثة الطوفان والسفينة ومكثه تلك المدة الطويلة مع قلة المستجيب عبرة للناس، إذا اعتبروا، وقليل من يعتبر.", "h": ["بيان سنّة الله تعالى في إرسال الرسل لهداية الخلق.", "قلة من استجاب لنوح مع المدة الطويلة، فيكون هذا تسلية لرسول الله ﷺ والدعاة.", "بيان إهلاك الله تعالى الظالمين وإنجائه المؤمنين، وهي عبرة للمعتبرين."], "k": "«ألف سنة إلا خمسين عاماً»… ونحن نملّ بعد أيام؛ فكم صبري على دعوة من أحب؟"}, {"lbl": "الآيات ١٦ – ١٨", "q": "وَإِبۡرَٰهِيمَ إِذۡ قَالَ لِقَوۡمِهِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُۖ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿١٦﴾ إِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَٰنٗا وَتَخۡلُقُونَ إِفۡكًاۚ إِنَّ ٱلَّذِينَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمۡلِكُونَ لَكُمۡ رِزۡقٗا فَٱبۡتَغُواْ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُواْ لَهُۥٓۖ إِلَيۡهِ تُرۡجَعُونَ ﴿١٧﴾ وَإِن تُكَذِّبُواْ فَقَدۡ كَذَّبَ أُمَمٞ مِّن قَبۡلِكُمۡۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿١٨﴾", "w": [["وإبراهيم", "واذكر إبراهيم."], ["اعبدوا الله واتقوه", "آمنوا به ووحّدوه في عبادته، واتّقوا أن تشركوا به وتعصوه."], ["أوثاناً", "أصناماً وأحجاراً وصوراً وتماثيل."], ["وتخلقون إفكاً", "تختلقون الكذب فتقولون في الأصنام: آلهة."], ["فابتغوا عند الله الرزق", "اطلبوا الرزق من الله، لا من الأصنام المنحوتة بأيدي الرجال."], ["واعبدوه واشكروا له", "بالإيمان به وتوحيده، واشكروه بطاعته."], ["وإن تكذّبوا", "يا أهل مكة، فقد كذّبت أمم من قبلكم."], ["وما على الرسول إلا البلاغ المبين", "وقد بلّغ وبيّن فبرئت ذمته."]], "m": "هذا القصص معطوف على قصص نوح، تسلية للرسول ﷺ وتذكيراً لقريش بمصير المكذّبين: واذكر إبراهيم إذ قال لقومه البابليين ومن بينهم أبوه آزر: اعبدوا الله بتوحيده واتّقوه بترك الشرك والعصيان، ذلكم خير لكم إن كنتم تعلمون، إنما تعبدون من دون الله أصناماً لا تنفع ولا تضر، وتختلقون الكذب حين تقولون إنها آلهة، إن الذين تعبدون من دون الله لا يملكون لكم رزقاً، فما الحاجة الداعية إلى عبادتها لولا الغفلة والجهل؟ فاطلبوا الرزق عند الله فإنه مالكه، واعبدوه واشكروا له، إليه ترجعون لا إلى غيره، فتعرّفوا إليه. ثم اعترض بين قصص إبراهيم خطاب لأهل مكة: وإن تكذّبوا رسولنا فقد كذّبت أمم من قبلكم كقوم نوح وعاد وفرعون، وما على الرسول إلا البلاغ المبين، وقد بلّغكم، فإما أن تتّعظوا فتؤمنوا، وإما أن يحلّ بكم ما حلّ بأمثالكم.", "h": ["وجوب عبادة الله وتقواه طلباً للنجاة من الخسران في الدارين.", "بطلان عبادة غير الله، ووجوب عبادة الله عن طريق الأدلة العقلية.", "ما عبد الناس الأوثان إلا من جهلهم وفقرهم، فلذا يجب أن يعلموا أن الله هو الذي يسدّ فقرهم ويرزقهم، ومن عداه لا يملك ذلك.", "وجوب شكر الله تعالى بحمده والثناء عليه وبطاعته، وصرف النعم فيما من أجله أنعم بها.", "تسلية الرسول ﷺ وتأنيب المشركين من أهل مكة."], "k": "«فابتغوا عند الله الرزق»… أين أطلب رزقي أولاً حين يضيق: عند الله أم عند الأسباب؟"}, {"lbl": "الآيات ١٩ – ٢٣", "q": "أَوَلَمۡ يَرَوۡاْ كَيۡفَ يُبۡدِئُ ٱللَّهُ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥٓۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿١٩﴾ قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشۡأَةَ ٱلۡأٓخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٢٠﴾ يُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ ﴿٢١﴾ وَمَآ أَنتُم بِمُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ ﴿٢٢﴾ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُوْلَـٰٓئِكَ يَئِسُواْ مِن رَّحۡمَتِي وَأُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٢٣﴾", "w": [["أوَلم يروا", "ينظروا بأبصارهم فيعلموا بقلوبهم."], ["كيف يُبدئ الله الخلق", "كيف يخلق المخلوق ابتداءً."], ["ثم يعيده", "بعد بدئه وإفنائه، والإعادة أهون من البدء."], ["على الله يسير", "سهل لا صعوبة فيه."], ["ينشئ النشأة الآخرة", "يُحيي الناس بعد موتهم، وهو البعث."], ["وإليه تُقلبون", "ترجعون إليه لا إلى غيره."], ["وما أنتم بمعجزين", "بغالبين ولا فائتين بالهروب."], ["يئسوا من رحمتي", "من دخول الجنة، لأنهم كذّبوا بالقرآن والبعث الآخر."]], "m": "ما زال السياق في تقرير أصول الدين، وهنا تقرير البعث والجزاء: أوَلم ينظر المنكرون للبعث كيف يبدئ الله خلق الإنسان ثم يعيده متى شاء؟ إن ذلك على الله سهل لا يتعذّر عليه. قل لهم: سيروا في الأرض شرقاً وغرباً فانظروا كيف بدأ الخلق من أرض وسماء وأنهار وأشجار وحيوان وإنسان، كلها كانت عدماً فأنشأها الله، ثم الله ينشئ النشأة الآخرة فيعيد حياة الإنسان ليحاسبه على كسبه، إن الله على كل شيء قدير. يعذّب من يشاء من أهل الكفر الذين لم يزكّوا أنفسهم، ويرحم من يشاء من أهل الإيمان والتقوى، وإليه ترجعون. وما أنتم بفائتين في الأرض ولا في السماء، وما لكم من دون الله من ولي يتولاكم ولا نصير ينصركم. والذين كفروا بآيات الله ولقائه أولئك يئسوا من رحمتي، إذ تكذيبهم بالقرآن مانع لهم من الإيمان، وتكذيبهم بالبعث مانع لهم من ترك الشرك، وأولئك لهم عذاب أليم.", "h": ["وجوب استعمال العقل للاستدلال على الغائب بالحاضر، وعلى المعدوم بالموجود.", "تقرير عقيدة البعث والجزاء، وذكر أدلتها التفصيلية.", "تقرير عجز الإنسان التام، وأنه لا مهرب له من الله ربه ومالكه، وهي حال تستدعي الفرار إلى الله اليوم بالإيمان والتقوى.", "إنذار المكذّبين بأنهم إن ماتوا على التكذيب بالبعث لا يدخلون الجنة بحال، وسيُعذّبون في نار جهنم."], "k": "«قل سيروا في الأرض فانظروا كيف بدأ الخلق»… كل ما حولي كان عدماً؛ فهل يصعب على خالقه أن يعيدني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 285;
insert into public.tdb_cards(topic, i, body) select 285, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٤ – ١٥", "q": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ ﴿١٤﴾ فَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ ﴿١٥﴾", "w": [["ولقد أرسلنا نوحاً إلى قومه", "وهو من ذرية آدم ﵇، وقومه يومئذ البشرية جمعاء."], ["فلبث فيهم ألف سنة إلا خمسين عاماً", "مكث فيهم يدعوهم إلى الله تسعمئة وخمسين سنة."], ["فأخذهم الطوفان", "الماء الكثير الذي طاف بهم وعلاهم."], ["وهم ظالمون", "مشركون."], ["وجعلناها آية للعالمين", "عبرة للناس يعتبرون بها فلا يشركون."]], "m": "لما ذكر ما يلاقيه رسوله والمؤمنون من مشركي قريش ذكر نوحاً وإبراهيم، وكلاهما لاقى ما لم يلقه محمد ﷺ وأصحابه، تسلية لهم: ولقد أرسلنا نوحاً إلى قومه، يدعوهم إلى توحيد الله وترك أصنامهم الخمسة: ودّ وسواع ويغوث ويعوق ونسر، وكانوا رجالاً صالحين فلما ماتوا بنوا على قبورهم ووضعوا لهم تماثيل بحجة أنها تذكّرهم بالله، ثم زيّن لهم الشيطان عبادتهم فعبدوهم. فلبث فيهم ألف سنة إلا خمسين عاماً يدعوهم فلم يستجيبوا، فدعا ربه أني مغلوب فانتصر، فأخذهم الطوفان وهم ظالمون لأنفسهم بالشرك، فأنجيناه وأصحاب السفينة، وكانوا قرابة الثمانين، ومن أبنائه عُمرت الأرض، وجعلنا حادثة الطوفان والسفينة ومكثه تلك المدة الطويلة مع قلة المستجيب عبرة للناس، إذا اعتبروا، وقليل من يعتبر.", "h": ["بيان سنّة الله تعالى في إرسال الرسل لهداية الخلق.", "قلة من استجاب لنوح مع المدة الطويلة، فيكون هذا تسلية لرسول الله ﷺ والدعاة.", "بيان إهلاك الله تعالى الظالمين وإنجائه المؤمنين، وهي عبرة للمعتبرين."], "k": "«ألف سنة إلا خمسين عاماً»… ونحن نملّ بعد أيام؛ فكم صبري على دعوة من أحب؟"}, {"lbl": "الآيات ١٦ – ١٨", "q": "وَإِبۡرَٰهِيمَ إِذۡ قَالَ لِقَوۡمِهِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُۖ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿١٦﴾ إِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَٰنٗا وَتَخۡلُقُونَ إِفۡكًاۚ إِنَّ ٱلَّذِينَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمۡلِكُونَ لَكُمۡ رِزۡقٗا فَٱبۡتَغُواْ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُواْ لَهُۥٓۖ إِلَيۡهِ تُرۡجَعُونَ ﴿١٧﴾ وَإِن تُكَذِّبُواْ فَقَدۡ كَذَّبَ أُمَمٞ مِّن قَبۡلِكُمۡۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿١٨﴾", "w": [["وإبراهيم", "واذكر إبراهيم."], ["اعبدوا الله واتقوه", "آمنوا به ووحّدوه في عبادته، واتّقوا أن تشركوا به وتعصوه."], ["أوثاناً", "أصناماً وأحجاراً وصوراً وتماثيل."], ["وتخلقون إفكاً", "تختلقون الكذب فتقولون في الأصنام: آلهة."], ["فابتغوا عند الله الرزق", "اطلبوا الرزق من الله، لا من الأصنام المنحوتة بأيدي الرجال."], ["واعبدوه واشكروا له", "بالإيمان به وتوحيده، واشكروه بطاعته."], ["وإن تكذّبوا", "يا أهل مكة، فقد كذّبت أمم من قبلكم."], ["وما على الرسول إلا البلاغ المبين", "وقد بلّغ وبيّن فبرئت ذمته."]], "m": "هذا القصص معطوف على قصص نوح، تسلية للرسول ﷺ وتذكيراً لقريش بمصير المكذّبين: واذكر إبراهيم إذ قال لقومه البابليين ومن بينهم أبوه آزر: اعبدوا الله بتوحيده واتّقوه بترك الشرك والعصيان، ذلكم خير لكم إن كنتم تعلمون، إنما تعبدون من دون الله أصناماً لا تنفع ولا تضر، وتختلقون الكذب حين تقولون إنها آلهة، إن الذين تعبدون من دون الله لا يملكون لكم رزقاً، فما الحاجة الداعية إلى عبادتها لولا الغفلة والجهل؟ فاطلبوا الرزق عند الله فإنه مالكه، واعبدوه واشكروا له، إليه ترجعون لا إلى غيره، فتعرّفوا إليه. ثم اعترض بين قصص إبراهيم خطاب لأهل مكة: وإن تكذّبوا رسولنا فقد كذّبت أمم من قبلكم كقوم نوح وعاد وفرعون، وما على الرسول إلا البلاغ المبين، وقد بلّغكم، فإما أن تتّعظوا فتؤمنوا، وإما أن يحلّ بكم ما حلّ بأمثالكم.", "h": ["وجوب عبادة الله وتقواه طلباً للنجاة من الخسران في الدارين.", "بطلان عبادة غير الله، ووجوب عبادة الله عن طريق الأدلة العقلية.", "ما عبد الناس الأوثان إلا من جهلهم وفقرهم، فلذا يجب أن يعلموا أن الله هو الذي يسدّ فقرهم ويرزقهم، ومن عداه لا يملك ذلك.", "وجوب شكر الله تعالى بحمده والثناء عليه وبطاعته، وصرف النعم فيما من أجله أنعم بها.", "تسلية الرسول ﷺ وتأنيب المشركين من أهل مكة."], "k": "«فابتغوا عند الله الرزق»… أين أطلب رزقي أولاً حين يضيق: عند الله أم عند الأسباب؟"}, {"lbl": "الآيات ١٩ – ٢٣", "q": "أَوَلَمۡ يَرَوۡاْ كَيۡفَ يُبۡدِئُ ٱللَّهُ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥٓۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿١٩﴾ قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشۡأَةَ ٱلۡأٓخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٢٠﴾ يُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ ﴿٢١﴾ وَمَآ أَنتُم بِمُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ ﴿٢٢﴾ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُوْلَـٰٓئِكَ يَئِسُواْ مِن رَّحۡمَتِي وَأُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٢٣﴾", "w": [["أوَلم يروا", "ينظروا بأبصارهم فيعلموا بقلوبهم."], ["كيف يُبدئ الله الخلق", "كيف يخلق المخلوق ابتداءً."], ["ثم يعيده", "بعد بدئه وإفنائه، والإعادة أهون من البدء."], ["على الله يسير", "سهل لا صعوبة فيه."], ["ينشئ النشأة الآخرة", "يُحيي الناس بعد موتهم، وهو البعث."], ["وإليه تُقلبون", "ترجعون إليه لا إلى غيره."], ["وما أنتم بمعجزين", "بغالبين ولا فائتين بالهروب."], ["يئسوا من رحمتي", "من دخول الجنة، لأنهم كذّبوا بالقرآن والبعث الآخر."]], "m": "ما زال السياق في تقرير أصول الدين، وهنا تقرير البعث والجزاء: أوَلم ينظر المنكرون للبعث كيف يبدئ الله خلق الإنسان ثم يعيده متى شاء؟ إن ذلك على الله سهل لا يتعذّر عليه. قل لهم: سيروا في الأرض شرقاً وغرباً فانظروا كيف بدأ الخلق من أرض وسماء وأنهار وأشجار وحيوان وإنسان، كلها كانت عدماً فأنشأها الله، ثم الله ينشئ النشأة الآخرة فيعيد حياة الإنسان ليحاسبه على كسبه، إن الله على كل شيء قدير. يعذّب من يشاء من أهل الكفر الذين لم يزكّوا أنفسهم، ويرحم من يشاء من أهل الإيمان والتقوى، وإليه ترجعون. وما أنتم بفائتين في الأرض ولا في السماء، وما لكم من دون الله من ولي يتولاكم ولا نصير ينصركم. والذين كفروا بآيات الله ولقائه أولئك يئسوا من رحمتي، إذ تكذيبهم بالقرآن مانع لهم من الإيمان، وتكذيبهم بالبعث مانع لهم من ترك الشرك، وأولئك لهم عذاب أليم.", "h": ["وجوب استعمال العقل للاستدلال على الغائب بالحاضر، وعلى المعدوم بالموجود.", "تقرير عقيدة البعث والجزاء، وذكر أدلتها التفصيلية.", "تقرير عجز الإنسان التام، وأنه لا مهرب له من الله ربه ومالكه، وهي حال تستدعي الفرار إلى الله اليوم بالإيمان والتقوى.", "إنذار المكذّبين بأنهم إن ماتوا على التكذيب بالبعث لا يدخلون الجنة بحال، وسيُعذّبون في نار جهنم."], "k": "«قل سيروا في الأرض فانظروا كيف بدأ الخلق»… كل ما حولي كان عدماً؛ فهل يصعب على خالقه أن يعيدني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (286, 29, 24, 35, 'سورة العنكبوت ٢٤ – ٣٥', '«قالوا اقتلوه أو حرّقوه فأنجاه الله من النار»، و«إني مهاجر إلى ربي»، ولوط ﵇: «ربّ انصرني على القوم المفسدين»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 286) = $j$[{"lbl": "الآيتان ٢٤ – ٢٥", "q": "فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٢٤﴾ وَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنٗا مَّوَدَّةَ بَيۡنِكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِينَ ﴿٢٥﴾", "w": [["فما كان جواب قومه", "قوم إبراهيم ﵇."], ["إلا أن قالوا اقتلوه أو حرّقوه", "إلا قولهم ذلك."], ["إن في ذلك لآيات", "في كون النار لم تحرق الخليل وخرج منها سالماً."], ["لقوم يؤمنون", "لأنهم المنتفعون بالآيات لحياة قلوبهم."], ["أوثاناً مودّة بينكم", "اتخذتم الأوثان آلهة تتوادّون من أجل عبادتها."], ["في الحياة الدنيا", "هذا التوادّ في الدنيا فقط."], ["يكفر بعضكم ببعض", "يكفر المتبوعون بأتباعهم ويتبرّؤون منهم."], ["ويلعن بعضكم بعضاً", "يلعن الأتباع القادة الذين اتّبعوهم في الباطل."]], "m": "لما أفحمهم إبراهيم بالحجة لجأوا، كعادة الطغاة، إلى القوة، فما كان جوابهم إلا أن قالوا: اقتلوه أو حرّقوه، فأوقدوا النار وألقوه فيها، فقال الله: «يا نار كوني برداً وسلاماً على إبراهيم»، فخرج سالماً لم تحرق النار إلا الحبل الذي شُدّ به، فأنجاه الله من النار، إن في ذلك لدلائل على قدرة الله ورحمته، لا ينتفع بها إلا المؤمنون لأنهم أحياء، والإيمان في القلب كالروح في البدن. وقال لهم: إنما اتخذتم من دون الله أوثاناً لأجل التوادّ والتحابّ والاجتماع عليها، تقيمون لها الأعياد فتأكلون وتشربون، لا أنكم تعتقدون حقاً أنها آلهة، ثم يوم القيامة ينعكس الأمر، فيكفر المتبوعون بأتباعهم، ويلعن بعضكم بعضاً عند معاينة العذاب، ومأواكم جميعاً النار، وما لكم من ناصرين.", "h": ["تقرير أن الظلمة سنّتهم أنهم إذا أعيتهم الحجج يلجأون إلى استعمال القوة.", "في عدم إحراق النار دليل على أن الله تعالى قادر على إبطال السنن إذا شاء، ومن هنا تكون الكرامات والمعجزات، إذ هي خوارق للعادات."], "k": "«مودّة بينكم في الحياة الدنيا»… أي صحبة في حياتي تقوم على ما يرضي الله، وأيها ستنقلب عداوة يومها؟"}, {"lbl": "الآيتان ٢٦ – ٢٧", "q": "۞فَـَٔامَنَ لَهُۥ لُوطٞۘ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢٦﴾ وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ وَءَاتَيۡنَٰهُ أَجۡرَهُۥ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ ﴿٢٧﴾", "w": [["فآمن له لوط", "آمن بإبراهيم لوط ابن أخيه هاران."], ["إني مهاجر إلى ربي", "إلى حيث أعبد ربي فلا أُفتن في ديني."], ["ووهبنا له إسحاق ويعقوب", "أكرمناه في دار هجرته بإسحاق الابن ويعقوب الحفيد."], ["في ذريته النبوة والكتاب", "فكل الأنبياء بعده من ذريته، وكل الكتب التي أُنزلت بعده فيهم."], ["وآتيناه أجره في الدنيا", "بالرزق الطيب والثناء الحسن من أهل الأديان الإلهية."], ["وإنه في الآخرة لمن الصالحين", "أحدهم، فيُكرم كما يُكرمون بالدرجات العلا."]], "m": "هذا آخر قصص إبراهيم في هذا السياق: بعد الجهاد الطويل في الدعوة لم يؤمن له إلا لوط ابن أخيه، وقال إبراهيم: إني مهاجر إلى ربي، إنه هو العزيز الحكيم، فترك بلاد قومه في العراق وارتحل إلى الشام، ومن دلائل العزة أن أنجاه من الطغاة، ومن مظاهر الحكمة أن نقله إلى أرض كلها خير. فأكرمه الله جزاء هجرته: ووهبنا له إسحاق ويعقوب، وجعلنا في ذريته النبوة والكتاب، فالتوراة على موسى والزبور على داود والإنجيل على عيسى، وهم من ذريته، والقرآن على محمد ﷺ وهو من ذرية إسماعيل. وآتيناه أجره في الدنيا، فرزقه أطيب الأرزاق، والثناء الحسن من أهل الأديان كلها، وإنه في الآخرة لمن الصالحين ذوي الدرجات العلا.", "h": ["بيان حصيلة دعوة إبراهيم ﵇ سنين طويلة، وأنها كانت إيمان واحد بها، وهو لوط ﵇، وفي هذا تسلية للرسول ﷺ.", "بيان إكرام الله تعالى لمن يهاجر إليه ويترك أهله وداره.", "بيان ما أكرم الله تعالى به إبراهيم من خير الدنيا والآخرة جزاء صبره على الدعوة."], "k": "«إني مهاجر إلى ربي»… ما الذي أحتاج أن أهجره اليوم لأكون أقرب إليه؟"}, {"lbl": "الآيات ٢٨ – ٣٠", "q": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ﴿٢٨﴾ أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ ٱلسَّبِيلَ وَتَأۡتُونَ فِي نَادِيكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٢٩﴾ قَالَ رَبِّ ٱنصُرۡنِي عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِينَ ﴿٣٠﴾", "w": [["ولوطاً إذ قال لقومه", "واذكر لوطاً إذ قال لقومه أهل سدوم."], ["لتأتون الفاحشة", "الخصلة القبيحة، وهي إتيان الذكران."], ["ما سبقكم بها من أحد", "لم تعرف البشرية قبلهم هذه الفعلة."], ["وتقطعون السبيل", "باعتدائكم على المارّة، فامتنع الناس من المرور."], ["وتأتون في ناديكم المنكر", "في مجالس أحاديثكم تأتون المنكر من الأقوال والأفعال القبيحة."], ["فما كان جواب قومه", "إلا قولهم: ائتنا بعذاب الله إن كنت من الصادقين."]], "m": "هذا بداية قصص لوط ﵇ مع أهل سدوم وعمورية، تقريراً للنبوة المحمدية وتسلية للرسول: واذكر لوطاً إذ قال لقومه: إنكم لتأتون الفاحشة ما سبقكم بها أحد من العالمين، أئنّكم لتأتون الرجال، وتقطعون السبيل بالاعتداء على المارّة بالفاحشة قسراً وسلب أموالهم، فامتنع الناس من المرور، كما قطعتم بإتيان الذكران سبيل الولادة، وتأتون في مجالس اجتماعكم المنكر بارتكاب الفاحشة وأنواع العبث والسوء؟ فما كان جوابهم بعد أن وبّخهم إلا المطالبة بعذاب الله: ائتنا بعذاب الله إن كنت من الصادقين، وهذه طريقة الغلاة المفسدين إذا أعيتهم الحجج. فلجأ لوط إلى ربه: رب انصرني على القوم المفسدين، فاستجاب له.", "h": ["تقرير النبوة المحمدية بذكر قصص لا يتم إلا عن طريق الوحي.", "تسلية الرسول ﷺ من أجل ما يعاني من المشركين من كفر وعناد ومطالبة بالعذاب.", "قبح الفاحشة وحرمتها، وأسوؤها فاحشة اللواط.", "وجوب إقامة الحد على اللوطي الفاعل والمفعول، لأن الله تعالى سمّاها فاحشة كما سمّى الزنى، وقد صرّحت السنّة بذلك.", "التحذير من العبث والباطل قولاً أو عملاً، وخاصة في الأندية والمجتمعات."], "k": "«وتأتون في ناديكم المنكر»… مجالسي التي أجلسها، ماذا يُقال ويُفعل فيها؟"}, {"lbl": "الآيات ٣١ – ٣٥", "q": "وَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ ﴿٣١﴾ قَالَ إِنَّ فِيهَا لُوطٗاۚ قَالُواْ نَحۡنُ أَعۡلَمُ بِمَن فِيهَاۖ لَنُنَجِّيَنَّهُۥ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ ﴿٣٢﴾ وَلَمَّآ أَن جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗاۖ وَقَالُواْ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا ٱمۡرَأَتَكَ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ ﴿٣٣﴾ إِنَّا مُنزِلُونَ عَلَىٰٓ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ ﴿٣٤﴾ وَلَقَد تَّرَكۡنَا مِنۡهَآ ءَايَةَۢ بَيِّنَةٗ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٣٥﴾", "w": [["بالبشرى", "بإسحاق ومن بعده يعقوب."], ["هذه القرية", "قرية لوط، وهي سدوم."], ["نحن أعلم بمن فيها", "قالت الرسل."], ["من الغابرين", "الباقين في العذاب."], ["سيء بهم", "حصلت له مساءة وغمّ مخافة أن يقصدهم قومه."], ["وضاق بهم ذرعاً", "عجز عن احتمال الأمر لخوفه أن ينال قومه ضيفه."], ["رجزاً", "عذاباً من السماء."], ["بما كانوا يفسقون", "بسبب فسقهم، وهو إتيان الفاحشة."], ["ولقد تركنا منها آية", "خرابها ودمارها وتحوّلها إلى بحر ميت لا حياة فيه."], ["لقوم يعقلون", "يعلمون الأسباب والنتائج إذا تدبّروا."]], "m": "استجاب الله للوط، ولما جاءت الملائكة إبراهيم بالبشرى بإسحاق ومن ورائه يعقوب قالوا: إنا مهلكو أهل قرية لوط، إن أهلها كانوا ظالمين لأنفسهم بالفواحش ولغيرهم بقطع السبيل. قال إبراهيم: إن فيها لوطاً، وهو من الصالحين. قالوا: نحن أعلم بمن فيها منك، لننجّينّه وأهله إلا امرأته كانت من الباقين في العذاب لكفرها وموالاتها الظالمين. ولما جاءت الملائكة لوطاً استاء بهم وأصابه همّ خوفاً من أن يسيء قومه إلى ضيوفه، فقالوا: لا تخف ولا تحزن، إنا منجّوك وأهلك من العذاب إلا امرأتك، إنا منزلون على أهل هذه القرية عذاباً من السماء، وهو الحجارة، بسبب فسقهم. ولقد تركنا منها علامة واضحة على قدرتنا على إهلاك الظالمين لقوم يعقلون، أما من لا يعقل فهو كالبهيمة تنساق إلى المجزرة ولا تدري، وفي هذا تعريض بمشركي مكة.", "h": ["حلم إبراهيم ورحمته تجلّيا في دفاعه عن لوط وأهله.", "تقرير مبدأ: من بطّأ به عمله لم يُسرع به نسبه، فالعلاقة الزوجية بين لوط وامرأته لم تنفعها، وهلكت لأنها كانت مع الظالمين بقلبها وسلوكها.", "مشروعية الضيافة وتأكّدها في الإسلام، للحديث الصحيح: «من كان يؤمن بالله واليوم الآخر فليكرم ضيفه».", "التنديد بالفسق عن طاعة الله، وهو سبب هلاك الأمم والشعوب.", "فضيلة العقل إذا استعمله صاحبه في التعرّف إلى الحق والباطل والخير والشر."], "k": "«إلا امرأتك كانت من الغابرين»… قربها من نبي لم ينفعها؛ فما الذي ينفعني أنا غير عملي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 286;
insert into public.tdb_cards(topic, i, body) select 286, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٤ – ٢٥", "q": "فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٢٤﴾ وَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنٗا مَّوَدَّةَ بَيۡنِكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِينَ ﴿٢٥﴾", "w": [["فما كان جواب قومه", "قوم إبراهيم ﵇."], ["إلا أن قالوا اقتلوه أو حرّقوه", "إلا قولهم ذلك."], ["إن في ذلك لآيات", "في كون النار لم تحرق الخليل وخرج منها سالماً."], ["لقوم يؤمنون", "لأنهم المنتفعون بالآيات لحياة قلوبهم."], ["أوثاناً مودّة بينكم", "اتخذتم الأوثان آلهة تتوادّون من أجل عبادتها."], ["في الحياة الدنيا", "هذا التوادّ في الدنيا فقط."], ["يكفر بعضكم ببعض", "يكفر المتبوعون بأتباعهم ويتبرّؤون منهم."], ["ويلعن بعضكم بعضاً", "يلعن الأتباع القادة الذين اتّبعوهم في الباطل."]], "m": "لما أفحمهم إبراهيم بالحجة لجأوا، كعادة الطغاة، إلى القوة، فما كان جوابهم إلا أن قالوا: اقتلوه أو حرّقوه، فأوقدوا النار وألقوه فيها، فقال الله: «يا نار كوني برداً وسلاماً على إبراهيم»، فخرج سالماً لم تحرق النار إلا الحبل الذي شُدّ به، فأنجاه الله من النار، إن في ذلك لدلائل على قدرة الله ورحمته، لا ينتفع بها إلا المؤمنون لأنهم أحياء، والإيمان في القلب كالروح في البدن. وقال لهم: إنما اتخذتم من دون الله أوثاناً لأجل التوادّ والتحابّ والاجتماع عليها، تقيمون لها الأعياد فتأكلون وتشربون، لا أنكم تعتقدون حقاً أنها آلهة، ثم يوم القيامة ينعكس الأمر، فيكفر المتبوعون بأتباعهم، ويلعن بعضكم بعضاً عند معاينة العذاب، ومأواكم جميعاً النار، وما لكم من ناصرين.", "h": ["تقرير أن الظلمة سنّتهم أنهم إذا أعيتهم الحجج يلجأون إلى استعمال القوة.", "في عدم إحراق النار دليل على أن الله تعالى قادر على إبطال السنن إذا شاء، ومن هنا تكون الكرامات والمعجزات، إذ هي خوارق للعادات."], "k": "«مودّة بينكم في الحياة الدنيا»… أي صحبة في حياتي تقوم على ما يرضي الله، وأيها ستنقلب عداوة يومها؟"}, {"lbl": "الآيتان ٢٦ – ٢٧", "q": "۞فَـَٔامَنَ لَهُۥ لُوطٞۘ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٢٦﴾ وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ وَءَاتَيۡنَٰهُ أَجۡرَهُۥ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ ﴿٢٧﴾", "w": [["فآمن له لوط", "آمن بإبراهيم لوط ابن أخيه هاران."], ["إني مهاجر إلى ربي", "إلى حيث أعبد ربي فلا أُفتن في ديني."], ["ووهبنا له إسحاق ويعقوب", "أكرمناه في دار هجرته بإسحاق الابن ويعقوب الحفيد."], ["في ذريته النبوة والكتاب", "فكل الأنبياء بعده من ذريته، وكل الكتب التي أُنزلت بعده فيهم."], ["وآتيناه أجره في الدنيا", "بالرزق الطيب والثناء الحسن من أهل الأديان الإلهية."], ["وإنه في الآخرة لمن الصالحين", "أحدهم، فيُكرم كما يُكرمون بالدرجات العلا."]], "m": "هذا آخر قصص إبراهيم في هذا السياق: بعد الجهاد الطويل في الدعوة لم يؤمن له إلا لوط ابن أخيه، وقال إبراهيم: إني مهاجر إلى ربي، إنه هو العزيز الحكيم، فترك بلاد قومه في العراق وارتحل إلى الشام، ومن دلائل العزة أن أنجاه من الطغاة، ومن مظاهر الحكمة أن نقله إلى أرض كلها خير. فأكرمه الله جزاء هجرته: ووهبنا له إسحاق ويعقوب، وجعلنا في ذريته النبوة والكتاب، فالتوراة على موسى والزبور على داود والإنجيل على عيسى، وهم من ذريته، والقرآن على محمد ﷺ وهو من ذرية إسماعيل. وآتيناه أجره في الدنيا، فرزقه أطيب الأرزاق، والثناء الحسن من أهل الأديان كلها، وإنه في الآخرة لمن الصالحين ذوي الدرجات العلا.", "h": ["بيان حصيلة دعوة إبراهيم ﵇ سنين طويلة، وأنها كانت إيمان واحد بها، وهو لوط ﵇، وفي هذا تسلية للرسول ﷺ.", "بيان إكرام الله تعالى لمن يهاجر إليه ويترك أهله وداره.", "بيان ما أكرم الله تعالى به إبراهيم من خير الدنيا والآخرة جزاء صبره على الدعوة."], "k": "«إني مهاجر إلى ربي»… ما الذي أحتاج أن أهجره اليوم لأكون أقرب إليه؟"}, {"lbl": "الآيات ٢٨ – ٣٠", "q": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ﴿٢٨﴾ أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ ٱلسَّبِيلَ وَتَأۡتُونَ فِي نَادِيكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٢٩﴾ قَالَ رَبِّ ٱنصُرۡنِي عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِينَ ﴿٣٠﴾", "w": [["ولوطاً إذ قال لقومه", "واذكر لوطاً إذ قال لقومه أهل سدوم."], ["لتأتون الفاحشة", "الخصلة القبيحة، وهي إتيان الذكران."], ["ما سبقكم بها من أحد", "لم تعرف البشرية قبلهم هذه الفعلة."], ["وتقطعون السبيل", "باعتدائكم على المارّة، فامتنع الناس من المرور."], ["وتأتون في ناديكم المنكر", "في مجالس أحاديثكم تأتون المنكر من الأقوال والأفعال القبيحة."], ["فما كان جواب قومه", "إلا قولهم: ائتنا بعذاب الله إن كنت من الصادقين."]], "m": "هذا بداية قصص لوط ﵇ مع أهل سدوم وعمورية، تقريراً للنبوة المحمدية وتسلية للرسول: واذكر لوطاً إذ قال لقومه: إنكم لتأتون الفاحشة ما سبقكم بها أحد من العالمين، أئنّكم لتأتون الرجال، وتقطعون السبيل بالاعتداء على المارّة بالفاحشة قسراً وسلب أموالهم، فامتنع الناس من المرور، كما قطعتم بإتيان الذكران سبيل الولادة، وتأتون في مجالس اجتماعكم المنكر بارتكاب الفاحشة وأنواع العبث والسوء؟ فما كان جوابهم بعد أن وبّخهم إلا المطالبة بعذاب الله: ائتنا بعذاب الله إن كنت من الصادقين، وهذه طريقة الغلاة المفسدين إذا أعيتهم الحجج. فلجأ لوط إلى ربه: رب انصرني على القوم المفسدين، فاستجاب له.", "h": ["تقرير النبوة المحمدية بذكر قصص لا يتم إلا عن طريق الوحي.", "تسلية الرسول ﷺ من أجل ما يعاني من المشركين من كفر وعناد ومطالبة بالعذاب.", "قبح الفاحشة وحرمتها، وأسوؤها فاحشة اللواط.", "وجوب إقامة الحد على اللوطي الفاعل والمفعول، لأن الله تعالى سمّاها فاحشة كما سمّى الزنى، وقد صرّحت السنّة بذلك.", "التحذير من العبث والباطل قولاً أو عملاً، وخاصة في الأندية والمجتمعات."], "k": "«وتأتون في ناديكم المنكر»… مجالسي التي أجلسها، ماذا يُقال ويُفعل فيها؟"}, {"lbl": "الآيات ٣١ – ٣٥", "q": "وَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ ﴿٣١﴾ قَالَ إِنَّ فِيهَا لُوطٗاۚ قَالُواْ نَحۡنُ أَعۡلَمُ بِمَن فِيهَاۖ لَنُنَجِّيَنَّهُۥ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ ﴿٣٢﴾ وَلَمَّآ أَن جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗاۖ وَقَالُواْ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا ٱمۡرَأَتَكَ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ ﴿٣٣﴾ إِنَّا مُنزِلُونَ عَلَىٰٓ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ ﴿٣٤﴾ وَلَقَد تَّرَكۡنَا مِنۡهَآ ءَايَةَۢ بَيِّنَةٗ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٣٥﴾", "w": [["بالبشرى", "بإسحاق ومن بعده يعقوب."], ["هذه القرية", "قرية لوط، وهي سدوم."], ["نحن أعلم بمن فيها", "قالت الرسل."], ["من الغابرين", "الباقين في العذاب."], ["سيء بهم", "حصلت له مساءة وغمّ مخافة أن يقصدهم قومه."], ["وضاق بهم ذرعاً", "عجز عن احتمال الأمر لخوفه أن ينال قومه ضيفه."], ["رجزاً", "عذاباً من السماء."], ["بما كانوا يفسقون", "بسبب فسقهم، وهو إتيان الفاحشة."], ["ولقد تركنا منها آية", "خرابها ودمارها وتحوّلها إلى بحر ميت لا حياة فيه."], ["لقوم يعقلون", "يعلمون الأسباب والنتائج إذا تدبّروا."]], "m": "استجاب الله للوط، ولما جاءت الملائكة إبراهيم بالبشرى بإسحاق ومن ورائه يعقوب قالوا: إنا مهلكو أهل قرية لوط، إن أهلها كانوا ظالمين لأنفسهم بالفواحش ولغيرهم بقطع السبيل. قال إبراهيم: إن فيها لوطاً، وهو من الصالحين. قالوا: نحن أعلم بمن فيها منك، لننجّينّه وأهله إلا امرأته كانت من الباقين في العذاب لكفرها وموالاتها الظالمين. ولما جاءت الملائكة لوطاً استاء بهم وأصابه همّ خوفاً من أن يسيء قومه إلى ضيوفه، فقالوا: لا تخف ولا تحزن، إنا منجّوك وأهلك من العذاب إلا امرأتك، إنا منزلون على أهل هذه القرية عذاباً من السماء، وهو الحجارة، بسبب فسقهم. ولقد تركنا منها علامة واضحة على قدرتنا على إهلاك الظالمين لقوم يعقلون، أما من لا يعقل فهو كالبهيمة تنساق إلى المجزرة ولا تدري، وفي هذا تعريض بمشركي مكة.", "h": ["حلم إبراهيم ورحمته تجلّيا في دفاعه عن لوط وأهله.", "تقرير مبدأ: من بطّأ به عمله لم يُسرع به نسبه، فالعلاقة الزوجية بين لوط وامرأته لم تنفعها، وهلكت لأنها كانت مع الظالمين بقلبها وسلوكها.", "مشروعية الضيافة وتأكّدها في الإسلام، للحديث الصحيح: «من كان يؤمن بالله واليوم الآخر فليكرم ضيفه».", "التنديد بالفسق عن طاعة الله، وهو سبب هلاك الأمم والشعوب.", "فضيلة العقل إذا استعمله صاحبه في التعرّف إلى الحق والباطل والخير والشر."], "k": "«إلا امرأتك كانت من الغابرين»… قربها من نبي لم ينفعها؛ فما الذي ينفعني أنا غير عملي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (287, 29, 36, 45, 'سورة العنكبوت ٣٦ – ٤٥', '«وإلى مدين أخاهم شعيباً»، و«فكلّاً أخذنا بذنبه»، و«مثل الذين اتخذوا من دون الله أولياء كمثل العنكبوت»، و«إن الصلاة تنهى عن الفحشاء والمنكر»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 287) = $j$[{"lbl": "الآيتان ٣٦ – ٣٧", "q": "وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗا فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ وَٱرۡجُواْ ٱلۡيَوۡمَ ٱلۡأٓخِرَ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ﴿٣٦﴾ فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ﴿٣٧﴾", "w": [["وإلى مدين", "وأرسلنا إلى قبيلة مدين، ومدين أبو القبيلة."], ["أخاهم شعيباً", "أخاهم في النسب."], ["اعبدوا الله", "اعبدوه وحده ولا تشركوا به شيئاً."], ["وارجوا اليوم الآخر", "آمنوا به وتوقّعوا مجيئه وما يحدث فيه."], ["ولا تعثوا في الأرض مفسدين", "لا تنشروا فيها الفساد بالعمل بالمعاصي."], ["فأخذتهم الرجفة", "الهزّة العنيفة والزلزلة الشديدة."], ["في دارهم جاثمين", "لاصقين بالأرض أمواتاً لا يتحركون."]], "m": "هذا موجز قصة شعيب ﵇ مع أهل مدين، والعبرة منه إهلاك تلك الأمة لما كذّبت رسولها، لعل قريشاً تعتبر: وأرسلنا إلى مدين أخاهم شعيباً، فقال: يا قوم اعبدوا الله وحده وأطيعوه فيما يأمركم به وينهاكم عنه من التطفيف في الكيل والوزن، وآمنوا باليوم الآخر وتوقّعوا مجيئه وخافوا أهواله، فإن ذلك يعينكم على التقوى، ولا تفسدوا في الأرض بنقص الكيل والوزن وبخس الناس أشياءهم والمعاصي. فكذّبوه، فأخذتهم رجفة الهلاك من تحتهم فأصبحوا في دارهم جاثمين هلكى، وما ظلمهم الله ولكن كانوا هم الظالمين.", "h": ["تقرير التوحيد والنبوة والبعث الآخر.", "حرمة الفساد في الأرض، وذلك بارتكاب المعاصي وغشيان الذنوب.", "بيان نقمة الله تعالى على المكذّبين والظالمين والفاسقين."], "k": "«وارجوا اليوم الآخر»… الرجاء في الآخرة يُصلح الميزان في الدنيا؛ فهل يظهر رجائي في معاملاتي؟"}, {"lbl": "الآيات ٣٨ – ٤٠", "q": "وَعَادٗا وَثَمُودَاْ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمۡۖ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ ﴿٣٨﴾ وَقَٰرُونَ وَفِرۡعَوۡنَ وَهَٰمَٰنَۖ وَلَقَدۡ جَآءَهُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ وَمَا كَانُواْ سَٰبِقِينَ ﴿٣٩﴾ فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَيۡهِ حَاصِبٗا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّيۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٤٠﴾", "w": [["وعاداً وثمود", "وأهلكنا عاداً وثمود كذلك."], ["وقد تبيّن لكم من مساكنهم", "تبيّن لكم إهلاكهم من مساكنهم الخالية بالحِجر شمال الحجاز، والشِّحر جنوب اليمن."], ["فصدّهم عن السبيل", "سبيل الهدى والحق التي بيّنتها لهم رسلهم."], ["وكانوا مستبصرين", "ذوي بصائر لما علّمتهم رسلهم."], ["وقارون وفرعون وهامان", "وأهلكنا قارون بالخسف، وفرعون وهامان بالغرق."], ["وما كانوا سابقين", "فائتين عذاب الله، بل أدركهم."], ["حاصباً", "ريحاً شديدة، كعاد."], ["ومنهم من أخذته الصيحة", "ثمود."], ["ومنهم من خسفنا به الأرض", "قارون."], ["ومنهم من أغرقنا", "قوم نوح وفرعون."]], "m": "بعد ذكر إهلاك قوم لوط وشعيب ونوح ذكر بقية المكذّبين: وأهلكنا عاداً قوم هود وثمود قوم صالح، وقد تبيّن لكم يا مشركي قريش من مساكنهم الخاوية بالحِجر والشِّحر ما يؤكد إهلاكنا لهم، وزيّن لهم الشيطان أعمالهم من الشرك والظلم فصدّهم عن سبيل الإيمان، وكانوا ذوي بصائر يعرفون الحق والباطل لما علّمتهم الرسل، ولكن آثروا أهواءهم على عقولهم. وأهلكنا قارون ببغيه وكفره، وفرعون وهامان بكفرهما وظلمهما، بعدما جاءهم موسى بالبيّنات، فاستكبروا في أرض مصر وما كانوا فائتين. فكلّاً أخذنا بذنبه: فمنهم من أرسلنا عليه ريحاً شديدة كعاد، ومنهم من أخذته الصيحة كثمود، ومنهم من خسفنا به الأرض كقارون، ومنهم من أغرقنا كقوم نوح وفرعون، وما كان الله ليظلمهم، ولكن كانوا أنفسهم يظلمون بالشرك والتكذيب والمعاصي.", "h": ["بيان أن الشيطان هو سبب هلاك الأقوام، بتزيينه لهم الشر والقبيح كالشرك والباطل والفساد.", "بيان أن الاستكبار كالظلم، عاقبتهما الهلاك والخسران.", "بيان أن الله تعالى ما أهلك أمة حتى يبيّن لها ما يجب أن تتّقيه من أسباب الهلاك، فإذا أبت إلا ذاك أوردها موارده."], "k": "«وكانوا مستبصرين»… العلم وحده لم ينجهم حين آثروا الهوى؛ فهل أعمل بما أعرف؟"}, {"lbl": "الآيات ٤١ – ٤٥", "q": "مَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٤١﴾ إِنَّ ٱللَّهَ يَعۡلَمُ مَا يَدۡعُونَ مِن دُونِهِۦ مِن شَيۡءٖۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٤٢﴾ وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ ﴿٤٣﴾ خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ ﴿٤٤﴾ ٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ يَعۡلَمُ مَا تَصۡنَعُونَ ﴿٤٥﴾", "w": [["مثل الذين اتخذوا من دون الله أولياء", "صفة الذين اتخذوا أصناماً يرجون نفعها."], ["كمثل العنكبوت اتخذت بيتاً", "لنفسها تأوي إليه."], ["أوهن البيوت", "أضعفها وأقلّها جدوى."], ["وما يعقلها إلا العالمون", "العالمون بالله وآياته وأحكام شرعه وأسراره."], ["خلق الله السماوات والأرض بالحق", "من أجل أن يُعبد، لا للهو ولا لباطل."], ["اتلُ ما أوحي إليك من الكتاب", "اقرأ ما أُنزل إليك من القرآن."], ["وأقم الصلاة", "بأدائها مراعى فيها شروطها وأركانها وواجباتها وسننها."], ["تنهى عن الفحشاء والمنكر", "بما توجده من نور في القلب يصبح العبد معه لا يقدر على فعل فاحشة ولا إتيان منكر."], ["ولذكر الله أكبر", "ذكر الله عبده أكبر من ذكر العبد ربه، وذكر الله أكبر في النهي عن الفحشاء من الصلاة."]], "m": "بعد ذكر نقمته على أعدائه ضرب مثلاً لعبادة الأوثان في عدم نفعها: مثل الذين اتخذوا من دون الله أصناماً يرجون نفعها وشفاعتها كمثل العنكبوت اتخذت بيتاً تأوي إليه تتّقي به البرد والاعتداء، وإن أضعف البيوت وأقلّها مناعة لبيت العنكبوت، فهم واهمون، إذ لا ينفع ولا يضر إلا الله، لو كانوا يعلمون ذلك لما رضوا بعبادة غيره. إن الله يعلم ما يدعون من دونه، وهو العزيز الحكيم، يعجّل العقوبة لمن يشاء ويؤخّرها لحكمة، فلا يغترّوا بتأخيرها. وتلك الأمثال نضربها للناس، وما يدرك مغزاها إلا العالمون بالله وشرعه. خلق الله السماوات والأرض بالحق لا بالباطل، من أجل أن يُذكر ويُشكر، إن في ذلك لآية للمؤمنين. فاتلُ ما أوحي إليك من القرآن، وأقم الصلاة، فإنها عون كبير على الصبر والثبات، إن الصلاة تنهى عن الفحشاء والمنكر بما توجده من إشراق في النفس، وإقامتها بالإخلاص فيها، وحضور القلب، وأدائها في أوقاتها في بيوت الله مع الجماعة، ومراعاة أركانها، وآخرها الخشوع، ولذكر الله بالقلب واللسان في كل الأحيان أكبر في النهي عن الفحشاء من الصلاة، وذكر الله عبده في الملأ الأعلى أكبر من ذكر العبد ربه، والله يعلم ما تصنعون فيجزيكم به.", "h": ["تقرير التوحيد وإبطال التنديد.", "فضل العلماء بالله وصفاته وأسمائه وآياته وشرائعه وأسرارها على غيرهم.", "وجوب تلاوة القرآن وإقامة الصلاة وذكر الله، إذ هي غذاء الروح.", "بيان فائدة إقام الصلاة وتلاوة القرآن وذكر الله تعالى بالقلب واللسان."], "k": "«إن الصلاة تنهى عن الفحشاء والمنكر»… إن لم تنهني صلاتي، فما الذي ينقصها من الإقامة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 287;
insert into public.tdb_cards(topic, i, body) select 287, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٣٦ – ٣٧", "q": "وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗا فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ وَٱرۡجُواْ ٱلۡيَوۡمَ ٱلۡأٓخِرَ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ﴿٣٦﴾ فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ﴿٣٧﴾", "w": [["وإلى مدين", "وأرسلنا إلى قبيلة مدين، ومدين أبو القبيلة."], ["أخاهم شعيباً", "أخاهم في النسب."], ["اعبدوا الله", "اعبدوه وحده ولا تشركوا به شيئاً."], ["وارجوا اليوم الآخر", "آمنوا به وتوقّعوا مجيئه وما يحدث فيه."], ["ولا تعثوا في الأرض مفسدين", "لا تنشروا فيها الفساد بالعمل بالمعاصي."], ["فأخذتهم الرجفة", "الهزّة العنيفة والزلزلة الشديدة."], ["في دارهم جاثمين", "لاصقين بالأرض أمواتاً لا يتحركون."]], "m": "هذا موجز قصة شعيب ﵇ مع أهل مدين، والعبرة منه إهلاك تلك الأمة لما كذّبت رسولها، لعل قريشاً تعتبر: وأرسلنا إلى مدين أخاهم شعيباً، فقال: يا قوم اعبدوا الله وحده وأطيعوه فيما يأمركم به وينهاكم عنه من التطفيف في الكيل والوزن، وآمنوا باليوم الآخر وتوقّعوا مجيئه وخافوا أهواله، فإن ذلك يعينكم على التقوى، ولا تفسدوا في الأرض بنقص الكيل والوزن وبخس الناس أشياءهم والمعاصي. فكذّبوه، فأخذتهم رجفة الهلاك من تحتهم فأصبحوا في دارهم جاثمين هلكى، وما ظلمهم الله ولكن كانوا هم الظالمين.", "h": ["تقرير التوحيد والنبوة والبعث الآخر.", "حرمة الفساد في الأرض، وذلك بارتكاب المعاصي وغشيان الذنوب.", "بيان نقمة الله تعالى على المكذّبين والظالمين والفاسقين."], "k": "«وارجوا اليوم الآخر»… الرجاء في الآخرة يُصلح الميزان في الدنيا؛ فهل يظهر رجائي في معاملاتي؟"}, {"lbl": "الآيات ٣٨ – ٤٠", "q": "وَعَادٗا وَثَمُودَاْ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمۡۖ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ ﴿٣٨﴾ وَقَٰرُونَ وَفِرۡعَوۡنَ وَهَٰمَٰنَۖ وَلَقَدۡ جَآءَهُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ وَمَا كَانُواْ سَٰبِقِينَ ﴿٣٩﴾ فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَيۡهِ حَاصِبٗا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّيۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٤٠﴾", "w": [["وعاداً وثمود", "وأهلكنا عاداً وثمود كذلك."], ["وقد تبيّن لكم من مساكنهم", "تبيّن لكم إهلاكهم من مساكنهم الخالية بالحِجر شمال الحجاز، والشِّحر جنوب اليمن."], ["فصدّهم عن السبيل", "سبيل الهدى والحق التي بيّنتها لهم رسلهم."], ["وكانوا مستبصرين", "ذوي بصائر لما علّمتهم رسلهم."], ["وقارون وفرعون وهامان", "وأهلكنا قارون بالخسف، وفرعون وهامان بالغرق."], ["وما كانوا سابقين", "فائتين عذاب الله، بل أدركهم."], ["حاصباً", "ريحاً شديدة، كعاد."], ["ومنهم من أخذته الصيحة", "ثمود."], ["ومنهم من خسفنا به الأرض", "قارون."], ["ومنهم من أغرقنا", "قوم نوح وفرعون."]], "m": "بعد ذكر إهلاك قوم لوط وشعيب ونوح ذكر بقية المكذّبين: وأهلكنا عاداً قوم هود وثمود قوم صالح، وقد تبيّن لكم يا مشركي قريش من مساكنهم الخاوية بالحِجر والشِّحر ما يؤكد إهلاكنا لهم، وزيّن لهم الشيطان أعمالهم من الشرك والظلم فصدّهم عن سبيل الإيمان، وكانوا ذوي بصائر يعرفون الحق والباطل لما علّمتهم الرسل، ولكن آثروا أهواءهم على عقولهم. وأهلكنا قارون ببغيه وكفره، وفرعون وهامان بكفرهما وظلمهما، بعدما جاءهم موسى بالبيّنات، فاستكبروا في أرض مصر وما كانوا فائتين. فكلّاً أخذنا بذنبه: فمنهم من أرسلنا عليه ريحاً شديدة كعاد، ومنهم من أخذته الصيحة كثمود، ومنهم من خسفنا به الأرض كقارون، ومنهم من أغرقنا كقوم نوح وفرعون، وما كان الله ليظلمهم، ولكن كانوا أنفسهم يظلمون بالشرك والتكذيب والمعاصي.", "h": ["بيان أن الشيطان هو سبب هلاك الأقوام، بتزيينه لهم الشر والقبيح كالشرك والباطل والفساد.", "بيان أن الاستكبار كالظلم، عاقبتهما الهلاك والخسران.", "بيان أن الله تعالى ما أهلك أمة حتى يبيّن لها ما يجب أن تتّقيه من أسباب الهلاك، فإذا أبت إلا ذاك أوردها موارده."], "k": "«وكانوا مستبصرين»… العلم وحده لم ينجهم حين آثروا الهوى؛ فهل أعمل بما أعرف؟"}, {"lbl": "الآيات ٤١ – ٤٥", "q": "مَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٤١﴾ إِنَّ ٱللَّهَ يَعۡلَمُ مَا يَدۡعُونَ مِن دُونِهِۦ مِن شَيۡءٖۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٤٢﴾ وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ ﴿٤٣﴾ خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ ﴿٤٤﴾ ٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ يَعۡلَمُ مَا تَصۡنَعُونَ ﴿٤٥﴾", "w": [["مثل الذين اتخذوا من دون الله أولياء", "صفة الذين اتخذوا أصناماً يرجون نفعها."], ["كمثل العنكبوت اتخذت بيتاً", "لنفسها تأوي إليه."], ["أوهن البيوت", "أضعفها وأقلّها جدوى."], ["وما يعقلها إلا العالمون", "العالمون بالله وآياته وأحكام شرعه وأسراره."], ["خلق الله السماوات والأرض بالحق", "من أجل أن يُعبد، لا للهو ولا لباطل."], ["اتلُ ما أوحي إليك من الكتاب", "اقرأ ما أُنزل إليك من القرآن."], ["وأقم الصلاة", "بأدائها مراعى فيها شروطها وأركانها وواجباتها وسننها."], ["تنهى عن الفحشاء والمنكر", "بما توجده من نور في القلب يصبح العبد معه لا يقدر على فعل فاحشة ولا إتيان منكر."], ["ولذكر الله أكبر", "ذكر الله عبده أكبر من ذكر العبد ربه، وذكر الله أكبر في النهي عن الفحشاء من الصلاة."]], "m": "بعد ذكر نقمته على أعدائه ضرب مثلاً لعبادة الأوثان في عدم نفعها: مثل الذين اتخذوا من دون الله أصناماً يرجون نفعها وشفاعتها كمثل العنكبوت اتخذت بيتاً تأوي إليه تتّقي به البرد والاعتداء، وإن أضعف البيوت وأقلّها مناعة لبيت العنكبوت، فهم واهمون، إذ لا ينفع ولا يضر إلا الله، لو كانوا يعلمون ذلك لما رضوا بعبادة غيره. إن الله يعلم ما يدعون من دونه، وهو العزيز الحكيم، يعجّل العقوبة لمن يشاء ويؤخّرها لحكمة، فلا يغترّوا بتأخيرها. وتلك الأمثال نضربها للناس، وما يدرك مغزاها إلا العالمون بالله وشرعه. خلق الله السماوات والأرض بالحق لا بالباطل، من أجل أن يُذكر ويُشكر، إن في ذلك لآية للمؤمنين. فاتلُ ما أوحي إليك من القرآن، وأقم الصلاة، فإنها عون كبير على الصبر والثبات، إن الصلاة تنهى عن الفحشاء والمنكر بما توجده من إشراق في النفس، وإقامتها بالإخلاص فيها، وحضور القلب، وأدائها في أوقاتها في بيوت الله مع الجماعة، ومراعاة أركانها، وآخرها الخشوع، ولذكر الله بالقلب واللسان في كل الأحيان أكبر في النهي عن الفحشاء من الصلاة، وذكر الله عبده في الملأ الأعلى أكبر من ذكر العبد ربه، والله يعلم ما تصنعون فيجزيكم به.", "h": ["تقرير التوحيد وإبطال التنديد.", "فضل العلماء بالله وصفاته وأسمائه وآياته وشرائعه وأسرارها على غيرهم.", "وجوب تلاوة القرآن وإقامة الصلاة وذكر الله، إذ هي غذاء الروح.", "بيان فائدة إقام الصلاة وتلاوة القرآن وذكر الله تعالى بالقلب واللسان."], "k": "«إن الصلاة تنهى عن الفحشاء والمنكر»… إن لم تنهني صلاتي، فما الذي ينقصها من الإقامة؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;